local System = require("System.System")
local readonly = System.readonly
local AwakerStory = readonly({
  [11169] = {
    ID = 11169,
    CnID = "唤醒体故事@美德骑士·简介",
    BaseSortID = 1,
    ActorIndex = 15585,
    Title = "AwakerStory_11169_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11169_Content|一言一行践行忠贞，一举一动贯彻美德。\n尽管「知礼守义，严于律己」已经深深刻在魂灵之上，但这名美德骑士，无疑还是孩童的样貌。\n不过还请别担心，即便代价是永远的消亡，奥吉尔也会拼尽全力完成主君的指令。\n愿那日永远不要来临。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11169_UnlockDesc|唤醒体等级达到1级"
  },
  [11286] = {
    ID = 11286,
    CnID = "唤醒体故事@美德骑士·故事一",
    BaseSortID = 2,
    ActorIndex = 15585,
    Title = "AwakerStory_11286_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11286_Content|A.F.2@2年11月，贝伦地区发生大地震。\n次日，两名教授受命动身前往震区，寻找震后失去联络的弥萨格调查员小队。\n该小队失联前活跃于陆间海沿岸，主要任务为勘探、发掘历史遗迹，寻找与「融蚀现象」相关的可能线索。\n11月8日，在据传最后目击到小队成员的地点，@2教授发现了一处未被史料记载的行宫遗址，回收了一把弥萨格制式银钥，编号为I-@2，但并未找到小队成员。\n11月9日，于遗址中出土了两份银芯，后带回伦蒂尼恩，因其历史价值而被封存，另择日唤醒。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11286_UnlockDesc|同调率等级达到3"
  },
  [11343] = {
    ID = 11343,
    CnID = "唤醒体故事@美德骑士·故事二",
    BaseSortID = 3,
    ActorIndex = 15585,
    Title = "AwakerStory_11343_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11343_Content|「如果你是第一次执行调查任务，那么就去找小奥吉尔同行吧！」\n面对新人调查员的不安情绪，有经验的前辈们总会给出这样的建议。奥吉尔在师生间受欢迎的程度，由此可见一斑。\n虽然他老古董似的性子偶尔也会闹出些小插曲，但相互扶持，互为支撑，奥吉尔总能与调查员达成最和谐的节奏。近些年，让奥吉尔陪同新人调查员执行第一次任务，更是成为了校内所有人的共识。诸如「奥吉尔会为女调查员准备披风」、「奥吉尔看见大腿会脸红」的笑谈，也在学生间流传开来。\n「死亡骑士」的称号也逐渐被人遗忘，被信任与温暖淹没，只余一根微小的棘刺扎在少年心中。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11343_UnlockDesc|同调率等级达到5"
  },
  [11279] = {
    ID = 11279,
    CnID = "唤醒体故事@美德骑士·故事三",
    BaseSortID = 4,
    ActorIndex = 15585,
    Title = "AwakerStory_11279_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11279_Content|少年一度被称为「死亡骑士」的事，校内已经没有多少人记得了。\n只在午夜时分，那日的光景会变成恶魇，潜入少年的梦境。\n入侵校园的融蚀体，倒塌的钟楼，奄奄一息的「守密人」。\n「别哭，奥吉尔，这不是你的错……」\n入侵家园的铁骑，倾颓的行宫，从公主指间流下的黑血。\n「别为了我牺牲，奥吉尔，你做的已经够多了……」\n记忆的砂砾裹挟痛苦，冲刷着少年的魂灵。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11279_UnlockDesc|同调率等级达到7"
  },
  [11375] = {
    ID = 11375,
    CnID = "唤醒体故事@美德骑士·故事四",
    BaseSortID = 5,
    ActorIndex = 15585,
    Title = "AwakerStory_11375_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11375_Content|——这怎能不是他的错？他做的还远远不够。\n怀着这样极端自责的情绪，奥吉尔执行任务的频率是其他唤醒体的两倍，用人人称赞的「美德」埋葬「死亡」。\n过量的工作与年轻调查员感激的话语，仿佛真的能洗去刻在灵魂中的悲痛。\n沉疴被推挤进了内心的阴影中，祂们散发着腐烂的恶臭，暗中牵引着骑士走向深黑泥沼。\n「抱歉？您好？」\n有人带着一缕阳光，或是一阵微风，来到了奥吉尔面前。\n「前辈说，奥吉尔会加入我和拉蒙娜，一同执行我的初次调查任务，对吗？」\n他无法保护公主第二次，但上天给了他再次守护「守密人」的机会。\n「我的名字是奥吉尔，很荣幸能与您缔结契约。我将用灵魂护卫您的生命，今日誓言，永志不忘。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11375_UnlockDesc|同调率等级达到9"
  },
  [11289] = {
    ID = 11289,
    CnID = "唤醒体故事@鲸跃·简介",
    BaseSortID = 6,
    ActorIndex = 15569,
    Title = "AwakerStory_11289_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11289_Content|萝坦身上贴了太多太多标签，没人知道该用怎样的态度来与这名黑衣剑士相处。\n太过谦卑，她会以无趣之名敲碎你的膝盖；太过傲慢，她会用巨剑斩断你的无礼；太过强硬，她会用战斗软化你的灵魂。\n但也许，这正是星球初生之子的傲慢：作为曾经的守护者，她理应享有傲慢的权利。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11289_UnlockDesc|唤醒体等级达到1级"
  },
  [11304] = {
    ID = 11304,
    CnID = "唤醒体故事@鲸跃·故事一",
    BaseSortID = 7,
    ActorIndex = 15569,
    Title = "AwakerStory_11304_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11304_Content|A.F.180年，在北半球大干旱的影响下，卡拉苏河出现断流。\n当地居民从河床淤泥中挖掘出一具怪物骨架，因卡拉苏河在当地文化中有「混水」之意，该骨架被命名为「混沌之骨」。\n经海洋生物学者鉴定，这是一具大翅鲸骨架，长约32英尺，通体被一种银色物质覆盖。次年，该骨架于伊希斯拍卖会上以1.3亿雷欧坊的价格拍出。\n交易行拒绝透露买受人真实身份，但小道消息称，这具骨架被运往了伦蒂尼恩市郊一所私立大学。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11304_UnlockDesc|同调率等级达到3"
  },
  [11161] = {
    ID = 11161,
    CnID = "唤醒体故事@鲸跃·故事二",
    BaseSortID = 8,
    ActorIndex = 15569,
    Title = "AwakerStory_11161_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11161_Content|弥萨格大学里，「预科生必须要和萝坦战斗才能成为调查员」的校园传说愈演愈烈，让学生们对黑衣女剑士的恐惧达到了极点。不少专精于理论研究的学生光看见黑色裙角都会被吓出一身冷汗，生怕和「战斗狂」对上视线，命丧训练场。\n主编汉娜·皮斯利与当事人进行了一场简短的特约访谈，访谈中，萝坦小姐作出了如下发言：\n「我可没那么多时间陪婴儿玩过家家。」\n「软脚虾不配成为我的对手——你是其中之一吗？还是说，你也拥有直面混沌的胆量？」\n\n——截至发稿日前，主编都没有离开过学生宿舍。本期《M大校报》由实习编辑霍华德进行印刷与发行。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11161_UnlockDesc|同调率等级达到5"
  },
  [11327] = {
    ID = 11327,
    CnID = "唤醒体故事@鲸跃·故事三",
    BaseSortID = 9,
    ActorIndex = 15569,
    Title = "AwakerStory_11327_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11327_Content|在挑选对手这件事上，萝坦自有一套标准。\n学院派战士大多读书读坏了脑子，想的全是纸上把式，令人厌烦。\n军队中的佼佼者又往往受繁文缛节、道德礼教束缚，倍感无趣。\n只有那些天赐才华、战斗本能与生俱来的奇才，才能得她青眼。\n与星球同寿的巨兽按捺着战斗的欲望，近乎虔诚地等待着认定的对手成长至巅峰——那是多么具有天资的一个少年啊。他号令来自深海的力量，强悍的灵甚至能与界外神明连接，假以时日，他一定能成长为令人垂涎的强者。\n但，许是漫长的时间折损了她的判断力，这一次，混沌之灵看走了眼。诸多种种，萝坦不愿再向任何人提起。\n我们只知道，从那以后，她对任何「不求上进」、「不思进取」之人嗤之以鼻。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11327_UnlockDesc|同调率等级达到7"
  },
  [11307] = {
    ID = 11307,
    CnID = "唤醒体故事@鲸跃·故事四",
    BaseSortID = 10,
    ActorIndex = 15569,
    Title = "AwakerStory_11307_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11307_Content|作为诞生于混沌中的生命，她是纯粹的混沌力量，是不羁的自由灵魂，亦是未被定义的秩序。\n需要挑战、需要战斗，只有难以遏制的破坏欲得到释放，她才能完成创造者对她的唯一嘱托。\n——为了守望星球直至末日，她渴望一场酣畅的战斗太久了。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11307_UnlockDesc|同调率等级达到9"
  },
  [11342] = {
    ID = 11342,
    CnID = "唤醒体故事@知者·简介",
    BaseSortID = 11,
    ActorIndex = 15595,
    Title = "AwakerStory_11342_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11342_Content|唤醒体资料管理人几度将她的档案转入学生管理处，但又屡次被她亲手送回，埋没书山卷海之下。\n「放这里就可以了，终究有一天要送过来的。」\n她的语气一如既往平静，眼神却闪烁不定。\n\n这平静之下，藏着怎样磅礴的情绪呢？",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11342_UnlockDesc|唤醒体等级达到1级"
  },
  [11209] = {
    ID = 11209,
    CnID = "唤醒体故事@知者·故事一",
    BaseSortID = 12,
    ActorIndex = 15595,
    Title = "AwakerStory_11209_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11209_Content|拉蒙娜首次出现在校园时，掀起了轩然大波。\n在唤醒体遍地走、怪人随处可见的弥萨格大学，银发异瞳并不是什么值得在意的特征。使拉蒙娜成为谈资的，是她「教授之女」的身份。\n所有人都堵在数学系办公室前，希望一睹德克斯特大小姐的风采。人实在是太多，教授不得不求助萝坦小姐，才让众人悻悻散去。\n等拉蒙娜长大了一些，教授也终于放心撒手让她在校园里乱跑时，那些被萝坦赶走的学生才又找到了向她搭话的机会。\n「勋爵夫人是怎样的人？抱歉，这个人物暂时还不存在。我是个孤儿，是父亲好心收养了我。」\n为了摆脱纠缠，小小女孩从容地说出实情，在众人陷入愧疚中时，施施然离开。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11209_UnlockDesc|同调率等级达到3"
  },
  [11257] = {
    ID = 11257,
    CnID = "唤醒体故事@知者·故事二",
    BaseSortID = 13,
    ActorIndex = 15595,
    Title = "AwakerStory_11257_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11257_Content|拉蒙娜十岁开始，就成为了大学训练场的常客。敢以人类之身接受黑衣剑士指导的她，成为了诸多调查员钦佩的对象。\n在正式接受预科课程后，凭着过目不忘的本领、满分的试卷、优雅而致命的剑技，拉蒙娜在弥萨格的地位水涨船高，自律和优秀成了她的代名词。\n但令很多人不解的是，明明如此优秀，拉蒙娜却始终没有获得独立执行任务的资格。提前入学的她甚至接受了足足五年预科课程，目送了一批又一批调查员投身神秘学世界。\n她到底在等待什么呢？到底被赋予了怎样的使命呢？\n这个问题在新一任守密人入学后，得到了解答。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11257_UnlockDesc|同调率等级达到5"
  },
  [11205] = {
    ID = 11205,
    CnID = "唤醒体故事@知者·故事三",
    BaseSortID = 14,
    ActorIndex = 15595,
    Title = "AwakerStory_11205_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11205_Content|梦境是记忆的投射，是日常生活的缩影，是人类本身的总集。\n从幼时起，拉蒙娜就时常做着同一个梦。\n置身温暖而浑浊的水中，她与未知唇齿相依，空洞单调的鼓点在水中荡起圈圈涟漪。\n梦醒后，心中某处总感觉空空落落，仿佛某个存在被从她的生命中夺走、抹除。\n但为了不让父亲露出担忧的神情，为了不给本就忙碌的师长再添麻烦，拉蒙娜吞下几乎跳出喉咙的疑问，回到日常中去。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11205_UnlockDesc|同调率等级达到7"
  },
  [11226] = {
    ID = 11226,
    CnID = "唤醒体故事@知者·故事四",
    BaseSortID = 15,
    ActorIndex = 15595,
    Title = "AwakerStory_11226_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11226_Content|她什么都知道。\n她知道钟楼会在紧急时刻鸣响，知道波江座流星雨会在十年后到来，知道自己体内流淌着不一样的力量。\n她什么都不知道。\n她不知道食堂咖喱配方中的秘制香料，不知道如何计算星球湮灭后的半径，不知道自己的未来会被拉扯向何方。\n她难以割舍身边的一切，又难以抵抗直觉为她指引的道路。\n在通往真相与真理的旅途中，拉蒙娜需要与坚定之人同行，为她守住回归日常之路。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11226_UnlockDesc|同调率等级达到9"
  },
  [11165] = {
    ID = 11165,
    CnID = "唤醒体故事@缸中之脑·简介",
    BaseSortID = 16,
    ActorIndex = 15570,
    Title = "AwakerStory_11165_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11165_Content|用过的烧瓶要清洗如新，被实验烧坏的桌子要打磨到反光，天平每三日就要重新校准。出于对科学、对世界奥秘的狂热与尊重，她对身边的人与事都保持着极高要求。\n当然，这要求也适用于她自己——毕竟，不是所有人都能平静拥抱死亡，主动要求成为唤醒体的。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11165_UnlockDesc|唤醒体等级达到1级"
  },
  [11367] = {
    ID = 11367,
    CnID = "唤醒体故事@缸中之脑·故事一",
    BaseSortID = 17,
    ActorIndex = 15570,
    Title = "AwakerStory_11367_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11367_Content|朵尔是弥萨格大学，乃至整个学界都不可或缺的人物。\n在为学校所管理的唤醒体中，朵尔不是诺斯指数最稳定的，也不是战斗能力最强的，但她一定是最冷静、最理智的那一个。\n对一些曾为人类的唤醒体而言，「死而复生」初期通常伴随着迷惘、恐慌和狂躁等情绪。然而，朵尔似乎并未受到如此「阵痛期」的影响。\n在被唤醒的第二天，她就再度投身实验室，于一年内编纂出了集外域知识与人类智慧大成的技术手册。\n目前的朵尔，一半的时间用于革新「银芯科技」，一半的时间用于「给愚蠢的学生收拾残局」。\n——顺便一提，基于高维存在的影响，朵尔在书写那本《技术手册》时使用了某种未知语言，翻译工作正在朵尔的闲暇时间中有序进行。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11367_UnlockDesc|同调率等级达到3"
  },
  [11309] = {
    ID = 11309,
    CnID = "唤醒体故事@缸中之脑·故事二",
    BaseSortID = 18,
    ActorIndex = 15570,
    Title = "AwakerStory_11309_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11309_Content|「不留情面的评语」、「低分的试卷」、「不合格的研究报告」\n在朵尔数十年的执教生涯里，从她手中取得结业证书的学生屈指可数。大多数学生都被其过于严苛的态度逼退，转投其他教授门下。久而久之，朵尔教授的恶名便在学生间流传开来。\n但也有学生相信，她只是在用这个标准来挑选「门徒」。只有意志最坚毅的人，才配握住打开真理之门的钥匙，跟随她一同揭开世界真实的面纱。\n在如此信念的支撑下，即便从朵尔手下毕业的可能性微乎其微，希望被朵尔带教的申请书仍络绎不绝地飞入办公室。\n有时，被临时叫来审阅申请书的拉蒙娜不禁会想，学生们若是如此相信，也挺不错的。\n在拉蒙娜看来，她只是在以唤醒体之身的标准来要求人类学生，仅此而已。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11309_UnlockDesc|同调率等级达到5"
  },
  [11189] = {
    ID = 11189,
    CnID = "唤醒体故事@缸中之脑·故事三",
    BaseSortID = 19,
    ActorIndex = 15570,
    Title = "AwakerStory_11189_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11189_Content|朵尔的加入，是弥萨格大学在外界眼中唯一的高光时刻。\n学界无数人哀叹，哀叹天降奇才也无法逃脱世俗的桎梏——她居然为了财富，被一所名不见经传的大学收编，沾染上了铜臭。\n在外界口诛笔伐她的自甘堕落时，朵尔在弥萨格获得了比黄金更珍贵的东西。\n她得以越过物质科学的边界，触及现实领域的面纱，那面纱之下，藏着她愿付出生命去追求的东西。\n研究「银芯科技」的危险性，不亚于刀尖上跳舞，而朵尔成为了最认真、最勤勉、最优秀的舞者。\n当融蚀痕出现时，科学的舞者也并未停止舞动，而是抓紧有限的时间旋转，或沉淀或结晶出属于她的独特舞步。\n直至融蚀现象重创肉身，蔓延至心智，侵蚀理性。\n即便如此，她离真理的中心还是太远。\n于是，那颗生命之火已然黯淡，求知之光依旧夺目的明星留下了如此遗言：「在世界遗忘我之前，唤醒我。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11189_UnlockDesc|同调率等级达到7"
  },
  [11221] = {
    ID = 11221,
    CnID = "唤醒体故事@缸中之脑·故事四",
    BaseSortID = 20,
    ActorIndex = 15570,
    Title = "AwakerStory_11221_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11221_Content|科学与知识的新星，在一个普通的工人家庭冉冉升起。\n朵尔童年的大多数时间，都充斥着汽缸鼓动和齿轮运转的声音。\n但对机械的热爱，并不足以支撑少女爬上崎岖严峻的科学之山。\n将她引上求知之路的，是一场瘟疫。\n未知的疯狂肆虐城市，医院人满为患，停尸房不堪重负，人人自危。\n「整座城市的墓地都不够用，把奶奶挖出来和把妈妈烧掉，你总得选一个。」\n于是，朵尔目送母亲消失在了火焰中。\n不同于其他被火葬者，那捧曾被她称为「母亲」的碎骨与灰烬中，流动着一团闪耀的银质。\n「我想知道，我是否还能再见到她。」\n「我想知道，那里面是否有她善良的灵魂。」\n「我想知道，那银质是否是生命的本源，是否是灵魂的本质。」\n「我想知道，世间万物是否存在共同的起点。」\n在得到答案前，朵尔不会向融蚀现象低头。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11221_UnlockDesc|同调率等级达到9"
  },
  [11249] = {
    ID = 11249,
    CnID = "唤醒体故事@幸运侦探·简介",
    BaseSortID = 21,
    ActorIndex = 15604,
    Title = "AwakerStory_11249_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11249_Content|莱克被他的警探好友称为「好运侦探」。\n顾名思义，他是个好运的人：只要下注，就能赢回十倍本金；只要靠蒙，就能选对答案。\n好运侦探不是非得当侦探，只是误打误撞侦破了多起疑案，就被人簇拥着走上了这条道路。\n他破案不靠推理，靠运气。只要在案发现场巡视一周，就能撞上犯人；只要走在路上，就会捡到关键证据。\n在这样的好运中，他度过了顺风顺水的二十五年。\n从来不为昨日烦恼，从来不为明日发愁。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11249_UnlockDesc|唤醒体等级达到1级"
  },
  [11295] = {
    ID = 11295,
    CnID = "唤醒体故事@幸运侦探·故事一",
    BaseSortID = 22,
    ActorIndex = 15604,
    Title = "AwakerStory_11295_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11295_Content|唤醒了莱克的银芯出土于勒姆瓦希知名奇观三角巨塔的内部，呈流线完美的子弹型，大小与形制和SAA转轮手枪用子弹一致，嵌在一具青年男性遗骨的颅骨内。\n触摸这枚银芯时，眼前会出现精美绝伦却又宏大瑰丽的三角巨塔的景象，身体不由自主地蜷缩匍匐。假使触摸者竭力反抗并仰视前方，会见到逆光中面目朦胧的戴冠男人身影，然后瞬间意识中断，银芯自然脱手。\n「三角巨塔的尖顶尚未被磨蚀，应当是建成不久后的景象。」——实验员B·R·朗曼\n「我能听到来自黑暗灵魂的骇人低语。」——实验员K·沃特斯\n「我要控诉弥萨格安排我们进行的非人实验。反复触摸这枚银芯带来的副作用足以令人彻底丧失肉体控制能力。总之，我坚决拒绝再次触摸它。」——实验员L·洛佩兹",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11295_UnlockDesc|同调率等级达到3"
  },
  [11173] = {
    ID = 11173,
    CnID = "唤醒体故事@幸运侦探·故事二",
    BaseSortID = 23,
    ActorIndex = 15604,
    Title = "AwakerStory_11173_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11173_Content|在@3@1事件后，莱克成了弥萨格大学的特邀顾问。\n莱克是个称职的顾问。上至教授离奇失踪或仪器莫名损坏，下至寻猫找狗之类的琐事，莱克都能耐心且敏捷地交付令人满意的结果。\n很快，莱克就因其独特的外貌、体面优雅的举止和助人为乐的好习惯，成为了风靡弥萨格万千少男少女的偶像型角色。\n德克斯特教授曾这么感叹：「风头都被年轻人抢去了。」\n但在他渐渐融入校园后，大家发现，莱克出现在人前的时间日益减少。\n与此同时，弥萨格的某间废弃地下室内，开始频频出现摇骰的响动声。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11173_UnlockDesc|同调率等级达到5"
  },
  [11351] = {
    ID = 11351,
    CnID = "唤醒体故事@幸运侦探·故事三",
    BaseSortID = 24,
    ActorIndex = 15604,
    Title = "AwakerStory_11351_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11351_Content|二十五岁那年，莱克在侦破一起密室杀人案时，遇到了一个怪异的嫌疑人。\n在掌握绝对完整的证据链后，被铐在警局的嫌疑人离奇失踪了，手铐却完好无损。当然，这是当值警察的责任，莱克依然拿到了自己的酬金。\n莱克拿着这笔酬金远渡重洋，出国度假，然后在一个地摊边遇到了逃逸的嫌疑人。嫌疑人正在开盘，见到莱克却依然不慌不忙，只是邀请他加入赌局，并承诺只要莱克赢了，自己就乖乖束手就擒。\n\n莱克一局都没赢。\n\n他输掉了自己的烟斗，输掉了自己的领带，输掉了自己的帽子，输掉了自己的风衣。\n在他浑身赤裸时，嫌疑人将所有衣装还给了他，并表示这些赌注太小了。莱克毫不犹豫地询问嫌疑人想要赌什么，并在对方提出赌一条手臂后慨然应允。\n\n在数次追加赌注后，对方掏出了一把左轮手枪。面对生死轮盘赌，莱克毫不犹豫地拿起手枪，指向自己的太阳穴。\n一声枪响后，莱克倒下了。嫌疑人唤回了他的死灵，想要嘲弄他的无知。然而，莱克开口的第一句话是：「接下来赌什么？」\n\n他的狂妄终于引起了恶魔的兴趣。真名为「N@2@3」的嫌疑人决定让这个赌局延续下去。\n\n「N」拿出三顶礼帽，让他在其中做出能够让他恢复躯体的，「最好的选择」。\n莱克选定了帽子，「N」打开一顶空空如也的礼帽，问他是否需要更换自己的选择。莱克摇头。\n\n-你不懂概率？\n-我只是相信自己的运气。\n\n「N」揭开了第三顶礼帽，里面同样空空如也。最后，他揭开了莱克的礼帽，里面是一团诡异的黑雾。黑雾向莱克袭来，化作诡异的野兽肢体。「N」以化身的身躯取代了他早已押作赌注的身体。\n\n-有着野兽一般嗅觉的人啊，与这化身不是恰好合适吗？所以，这就是「最好的选择」！",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11351_UnlockDesc|同调率等级达到7"
  },
  [11260] = {
    ID = 11260,
    CnID = "唤醒体故事@幸运侦探·故事四",
    BaseSortID = 25,
    ActorIndex = 15604,
    Title = "AwakerStory_11260_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11260_Content|当登山家抵达艾尔沃斯的尖峰。\n当竞技者捧起世界第一的奖杯。\n当虔诚者于睡梦中聆听得天启。\n当胜利来得太过轻易，随之而来的满足感就会成为平平无奇的惯性。\n举目四望，竟全无对手，全无乐趣。\n表面上，莱克渴望激情澎湃的博弈，渴望ALL-IN后跳出喉咙口的心脏，渴望肾上腺素迸发的时刻。\n「不必说那些，了解你的人只有我。你渴望的只是失败罢了。\n就让我赏赐你，最甜美的失败吧。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11260_UnlockDesc|同调率等级达到9"
  },
  [11282] = {
    ID = 11282,
    CnID = "唤醒体故事@凸月侍女·简介",
    BaseSortID = 26,
    ActorIndex = 15571,
    Title = "AwakerStory_11282_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11282_Content|\n「我要戴上像葡萄酒一样黑的紫水晶。」\n「我要穿上鸵鸟毛做成的华贵长裙。」\n「我要成为宴会上唯一的光。」\n侍女忽闪着琥珀色的双眼，她还有好多美好的愿望，却再也无法将它们说出声。凝固的身躯面前，是一望无际的绿色火焰，在漆黑的夜里无声绽放。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11282_UnlockDesc|唤醒体等级达到1级"
  },
  [11243] = {
    ID = 11243,
    CnID = "唤醒体故事@凸月侍女·故事一",
    BaseSortID = 27,
    ActorIndex = 15571,
    Title = "AwakerStory_11243_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11243_Content|A.F.1@2年@1月@1日10:31，警方接到报案，@1@1庄园内发现多处血迹。分局警探贝尔福德立即前往，展开调查，并在血迹中发现成分不明的青绿色黏液。\n13:44，贝尔福德警探递交报告，密斯底亚协定审查会当即接管了案件。\n14:25，审查会第七响应队抵达庄园，控制相关人员并封锁了现场。根据现场情况，队长推测庄园内存在至少5名受害者，且庄园内出现了多处不同程度的融蚀。\n18:00，弥萨格大学调查员抵达现场，确认融蚀现象存在，携带唤醒体进入庄园进行清扫及调查。\n23:11，庄园清扫完毕。调查员在庄园地下室和书房的密室中发现大量神秘学文件及仪式材料，并找到一名不完全唤醒体。唤醒体自称「女仆珈伦」，是@3公爵的首席侍女。被发现时唤醒体穿着女仆制服，戴着许多风格不同的首饰，在非常卖力地打扫地下室。该唤醒体拥有人类外形，青绿色皮肤，四肢末端呈半透明黏胶状，疑似不完全或错误召唤的产物。其身上分泌的黏液与残肢上发现的物质在质地和颜色上完全吻合。\n调查员对其进行询问，女仆珈伦对@1事实供认不讳，并表示一切都是为了获得主人的关注。在得知@3公爵将被逮捕后，她喃喃地说了一句：「那我的新主人在哪里呢？」随后解体为凝胶，留下银芯。\n01:37，审查会第七响应队队长提审相关人员，并依《协定》拘留@1@1庄园主人@3公爵。\n03:09，调查员返回弥萨格大学，并将K-033号银芯登录入库。\n——《@1@1庄园事件记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11243_UnlockDesc|同调率等级达到3"
  },
  [11258] = {
    ID = 11258,
    CnID = "唤醒体故事@凸月侍女·故事二",
    BaseSortID = 28,
    ActorIndex = 15571,
    Title = "AwakerStory_11258_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11258_Content|制服要用蒸汽熨烫，被子要用手工清洗，夏天时壁炉必须干干净净，冬天时则要无时无刻不生着火堆。木地板要光可鉴人，书架要一尘不染，红茶要永远保持温度适宜，方便随时享用。\n为了她那高贵的、特别的、独一无二的新主人，那个给予她又一次生命的守密人，她可以做到一切。她可是世界上最好的女仆，当然要能够完美完成每一项工作，雕琢每一个细节。\n主人的夸赞总是让她无比高兴，但不够，还不够。要怎么做才能获得主人更多的关注呢？要怎么做才能让自己更加引人注目呢？\n「一定是缺少了耳环、项链、手链、戒指和头饰！」她将扫把往地上一杵，自言自语道，「只要有闪亮亮的珠宝装饰，珈伦一定能变得更加可爱，大家也就会更喜欢看着珈伦啦！」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11258_UnlockDesc|同调率等级达到5"
  },
  [11204] = {
    ID = 11204,
    CnID = "唤醒体故事@凸月侍女·故事三",
    BaseSortID = 29,
    ActorIndex = 15571,
    Title = "AwakerStory_11204_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11204_Content|柔软的黑发，饱满的脸颊，如宝石般明亮的双眼，红润的嘴唇——从小，珈伦就因为天生的美貌而备受优待，长大后，男人们每天送的礼物和鲜花更是能在她家门口堆成一个小山。因此，当王宫的管事宣布要将她带入王宫，训练成尊贵的王的侍女时，她并不意外。这难道不是应该的吗？她天生就该被人艳羡，天生就该与众不同，天生就该成为众人的焦点。\n但王宫内最不缺的就是美貌，小城镇的花朵再令人惊艳，在这里都显得寻常而又朴素。外貌再也不能给她换来特殊待遇，甚至连她心心念念的，在百年宴会上进入大殿服侍的机会，也被另一个女孩夺去。\n凭什么？那个女孩有的东西她珈伦也有，凭什么就不是她？\n然后她看到对方耳朵上挂着的银制耳饰，恍然大悟。\n宴会当天，她将女孩溺死在湖中，戴上了那对银白耳饰。她如愿成为了侍女中最耀眼的那个，甚至被恩准在国王身边服侍。或羡慕或嫉妒的目光让她无比畅快——没错，没错，一切就该是这样，这是她这辈子最幸福的一天。\n随后，她在吞没整座王城的绿色浓雾中迎来了自己生命的终结。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11204_UnlockDesc|同调率等级达到7"
  },
  [11223] = {
    ID = 11223,
    CnID = "唤醒体故事@凸月侍女·故事四",
    BaseSortID = 30,
    ActorIndex = 15571,
    Title = "AwakerStory_11223_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11223_Content|红宝石耳环，蓝宝石项链，用石榴石和孔雀石编织而成的漂亮发饰……它们是多么的耀眼，多么的美丽，多么的魅力无穷。它们所到之处，人们趋之若鹜。\n这些珠宝挂坠不是什么「装饰用品」，不，它们才是世界的主角。佩戴了绿松石项链的贵族小姐们被诗人编进曲子传唱；耳上挂着祖母绿宝石的年迈夫人们也被当做高贵的象征。就连那些和她一样出身低贱的女孩，也能凭借手腕上的一条廉价手链，获得「珍珠女孩」的爱称，吸引无数人目光。\n哪怕是干枯的树枝，腐臭的尸骨，只要挂上一串美丽的珠宝，就能变成所有人追求的对象。\n只要她也能戴上那些项链耳环，那些手链头饰，一定也能成为所有人的焦点吧。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11223_UnlockDesc|同调率等级达到9"
  },
  [11195] = {
    ID = 11195,
    CnID = "唤醒体故事@空想利刃·简介",
    BaseSortID = 31,
    ActorIndex = 15588,
    Title = "AwakerStory_11195_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11195_Content|艾尔瓦对她的义肢非常满意。\n「那场战斗后，我就没想过自己还能站起来。能有机会再度为正义而战，是我的荣幸。」\n至于午夜时分从宿舍中传来的低声呻吟，在新的日轮跃出地平线后，就当作不曾存在吧。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11195_UnlockDesc|唤醒体等级达到1级"
  },
  [11296] = {
    ID = 11296,
    CnID = "唤醒体故事@空想利刃·故事一",
    BaseSortID = 32,
    ActorIndex = 15588,
    Title = "AwakerStory_11296_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11296_Content|A.F.18@1年@1月，@2步兵团，勒姆瓦希王国，亚历山大港\n亚历山大港局势逐渐平稳，步兵团的第三营、第四营，连同三个连的火枪手已经借道运河，前往@4进行下一步作战，现仅有第一营及一连火枪手驻守亚历山大。\n一个小队在巡逻时遭遇了反叛军，已迅速解决。他们带回来了一个有趣的小玩意，看上去像一块银子，却比银子更加沉重。我将它收在保险箱里了，指挥官会喜欢这个礼物的。\n……\n驻扎第13天，不同连队皆有士兵出现行为异常，具体行动包括但不限于袭击战友、袭击长官、毁坏物资补给、毁坏军事装备等。这些人员，连同先前那些作乱的疯子，都已经在我的亲自监管下进行关押。\n他们双目赤红，唾沫横飞，比起士兵，更像是某种可悲的动物。这里有某种疯狂正在泛滥，我担心它会发展成瘟疫。\n……\n驻扎第30天。\n截至今日，共有370名士兵出现了疯狂行为，其中有331名在表现出严重的歇斯底里20天后出现肢体麻木，四肢瘫痪现象。他们的攻击性依旧很强，已有2名军医在试图诊治病患时遭到撕咬。\n疯病仍在继续蔓延。我已将情况上报，希望他们尽快采取行动。\n……\n审查会接管亚历山大驻军已经10天了，人们仍在陷入疯狂，我的弟兄们在一个接一个地陷入疯狂。我不明白，为什么只有我们受到这该死的瘟疫折磨？为什么当地人没事？那些总找我们麻烦的反叛军没事？\n我的头越来越疼了，军医们却无能为力——他们比我都要早地堕入疯狂之中，已经成为那些瘫在地上撕咬的怪物之一了。\n我担心我也将步入疯狂。\n那帮家伙说我们得等弥萨格大学的人来。去他的，我们为了国家出生入死，我们不该被这样对待。\n……\n我知道了，我终于知道了。那是个怨灵，寄宿在那块银子里，要向所有侵占这片土地的人复仇。那个缺了一条腿的女人要我们走，她要我们都走，将这里的一切还给原本的主人。是的，是的，就应该是这样，就应该如此，我们从来不该来这里，从来不该开始这场战争，我@1@3@4@2@1@2@3\n——节选自《@2步兵团第一营代理指挥官日志》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11296_UnlockDesc|同调率等级达到3"
  },
  [11361] = {
    ID = 11361,
    CnID = "唤醒体故事@空想利刃·故事二",
    BaseSortID = 33,
    ActorIndex = 15588,
    Title = "AwakerStory_11361_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11361_Content|汉娜：艾尔瓦女士，你加入弥萨格大学也快有好一段时间了。你在学生们中非常受欢迎，不少姑娘还往我这里塞了一堆情书，要不要我念给你听？\n艾尔瓦：这真的……咳，我是说，谢谢大家？但我不是来，呃，分享我的一天的吗？\n汉娜：想不到训练官还有这样可爱的一面，看来等访谈刊登了之后我得去校外躲一下，免得被嫉妒的姑娘们围堵啦！那么回归正题，你能否和本报读者分享一下属于魅力无穷的训练官的一天呢？\n艾尔瓦：恐怕我得让你们失望了，我的一天非常普通。每天早晨4点我会起来锻炼，让这条腿适应运动的状态。\n6点时我会去餐厅，虽然唤醒体之身不需要进食，但我还是……就当这是一种习惯吧。\n8到12点的午前，我会负责指导调查员们的战斗技巧，有时候会额外给守密人加训。下午的训练时间则会根据课程进行调整，有时候是1点开始，有时候是3点。\n每周我都会找时间去诺缔拉那里一趟，让她帮忙调试我的义肢。虽然她容易忘记事儿，但活干得很不错，每次她检修完，我的疼痛都会减轻不少。\n汉娜：那你平时会做什么来娱乐呢？\n艾尔瓦：娱乐啊……这其实对我来说是个还算陌生的概念。但我最近有和奥瑞塔她们一起去海边戏水，和这些比较单纯的孩子待在一起，总能让我感到非常放松。而且游泳对增强身体强度也很有帮助，想当年我还是新兵的时候，我的教官——\n汉娜：好了那么我们今天的栏目就先到这里啦！如果想要知道艾尔瓦女士的往事，还请继续关注下一期《弥萨格日常分享》！\n——摘自《弥萨格日报》特别访谈栏目，《弥萨格日常分享》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11361_UnlockDesc|同调率等级达到5"
  },
  [11301] = {
    ID = 11301,
    CnID = "唤醒体故事@空想利刃·故事三",
    BaseSortID = 34,
    ActorIndex = 15588,
    Title = "AwakerStory_11301_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11301_Content|她的少女时期是在军营中度过的。\n如同所有在军营中长大的孩子一样，她对军团的荣光深信不疑，并将它视作自己的生命。她的世界很简单：指挥官认可的就是正确的，指挥官禁止的就是错误的。\n「挥剑朝向敌人吧，我们将予以这片土地真正的自由；砍向来犯的军队吧，不要对他们抱有同情，现在的牺牲，都是为了未来的安定与繁荣。」\n她在这样的口号下训练，在这样的口号下踏上战场。一次拼死的救援后，她获得了一条伤腿，和一个战争英雄的称号。从此她戴着勋章退居二线，转而成为新兵教官，全然不知这条伤腿将会向她揭示怎样的一个世界。\n残肢受到羞辱，艾尔瓦愤而退伍。走上街头的她这才真正发现，指挥官光辉的演讲是何等谎言——解放不过是侵略的幌子，异国的人们饱受折磨。\n这不是她的理想国，这不是没有鲜血和泪水的光辉未来。\n她因此向着曾经的同僚举起赎罪的刀刃，并发誓为真正的公正而战。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11301_UnlockDesc|同调率等级达到7"
  },
  [11335] = {
    ID = 11335,
    CnID = "唤醒体故事@空想利刃·故事四",
    BaseSortID = 35,
    ActorIndex = 15588,
    Title = "AwakerStory_11335_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11335_Content|艾尔瓦不是没有怀疑过自己的正义，但那恍惚的日夜带给她的是透彻的觉悟。\n虚幻之物是切实存在的。\n最初的起点从来未曾变改，她为之奋战的正义，不是某个化为侵略者的组织，不是某个高喊口号的个人，而是堂堂正正地存在于自己的信念之中。\n\n所有的生命，所有的纯真，所有的梦想、抱负、美好的向往，在炮火面前都能轻易地化作灰烬。\n在战争中失去的，永远不会再回来，它如同地狱恶鬼，蚕食一切美好。\n因此，那些为一己私欲挑起战争之人，也必须品尝灰飞烟灭的滋味。会有真正的英雄，胸怀大义，无私地为所有人的光明未来而战。\n这就是所谓正义的价值。\n……\n\n错了，那就纠正。\n要让那些牺牲值得，要让这截断的双腿与残肢的幻痛值得。\n若有不幸摧毁的，就再用这崭新的义肢讨回来。\n那些渺小脆弱的东西，永远也不会失去它们的光芒。\n一切都是为了那真正没有鲜血，没有泪水的乌托邦。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11335_UnlockDesc|同调率等级达到9"
  },
  [11340] = {
    ID = 11340,
    CnID = "唤醒体故事@睡莲·简介",
    BaseSortID = 36,
    ActorIndex = 15580,
    Title = "AwakerStory_11340_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11340_Content|这团意志投射出的身体，停留在过早夭折的少女模样。腐败的衣摆，苍白的肌肤，弥漫着往世阴翳的双眸，无言地诉说着某种被病痛与苦难缠绕的过去。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11340_UnlockDesc|唤醒体等级达到1级"
  },
  [11176] = {
    ID = 11176,
    CnID = "唤醒体故事@睡莲·故事一",
    BaseSortID = 37,
    ActorIndex = 15580,
    Title = "AwakerStory_11176_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11176_Content|那是德克斯特教授从费弗尔海岸旅行归来时，带回的纪念品。\n费弗尔温润的海洋气候舒适宜人，有着百年历史的塞瓦达疗养院就坐落在海滨，每年选择在那里享受假期的旅人不计其数。\n这只被水渍与海草缠绕的玻璃瓶中，装着少许剔透的粉末。它既不是海难者留下的漂流瓶，亦不是当地土产的砂砾工艺品。德克斯特教授显然已经注意到了，那只瓶子里装的是银芯粉末，换句话说，是一个寄宿于其中的意志。\n他说那是从当地渔民手中买来的，渔民闪烁其词地讲述了最近遭遇的怪事。几天前的清晨，渔民出海时，赶上了一阵怪异的鱼潮。现在不是产卵或越冬的时节，鱼群却聚在一处久久不去。将沉甸甸的渔网拖上来，发现网里捞到了一只奇怪的瓶子。渔民觉得稀奇，又隐隐感到不安，好像会被这奇怪的瓶子诅咒，获得厄运一般。此后几天，在这片海域便再也捕不到鱼了。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11176_UnlockDesc|同调率等级达到3"
  },
  [11192] = {
    ID = 11192,
    CnID = "唤醒体故事@睡莲·故事二",
    BaseSortID = 38,
    ActorIndex = 15580,
    Title = "AwakerStory_11192_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11192_Content|她对待所有人、所有唤醒体都十分友好，从未显示出攻击性倾向。\n大多数时候，她只会安静地待在房间里，眺望着窗外。我们在她的床头，发现了几本被反复阅读过的古典小说，还有数篇写在便笺纸上的，字迹纤秀的随笔诗。\n「和那个少女相比，我显然是幸运的。」她面对着夕阳，对波光粼粼的校园池塘低语。\n她很少参与户外活动，与其说是不愿参与，不如说是不知该如何参与……那少女模样的唤醒体，似乎缺乏很多生活常识。\n我们还数次目击到她在与喷水池中的鱼类们对话，用一种怪异的、如同吐出气泡或溺水者嘶哑的低吼般的声音。但她的面容平静又祥和，仿佛在与亲密的友人相互抚慰、交谈。那一刻，我们都相信她已经获得了真正的安宁。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11192_UnlockDesc|同调率等级达到5"
  },
  [11315] = {
    ID = 11315,
    CnID = "唤醒体故事@睡莲·故事三",
    BaseSortID = 39,
    ActorIndex = 15580,
    Title = "AwakerStory_11315_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11315_Content|一步，再一步地，我缓缓向水中走去。疗养院的护士小姐从未允许我走到过这样遥远的地方。但愿一个很快就会无力支付疗养费用的病人的脱逃，不至于令她受到太多责备。\n夕阳的余晖映照在海上。浪潮迎面而来，轻柔地托起我的裙摆。海水的温度，温暖得像是母亲的拥抱。\n身体从未像此刻这般轻盈，我的胸腔里有一座枯竭的火山，如今那里只剩下海风拂过。\n「回家吧。」\n我听见大海用我父母的声音，呼唤着我。他们为了筹钱给我治病，去了海的另一边。如果我没有生就这样一副不幸的身体，他们也不必这样劳苦了吧。假如我能在一个月夜，悄无声息地消失在大海里……我曾经无数次这样想，但是想到父母伤心的面容，只能作罢。\n可是有一天，一个月夜，父母乘坐的船只悄无声息地消失在了大海里。\n「回家吧。」\n我用尽全身力气加快了脚步。大海总是平静地接纳所有苦难的灵魂，而对我来说，父母所在的地方就是永远的容身之所。\n当四面八方的黑夜降临时，我平生第一次能够自由地呼吸了。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11315_UnlockDesc|同调率等级达到7"
  },
  [11293] = {
    ID = 11293,
    CnID = "唤醒体故事@睡莲·故事四",
    BaseSortID = 40,
    ActorIndex = 15580,
    Title = "AwakerStory_11293_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11293_Content|我喜欢海。费弗尔的海。普鲁士蓝色的海。吹来湿润的暖风的海。从疗养院的窗棂间看过去像油画一样的海。载着归帆的海。像母亲一样孕育着无数生命的海。\n如今，我终于回到了平静的大海里，回到了未曾诞生之前，回到了被母亲的羊水包裹的胎内。洋流拾起那些不幸的碎片，在白骨与珊瑚间拼凑成我。深海的游鱼们穿游而过，倾听着那些关于命运苦难的叹息。\n母亲啊，如果能够再一次被诞生于世，我就能变得更幸福一些吗？",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11293_UnlockDesc|同调率等级达到9"
  },
  [11159] = {
    ID = 11159,
    CnID = "唤醒体故事@甜蜜恶鬼·简介",
    BaseSortID = 41,
    ActorIndex = 15560,
    Title = "AwakerStory_11159_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11159_Content|银铃般的甜笑空洞回响，娇小的躯体于黯淡烛光中浮现。她是戴罪者的恐惧与渴望，是垂死者的甘霖与毒酒，带来甜蜜的痛苦与浪漫的疯狂。她那永不离手的皮鞭落在皮肉上的「啪啪」声，正是于黑暗中奏响的邪恶乐章。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11159_UnlockDesc|唤醒体等级达到1级"
  },
  [11333] = {
    ID = 11333,
    CnID = "唤醒体故事@甜蜜恶鬼·故事一",
    BaseSortID = 42,
    ActorIndex = 15560,
    Title = "AwakerStory_11333_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11333_Content|唤醒材料G752a号银芯，出土于伦蒂尼恩新门监狱遗址的腐臭淤泥堆中。@2调查员在脏暗的牢房走道中不慎踩到破碎的头骨滑倒，因而凑巧发现了它。\n唤醒结果偏离预期，黑色融蚀浆中涌现的并非什么凶恶的死刑犯，或壮硕的刽子手，而是一名身材娇小、笑容狡黠的少女。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11333_UnlockDesc|同调率等级达到3"
  },
  [11201] = {
    ID = 11201,
    CnID = "唤醒体故事@甜蜜恶鬼·故事二",
    BaseSortID = 43,
    ActorIndex = 15560,
    Title = "AwakerStory_11201_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11201_Content|「要小心潘狄娅，她的危险性和外表完全不同。她是个恶魔。」\n这是无数调查员的血泪经历凝结成的肺腑之言。\n潘狄娅总是制造甜蜜的陷阱，诱使其他科研人员或唤醒体与她缔结主仆契约，然后肆意蹂躏与玩弄对方的情感与灵魂。\n与潘狄娅的谈话无果而终，她坚称自己只是与新的爱人制造、分享与播撒快乐的种子，那些契约均是出自双方自愿。毕竟，她也请那些奴隶品尝了甜蜜的果实。\n不过，校内也存在潘狄娅的克星。当索蕾尔经过潘狄娅的宿舍门口时，无论正在讨论怎样的话题，潘狄娅都会突然沉默收声。有传言说，潘狄娅曾在蛊惑索蕾尔时遭到了严重打击，但事实真相如何，至今仍是未解之谜。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11201_UnlockDesc|同调率等级达到5"
  },
  [11239] = {
    ID = 11239,
    CnID = "唤醒体故事@甜蜜恶鬼·故事三",
    BaseSortID = 44,
    ActorIndex = 15560,
    Title = "AwakerStory_11239_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11239_Content|「犯下罪愆之人啊，这里是欲壑之渊，地狱之底。黑犬在这里咆哮，恶臭在这里弥散，丧钟在这里鸣响。你们因放纵的欲望与残忍的行径汇聚于此，等待你们的自然是苦难与死亡。」\n潘狄娅曾供职于新门监狱，那里是整个伦蒂尼恩最压抑、最阴森、最不见天日的污秽角落。曾经满手血腥的重刑犯戴上镣铐与枷锁，被剥夺尊严，在迷宫般的牢房区域中向她跪地求饶，亲吻她的皮靴，谦卑地自称她的奴仆。\n每当有新的绞刑执行，她就会唤来新的死刑犯，请他们欣赏自己的末路。当被执行者于麻绳中扭动着死去时，她喜欢坐在高处，观赏穷凶极恶之徒因恐惧与绝望的折磨而瑟瑟发抖。\n但也有「地狱之猫」曾经观察到，潘狄娅无数次来到新门监狱的铁门旁，踮着脚尖朝伦蒂尼恩城外张望，仿佛在等待某位来自远方的访客。\n「其实我也不过是，永远离不开这黑暗潮湿的悲惨地牢的，那些囚徒中的一份子罢了。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11239_UnlockDesc|同调率等级达到7"
  },
  [11338] = {
    ID = 11338,
    CnID = "唤醒体故事@甜蜜恶鬼·故事四",
    BaseSortID = 45,
    ActorIndex = 15560,
    Title = "AwakerStory_11338_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11338_Content|「主人啊，鞭笞我吧。」\n她理应干涸的眼中燃烧着欲念之火，融化的蜡油如泪滴般滑落。\n饥渴、痛苦、诅咒、污秽，她所索求的一切折辱、她所施予的一切享乐，终于在此刻降临于自身。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11338_UnlockDesc|同调率等级达到9"
  },
  [11269] = {
    ID = 11269,
    CnID = "唤醒体故事@鹦鹉螺·简介",
    BaseSortID = 46,
    ActorIndex = 15565,
    Title = "AwakerStory_11269_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11269_Content|她似乎总在围着那台名为「幻影号」的摩托车打转：拧一下这里的螺丝，调整一下那里的管道……这是一个没有尽头的工程，尽管很多人都认为她已经将维修做到了最好，她还是日复一日地埋首其中。\n究其原因，则是那没有来头的「还缺点什么」的感觉。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11269_UnlockDesc|唤醒体等级达到1级"
  },
  [11244] = {
    ID = 11244,
    CnID = "唤醒体故事@鹦鹉螺·故事一",
    BaseSortID = 47,
    ActorIndex = 15565,
    Title = "AwakerStory_11244_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11244_Content|A.F.3@2年，亚格罗共和国沿海城镇出现融蚀现象。本次融蚀现象以港口为中心呈螺旋状扩散，波及方圆数百米的地区，造成@1人死亡。\n据调查，融蚀现象最早在港口渔船出现。该船于A.F.3@2年@1月@1@1日出海作业，捕捞到一条拥有银色螺旋纹路的类鳕鱼生物。\n该生物躯体柔软，被利器切割后整体破裂，流出夹杂了贝壳和其他残渣的流体物质。渔船抵达港口后，渔获上已经出现贝壳类增生，但并未引起注意，直到一名渔民将自己视作螺壳，尝试扭曲身体导致重伤入院，事件才得以上报。\n事后，弥萨格相关人员于@4罐头厂寻得融蚀源头，将其清除后取得O-36银芯。\n——《唤醒体系银芯获取报告：O-36》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11244_UnlockDesc|同调率等级达到3"
  },
  [11197] = {
    ID = 11197,
    CnID = "唤醒体故事@鹦鹉螺·故事二",
    BaseSortID = 48,
    ActorIndex = 15565,
    Title = "AwakerStory_11197_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11197_Content|被唤醒后第三个月，调查员们和守密人一起给诺缔拉举办了一场派对。倒不是庆祝她来到这里，而是庆祝她终于记得弥萨格大学的名字了。\n虽然她第二天又忘记了，但派对总可以再举办一次。谁知道呢，或许再过三个月她就能真正记住了。\n很难说诺缔拉那金鱼一般的记忆力是融蚀的后遗症，还是银芯缺损的结果。不过短期记忆也不完全意味着坏事，对一个认真对待工作的机修工而言，忘记拧到哪颗螺丝意味着把所有螺丝再拧一遍，两遍，三遍……因此，经由诺缔拉双手维修过的器械，往往有着比其他器械更牢固的结构，和更长的使用寿命。\n朵尔因此十分喜爱她，毕竟不是谁都有修一次顶十年的手艺的。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11197_UnlockDesc|同调率等级达到5"
  },
  [11290] = {
    ID = 11290,
    CnID = "唤醒体故事@鹦鹉螺·故事三",
    BaseSortID = 49,
    ActorIndex = 15565,
    Title = "AwakerStory_11290_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11290_Content|每当夜幕降临，诺缔拉便会和母亲一起钻进库房，拿起各种工具，用攒下来的零件拼凑一辆名为幻影号的独轮摩托。\n「为什么不直接买一辆呢？」年幼的她抬起头，向拿着工具的母亲提问，「那样我们立刻就可以出去冒险了。」\n母亲握着她的手，一边教她如何又快又好地焊接金属，一边说：\n「机械和人一样，每个都有不同的脾气和性格。只有真正理解我们的，才能与我们一起度过更长的时光。」\n「像朋友一样吗？」\n「除了机械是我们制造的这点以外——是的，像朋友一样。」\n巨大的轮毂必须结实，搭载的引擎必须耐用，因为她们一旦出发，就不会轻易回头。她们要一起走遍世界，一起完成一场盛大的冒险。\n疾病带走了她的母亲，留下了满是工具，却又空空荡荡的机修铺。诺缔拉抱着未完成的幻影号，下定决心要与这个冰冷的朋友一起完成她和母亲的梦想。\n直到最后一次出航。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11290_UnlockDesc|同调率等级达到7"
  },
  [11162] = {
    ID = 11162,
    CnID = "唤醒体故事@鹦鹉螺·故事四",
    BaseSortID = 50,
    ActorIndex = 15565,
    Title = "AwakerStory_11162_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11162_Content|A.F.315年@1月@2日\n茜尔维娅医生建议我把自己的想法记在本子上，好锻炼记忆力。大家都说医生懂得很多，肯定能帮助我。所以拜托了，明天的我，可千万不要忘记这个笔记本的用处啊！\n今天我完成了排气管的制作及组装，现在它既可以排气，又不会干扰到辅助软管的行动。这应该是最后一步了吧？起码目前我没有发现问题，但也不排除我忘了哪个地方的螺丝……没错，我一定忘了什么，不是螺丝就是管道，或者是轴承润滑？机油？老实说，我一直隐隐觉得幻影号有哪里不对劲。它总是很……欠缺？是这个词吗？它少了一个很关键的东西，比引擎还关键。没有它我无法启程，无法踏上那通往未知的旅途，因为那是我们的@2\n我为什么要说我们？我和谁？我是不是有过……我记得，好像，@2@4@3\n呃，我头好疼。\n不过这个笔记感觉蛮有用的，这样我明天就可以从这里接着回想啦，或许真的能想起来也不一定呢？\n——诺缔拉日记本中唯一的一篇日记。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11162_UnlockDesc|同调率等级达到9"
  },
  [11372] = {
    ID = 11372,
    CnID = "唤醒体故事@淤泥之花·简介",
    BaseSortID = 51,
    ActorIndex = 15581,
    Title = "AwakerStory_11372_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11372_Content|渴盼着名为「母亲」之物，服从「主人」命令的少女。\n世界遗忘了她的名字，于是那在巨型黑色淤泥眼球中，如百合花般绽放的脆弱白色纤影，被后来者仓促命名为「Lily」。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11372_UnlockDesc|唤醒体等级达到1级"
  },
  [11256] = {
    ID = 11256,
    CnID = "唤醒体故事@淤泥之花·故事一",
    BaseSortID = 52,
    ActorIndex = 15581,
    Title = "AwakerStory_11256_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11256_Content|在试图查询莉莉·奥斯伍德的记录时，艾瑞卡发出了81条错误警报。身为曾被世界遗忘之人，莉莉的出生档案、诊疗记录都已化为一捧黑色淤泥。\n但我们仍能通过特殊仪器观测到她的银芯形状：纤细蜷曲，形似数缕交缠的发丝——更准确地说，像是孩童的胎毛。\n特别需要注意的是，莉莉对链接者总是表达出特殊的依恋，比起自称「同伴」、「主人」，以「母亲」自居，或许能更快拉近与她的关系吧。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11256_UnlockDesc|同调率等级达到3"
  },
  [11262] = {
    ID = 11262,
    CnID = "唤醒体故事@淤泥之花·故事二",
    BaseSortID = 53,
    ActorIndex = 15581,
    Title = "AwakerStory_11262_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11262_Content|不完全唤醒的后遗症，加之变更链接者造成的心理刺激，让莉莉的性格与心智出现了一定程度的退化，她在大学内的沉默有目共睹。\n除了跟在守密人及唤醒体萝坦身边外，莉莉鲜少独自出现在校园中。她不会出现在教室，也不会加入少年唤醒体们的游戏。不出战时，她只是在宿舍中安静地等待着指令。\n莉莉的房间窗口正对着校园后的钥冢，夕阳西下时，她会站在窗边，出神地眺望被昏黄色光线笼罩的钥冢。\n银钥状的墓碑在低垂夕阳的照射下拉出纤长的投影，伫立在窗前的莉莉和那些墓碑一样沉默。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11262_UnlockDesc|同调率等级达到5"
  },
  [11207] = {
    ID = 11207,
    CnID = "唤醒体故事@淤泥之花·故事三",
    BaseSortID = 54,
    ActorIndex = 15581,
    Title = "AwakerStory_11207_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11207_Content|「妈妈，妈妈，莉莉打针没有哭！」\n「莉莉真勇敢！」\n「嗯，莉莉不痛，莉莉想到妈妈会回来陪莉莉，就觉得不痛了！」\n……\n「主人，给我命令。」\n「去手术台上躺好，十五分钟后开始手术。药都按时吃了吗？」\n「吃了，主人。」\n「切开这里，不痛吧？」\n「……不痛，主人。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    ConditionType_1 = "StageFirstClear",
    ConditionPara_1 = {7869},
    UnlockDesc = "AwakerStory_11207_UnlockDesc|同调率等级达到7",
    UnlockDesc_1 = "AwakerStory_11207_UnlockDesc_1|通关主线普通第4章「于无声处」"
  },
  [11227] = {
    ID = 11227,
    CnID = "唤醒体故事@淤泥之花·故事四",
    BaseSortID = 55,
    ActorIndex = 15581,
    Title = "AwakerStory_11227_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11227_Content|如果没有苏醒过来就好了，沉沦于深渊之人，本就不该睁眼直视耀眼的日轮。\n她应该是麻木的实验素材，是已被这世界埋葬之人，不该拥有疼痛的感知、被爱的渴望。\n母亲的留恋不舍制造了她一生的悲剧，而莉莉则仍陷于「是否应当服从于世界安排」的迷茫。\n或许某一天，她会从反抗命运的某人身上得到答案。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    ConditionType_1 = "StageFirstClear",
    ConditionPara_1 = {7869},
    UnlockDesc = "AwakerStory_11227_UnlockDesc|同调率等级达到9",
    UnlockDesc_1 = "AwakerStory_11227_UnlockDesc_1|通关主线普通第4章「于无声处」"
  },
  [11253] = {
    ID = 11253,
    CnID = "唤醒体故事@淤泥之花·故事五",
    BaseSortID = 56,
    ActorIndex = 15581,
    Title = "AwakerStory_11253_Title|故事·五",
    StoryType = 2,
    Content = "AwakerStory_11253_Content|本应湮没于历史长河的小小灵魂，依托于母亲的愿望，和@1@2@1设立法阵的充盈灵气，与沉眠艾尔沃斯冰下的巨型生物结合，复生为少女的怪物「莉莉」。\n由于唤醒的不完全，唤醒初期的莉莉没有知觉，只是一具服从命令的战斗人偶。\n雕塑家协会成员弗朗西斯·奥斯伍德曾以莉莉为素体，进行过长达@2年的非法实验。从弗朗西斯的日记中可知，那时的莉莉状态极不稳定，时常失控造成小范围破坏，导致弗朗西斯不得不频繁变换住所。\n随着灵知制剂的摄入和银芯的种植，莉莉于未经记录的某日恢复了感知力和部分记忆。后几经周折，弗朗西斯接手了濒临倒闭的拉伊疗养院，并将其改造为了试验场。\n在L-776号拉伊小镇「地狱犬」事件中，其母弗朗西斯·奥斯伍德被囚于自身打造的异常维度中，失去联络。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {10},
    ConditionType_1 = "StageFirstClear",
    ConditionPara_1 = {7869},
    UnlockDesc = "AwakerStory_11253_UnlockDesc|同调率等级达到10",
    UnlockDesc_1 = "AwakerStory_11253_UnlockDesc_1|通关主线普通第4章「于无声处」"
  },
  [11284] = {
    ID = 11284,
    CnID = "唤醒体故事@雕砌者·简介",
    BaseSortID = 57,
    ActorIndex = 15592,
    Title = "AwakerStory_11284_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11284_Content|来自西岱的艺术家并不在意人类，她只追求某种绝对意义上的纯粹之美，将转瞬即逝的刹那铭刻为永恒。\n灵感之泉奔涌而出，刻刀从未停歇。每完成一个作品，珊瑚色的阴霾便蚕食躯体一分，痛苦与喜悦并生，而雕砌者亦不在意自己。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11284_UnlockDesc|唤醒体等级达到1级"
  },
  [11358] = {
    ID = 11358,
    CnID = "唤醒体故事@雕砌者·故事一",
    BaseSortID = 58,
    ActorIndex = 15592,
    Title = "AwakerStory_11358_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11358_Content|「A.F.3@2年，密大海洋生态小组在南部海域进行物种观测时，发现一片形态怪异的珊瑚礁……」\n「该样本性质奇特，不同于地球上任何已知元素。在水中质地偏软，一到陆地便迅速风干硬化。据生物系和天文系联合研究，推测极有可能为某种未知地外物质……」\n\n「A.F.3@1年，唤醒代号Sanga。\n该唤醒体自苏醒后便保持雕刻行为。那些以诡谲的曲面和线条而闻名的艺术风格难以被归到任何流派。除了给予观看者精神冲击外，对融蚀研究几乎没有帮助。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11358_UnlockDesc|同调率等级达到3"
  },
  [11288] = {
    ID = 11288,
    CnID = "唤醒体故事@雕砌者·故事二",
    BaseSortID = 59,
    ActorIndex = 15592,
    Title = "AwakerStory_11288_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11288_Content|「@1月@1日，大学墓地再次遭到破坏。截至目前，这已是本月发生的第三次恶性掘墓事件。\n协会成员经过长达数周的跟踪调查，已初步锁定唤醒体珊为嫌疑人。\n相信参观过这位雕砌者工作间的人，都会震撼于那些形态各异、诡谲亵渎的海洋主题雕塑，并对其素材来源产生质疑：我们在这里发现了可怜的娜塔莎下葬时戴的贝壳珠串，以及与墓碑相同材质的阿伯丁花岗岩。与热衷阐释创作理念的皮克曼不同，珊更加捉摸不定——她虽面带微笑，却完全无视了我们的质疑。\n不要触碰她的刻刀，也不要和她单独待在工作间里——德克斯特教授曾这样警告我们，但为了揭开掘墓事件的真相，激进的手段是必要的。\n现在是@1月@1日0点45分，推理爱好者协会成员@2已潜入珊的工作间，祝我好@3」\n——节选自《推理爱好者协会，调查记录S-618》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11288_UnlockDesc|同调率等级达到5"
  },
  [11345] = {
    ID = 11345,
    CnID = "唤醒体故事@雕砌者·故事三",
    BaseSortID = 60,
    ActorIndex = 15592,
    Title = "AwakerStory_11345_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11345_Content|A.F.2@1年，西岱艺术沙龙展。\n「我要带她回家！」袭击者一面用锤击打着雕塑家奥古斯特的绝笔《无名珊瑚之女》，一面高声叫喊。他很快被围观的群众制止，人们惊讶地发现，这位神情恍惚的老者正是隐退已久的奥古斯特本人。\n一时间，有关《无名珊瑚之女》的揣测与议论纷至沓来。\n人们说，它的原型正是奥古斯特手下一位叫珊的女徒弟，奥古斯特最优秀的作品都出自珊之手，他是可耻的剽窃者。\n人们说，珊出身显赫，父亲是著名的作家，还有一位外交官弟弟。她为了学习雕塑，不惜与家里断绝关系，只身前往巴黎，至死都过着贫困潦倒的生活。\n人们说，珊患上了一种怪病，她的身上流淌着黑色的黏液，每雕刻一分，身体的一部分就会变成珊瑚，《无名珊瑚之女》其实是她珊瑚化的模样，根本不是什么雕塑作品。\n人们还说……\n师徒，知己，疯病。当人潮散去，展厅只剩被言语雕砌的珊瑚之女。她沐浴在月光下，眨了眨眼，等待着，等待着——回家的那一刻。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11345_UnlockDesc|同调率等级达到7"
  },
  [11323] = {
    ID = 11323,
    CnID = "唤醒体故事@雕砌者·故事四",
    BaseSortID = 61,
    ActorIndex = 15592,
    Title = "AwakerStory_11323_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11323_Content|无数个难眠夜晚里，身患融蚀的雕砌者倾听着海浪声，陷入迷乱的梦境：\n当她的亲族带着战火降临，她砌起螺湮雄伟的高墙。\n当天父和众眷陷入沉睡，她将史诗雕成不朽的圣像。\n她的知觉钝化，躯体僵硬，几乎快要握不住刻刀。\n珊瑚般的白色阴霾已蔓延到小臂，她凝视着颤抖的双手，倏然一笑。生命之火终会熄灭，而身躯将化为永恒。\n她如愿被沉入海底。珊瑚破碎，黑色的融蚀浆丝丝缕缕汇入海洋——她终于见到了那座遗失久远的螺湮古城，并与之彻底融为一体。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11323_UnlockDesc|同调率等级达到9"
  },
  [11222] = {
    ID = 11222,
    CnID = "唤醒体故事@守梦人·简介",
    BaseSortID = 62,
    ActorIndex = 15566,
    Title = "AwakerStory_11222_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11222_Content|她缥缈的身影叫人想起振翅欲飞的鸥鸟，白裙被猎猎海风扬起的时候，观者总能描绘出一幅飞向乌托邦的飞鸟之图。\n不知道那端坐于桅杆横木之上的少女，是否也曾想象过自己的遨游之姿呢？",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11222_UnlockDesc|唤醒体等级达到1级"
  },
  [11240] = {
    ID = 11240,
    CnID = "唤醒体故事@守梦人·故事一",
    BaseSortID = 63,
    ActorIndex = 15566,
    Title = "AwakerStory_11240_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11240_Content|A.F.3@1年7月3日，应内森尼尔·福布斯·格林基金会的邀请，弥萨格大学参与了针对「幽灵船」索纳尼尔号的调查。\n登上这艘于十年前被宣布沉没的三桅帆船后，出勤调查员芬戈尔·约翰森随即失去了通讯信号。\nA.F.3@1年7月10日，学校再次与他取得联系时，约翰森调查员已身处300海里外的雷欧高地北岸。约翰森调查员称，登船后他马上就失去了时间与空间的概念，并且无论如何都无法想起在索纳尼尔号上发生的一切。\n时至今日，约翰森调查员也只能依稀记起一个名词：永恒乐土。\n基于幽灵船本身的无害性，弥萨格大学于今日（A.F.3@1年12月24日）决定中止调查。\n——《档案：索纳尼尔号船难调查》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11240_UnlockDesc|同调率等级达到3"
  },
  [11186] = {
    ID = 11186,
    CnID = "唤醒体故事@守梦人·故事二",
    BaseSortID = 64,
    ActorIndex = 15566,
    Title = "AwakerStory_11186_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11186_Content|希莱斯特加入学校的第一分钟，便被朵尔带走并接受了全面评估。\n作为非大学流程召唤的唤醒体，希莱斯特的精神状态出奇稳定。但与之相对的，无论是精神体强度，还是作为银芯强度评判标准的诺斯指数，希莱斯特都远远没有达到唤醒体的标准。\n然而，如同虚空中盛开的无形之花一般，她作为唤醒体降临在了世界上。\n尽管在日常活动与外勤任务中均未表现出异常，但通过数据监控我们得知，希莱斯特的情况不容乐观：她身上微弱的意志正在不断流失。\n目前，唤醒系正在筹备一个小规模教团，希望以供给信仰的方式维持希莱斯特的存在，有意加入且精通水性者请联系茜尔维娅老师。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11186_UnlockDesc|同调率等级达到5"
  },
  [11235] = {
    ID = 11235,
    CnID = "唤醒体故事@守梦人·故事三",
    BaseSortID = 65,
    ActorIndex = 15566,
    Title = "AwakerStory_11235_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11235_Content|跟随极乐鸟前行的第三十一天，索纳尼尔号驶进一片起雾的海域。\n希莱斯特坐在桅杆的高处，眺望着下方的人们。那里传来鲁特琴甜美的旋律，与祈祷航行顺利的歌声。\n\n她不知晓这次航行的目的地，也不清楚这趟旅程能够带来多少财富与名誉。她不在意祈祷者是否虔诚，亦不在意在海上悄然流传的，关于她不够灵验的恶名。既然她被要求给予航船庇佑，那么她就将沉默地履行着使命。\n\n当歌声停止，雾霭散去，出现在水手面前的却是一片怒涛汹涌的风暴之海。闪电撕开天幕，黑色污雨倾盆而下，激流将脆弱的船身卷起，投入那骇人的深渊之中。\n\n「神已经抛弃我们了！」绝望的亲眷们呐喊着，咆哮着，将她关入暗无天日的地牢。\n失职的庇佑者，已经无人深究她为何无法履行使命，而希莱斯特亦只余下最后一个微小的疑惑。\n\n……那艘船为什么会沉呢？\n\n曾将她束缚桅杆之上的铁链溅起水花，她向深海坠去……\n如同被折断双翼的白鸟。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11235_UnlockDesc|同调率等级达到7"
  },
  [11168] = {
    ID = 11168,
    CnID = "唤醒体故事@守梦人·故事四",
    BaseSortID = 66,
    ActorIndex = 15566,
    Title = "AwakerStory_11168_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11168_Content|我们的好朋友，神通广大的汉娜·皮斯利，不知从何处挖到了希莱斯特的研究资料。托这位行事大胆的记者的福，原本是保密级别的资料和她们之间那段短小的访谈，现在闹得人尽皆知了。\n\n汉娜在阅读了保密资料后，向那位平时便缺乏情绪的希莱斯特，提出了一个问题。\n\n「大多数唤醒体都有未竟之愿，这是他们与学校合作的基础之一。但是在这份资料中，你的愿望一栏是空白的。你没有想要完成的事吗？或者，你成为唤醒体的意义在哪呢？」\n\n「有的，我有的。」\n\n少女的表情没有露出破绽，和往常一样虚无，高洁。如果不是这声短促的、焦急的回答，记者小姐几乎要以为对方没有听见自己的问题。\n\n\n「我会找到愿望的……大家是如此希望的，所以，我会找到的。」\n\n温柔的声音，恍如一场一触即碎的梦幻。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11168_UnlockDesc|同调率等级达到9"
  },
  [11236] = {
    ID = 11236,
    CnID = "唤醒体故事@复仇巨刃·简介",
    BaseSortID = 67,
    ActorIndex = 15564,
    Title = "AwakerStory_11236_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11236_Content|他是名副其实的巨人。强健的肉体，昭示着他那令人畏怖的力量。他使用着一柄无人能够举起的巨刃，战争与血祭的滋养，令它的表面如同饱涂油脂的皮毛那般光亮。巨刃的獠牙曾斩下过无数敌人、同族的头颅，亦斩下过他自己的。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11236_UnlockDesc|唤醒体等级达到1级"
  },
  [11369] = {
    ID = 11369,
    CnID = "唤醒体故事@复仇巨刃·故事一",
    BaseSortID = 68,
    ActorIndex = 15564,
    Title = "AwakerStory_11369_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11369_Content|A.F.3@2年4月2日，阿什杜德地区一处庙宇遗迹遭到了破坏。\n作为唯一读过大学的人，我这个游客被地区长官邀请参与了对遗迹的建筑学评估。哈哈，千万不能让他们知道我的「大学」其实并不是那么一回事。\n3日下午，我进入了庙宇的中心，古代闪族人将这座庙宇作为祭祀场所，这里曾盛行着某种已失传的异教信仰。\n然而出现在我面前的，是所有人都不会认错的一座雕塑。我清楚地知道，那具雕塑上的褶皱，原本该是斜纹亚麻布的纹理。\n雕像双手折断、身首分离，下肢被摔碎在门槛上，浑身像被蛞蝓爬过似的沾满黏液。我注意到了几道奇特的抓痕，和一个巨型的、有蹼的足印。\n异教信仰也许仍在该地区流传，但暂无需要展开正式调查的必要性，我会延长在阿什杜德地区的停留时间。\n——芬@1·@2森《非利士五城遗址巡礼》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11369_UnlockDesc|同调率等级达到3"
  },
  [11276] = {
    ID = 11276,
    CnID = "唤醒体故事@复仇巨刃·故事二",
    BaseSortID = 69,
    ActorIndex = 15564,
    Title = "AwakerStory_11276_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11276_Content|戈利亚专横、狂妄，但他的强大毋庸置疑。从艾瑞卡小姐的战斗记录中不难看出，那蛮横的力量足以支撑他独自突破险境。我认为，之所以戈利亚不在乎搭档的能力强弱，是因为在他的世界中，没有人比他更强。\n然而戈利亚在面对弥利亚姆时，总会不自觉流露出些许畏惧。很难想象，究竟是怎样的存在，才会让这名强横的首领、暴虐的旧王产生敬畏之情。\n另外，他对墨菲小姐表现出了不同寻常的关注。有时候，他会在学校迷障周边徘徊，似乎在等待墨菲完成任务归来；有时候，他会悄悄地观察墨菲有没有在任务中受伤。\n皮斯利小姐也注意到了这件事，她曾半开玩笑地对我说：「嘿，你觉不觉得他在尝试当一个普通的父亲？」\n——《一名实习研究员的观察记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11276_UnlockDesc|同调率等级达到5"
  },
  [11187] = {
    ID = 11187,
    CnID = "唤醒体故事@复仇巨刃·故事三",
    BaseSortID = 70,
    ActorIndex = 15564,
    Title = "AwakerStory_11187_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11187_Content|一道疤痕横亘在他的脖颈之上。他的族人从一道疤痕中获得死亡，而他从一道疤痕中获得了力量。\n被驱逐出领地的丧家之犬，舔舐着失败与绝望的苦涩，被困于茫茫大海之时，他向神祈求了超越的力量。\n神的使徒回应了祈祷，斩断了他的脖颈。\n神的使徒回应了祈祷，在断颈上培植出了不朽的残片。\n神的使徒回应了祈祷，将他领入了永生的殿堂。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11187_UnlockDesc|同调率等级达到7"
  },
  [11359] = {
    ID = 11359,
    CnID = "唤醒体故事@复仇巨刃·故事四",
    BaseSortID = 71,
    ActorIndex = 15564,
    Title = "AwakerStory_11359_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11359_Content|他独自从死亡中幸存，蜕变；他收敛了巨刃的锋芒，戴上了使徒的假面。\n当神迹降临时，他本能地产生了敬畏，但他不曾畏惧任何神明，也不曾理解真正的信仰。\n巨人不应居于人下，战士不会俯首称臣。\n亘古已古，他的战争仍未终结，征服的欲望与恩赐的力量一同，深深地刻入他的血脉。也许有一天他将身死，也许有一天他将统治所有地方。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11359_UnlockDesc|同调率等级达到9"
  },
  [11267] = {
    ID = 11267,
    CnID = "唤醒体故事@沉渊者·简介",
    BaseSortID = 72,
    ActorIndex = 15594,
    Title = "AwakerStory_11267_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11267_Content|他总是阴沉着脸，独自在湖畔游荡。渐渐地，学生们把湖畔称为「阴郁半鱼人的领地」。于是他便像个领主般，每日庄重地前来巡视。当他纵身跃入湖底，翻腾的气泡温柔地拥抱着他；在水中，岸上的嘲讽似乎也听不大清了。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11267_UnlockDesc|唤醒体等级达到1级"
  },
  [11274] = {
    ID = 11274,
    CnID = "唤醒体故事@沉渊者·故事一",
    BaseSortID = 73,
    ActorIndex = 15594,
    Title = "AwakerStory_11274_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11274_Content|A.F.3@1年 @1月。\n亚格罗共和国东部海岸的魔鬼礁，当地渔民报告打捞到「一具形态古怪的尸体」——体型矮小佝偻，眼球突出，皮肤部分硬化，指间长蹼，最怪异的是脖子两侧对称的红色印痕。如果不是因为他身上穿着学生制服，也许很难被当作「人类尸体」。\n调查员赶到时，那古怪尸体已被惊惧的渔民当作不祥之物烧毁，只留下一个当时在学生间颇为流行的手提箱。箱子里没放任何换洗衣物，只有一些字迹模糊的手稿，一个指南针，以及一张中年妇女的照片。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11274_UnlockDesc|同调率等级达到3"
  },
  [11341] = {
    ID = 11341,
    CnID = "唤醒体故事@沉渊者·故事二",
    BaseSortID = 74,
    ActorIndex = 15594,
    Title = "AwakerStory_11341_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11341_Content|自@2事件后，凯刻斯与我们握手言和，成为了唤醒体系的编外人员，他了解的@1知识仅有一鳞半爪，却极乐意展示和分享。\n他在图鲁、弥利亚姆、戈利亚等人面前充满谦卑，却对其他种族——尤其是人类——投以阴郁不善的目光。阅读过档案的研究员们理解他的偏执，然而部分脾气暴躁的唤醒体却不能容忍。这种剑拔弩张的氛围通常都需要由茜尔维娅出面开解和消弭，凯刻斯与茜尔维娅间也逐渐建立了信任关系。\n在茜尔维娅的开导下，凯刻斯又觉醒了「高等种族的包容心」，对他人的挑衅回避不言。\n「那孩子经常会充满温情地回忆他的人类母亲。都说母亲是孩子认知世界的标杆，本质上他对人类的敌意是后天形成的。所以，只是缺乏一些引导和关心而已啦。」茜尔维娅在心理辅导记录中写道。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11341_UnlockDesc|同调率等级达到5"
  },
  [11278] = {
    ID = 11278,
    CnID = "唤醒体故事@沉渊者·故事三",
    BaseSortID = 75,
    ActorIndex = 15594,
    Title = "AwakerStory_11278_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11278_Content|凯刻斯讨厌人类，当他还是个孩子时，他就讨厌他们。\n他曾救起一个落水的小女孩，反而被其他孩子诬赖为害人精；他躲他们躲得远远的，又被追着喊「臭臭的蛙人」。\n\n那十数年来的阴郁日子里，能让他有几分期盼的，唯有奥恩叔叔的来信。他渊博的知识中包含无穷无尽的鬼怪故事，让小小的凯刻斯痴迷不已。可好景不长，没过几年奥恩叔叔竟失踪了。\n直到16岁那年凯刻斯回到祖父家拜访，偶然翻到奥恩的手稿。他终于知晓了身体上扭曲纹路中隐含的高贵意义。\n呵，人类，终究是低劣的下等生物罢了。\n从此，他不再悲观，而是潜心等待，等待命运降临的那天。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11278_UnlockDesc|同调率等级达到7"
  },
  [11360] = {
    ID = 11360,
    CnID = "唤醒体故事@沉渊者·故事四",
    BaseSortID = 76,
    ActorIndex = 15594,
    Title = "AwakerStory_11360_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11360_Content|您一定也做过这样的梦吧？突然继承了高额的遗产，突然获得了无上的力量……足以将那些曾经鄙夷和伤害我们的人统统踩在脚下。\n然后，在梦醒来的瞬间，在永无止境的现实面前，陷入更深一层的绝望。\n可是，我的梦是真的，我的命运，降临了。\n\n知道吗，你们才是弱者。\n\n肉体的孱弱和灵魂的萎靡支撑不起高贵的血统？不，不会有那种事的，因为奥恩这个姓氏，就是我们@2的荣耀与象征。获赐了血脉和姓氏的我，不再是那个任人羞辱的怪胎，而是流淌着高贵血脉的@1者。\n\n所以……请你们……不要再用那样令人窒息的眼神看着我了……",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11360_UnlockDesc|同调率等级达到9"
  },
  [11364] = {
    ID = 11364,
    CnID = "唤醒体故事@深海淑女·简介",
    BaseSortID = 77,
    ActorIndex = 15576,
    Title = "AwakerStory_11364_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11364_Content|高傲、任性、自我中心……许多与她接触过的人，都会对她的个性留下如此评价。她在以往生活的环境中，似乎一直受到众星捧月般的照顾，也许正是这些曾经的无微不至养成了她骄纵的性格。\n「喂！你在看什么东西？不是说过了吗，叫你三声之内就必须回应本小姐！」\n——阅读档案的时候也得十分注意。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11364_UnlockDesc|唤醒体等级达到1级"
  },
  [11291] = {
    ID = 11291,
    CnID = "唤醒体故事@深海淑女·故事一",
    BaseSortID = 78,
    ActorIndex = 15576,
    Title = "AwakerStory_11291_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11291_Content|洪积3@2年夏季，伊里安岛上流传开了海怪的传说。\n有渔民声称，在近海目击了一只大约五层楼高的头足纲动物。它通体深红，触手上有着黑色的同心环。\n听到这则怪物流言时，我正和约翰森前辈在对棉兰地区发生的疑似融蚀现象进行查证。第二天，前辈就准备好了前往伊里安岛的船只，我在阿米兰特洋中央写下了这篇报告。\n航行第三天，海面上出现了大片鱼类浮尸：鲭鱼、比目鱼、海豚，我发誓在尸群中看见了一头怀孕的抹香鲸！尽管老水手都说，过量繁殖导致的海水缺氧是鱼类死亡的元凶，但我总觉得我们遗漏了些什么……\n航行第八天，我的晕船现象越来越严重，强烈的反胃让我几乎无法进食。尽管我们已经接近伊里安岛了，但约翰森强烈要求我们返航@3……我不理解，但我选择相信这名前辈。\n——贝尔·哥伦布《洪积3@2年夏季实习报告》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11291_UnlockDesc|同调率等级达到3"
  },
  [11265] = {
    ID = 11265,
    CnID = "唤醒体故事@深海淑女·故事二",
    BaseSortID = 79,
    ActorIndex = 15576,
    Title = "AwakerStory_11265_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11265_Content|被唤醒后，我们终于得知墨菲从前在教团过着怎样的生活。\n撑着一把阳伞，外出前要花大量时间整理自己的仪容。下午茶要在午后四时，配上牛奶红茶以及草莓果酱司康。保持整洁，优雅，这正是淑女的宿命，她无论身在何处，都坚持过着淑女的生活。\n（档案员批注：我觉得，她用手直接抓羊脂牛肉布丁的样子可称不上淑女……）\n尽管现在已经没有供她呼来喝去的仆从，她仍按照自己希望的方式生活着，这的确是一件值得欣慰的事。\n受到那个事件的影响，她很少与唤醒体弥利亚姆和戈利亚接触，甚至会故意视而不见。在与唤醒体图鲁相遇时，她也表露出了十分复杂的神情。\n若是提起过去，她会变得脾气很坏。也许，她还需要一点时间来平复心情。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11265_UnlockDesc|同调率等级达到5"
  },
  [11325] = {
    ID = 11325,
    CnID = "唤醒体故事@深海淑女·故事三",
    BaseSortID = 80,
    ActorIndex = 15576,
    Title = "AwakerStory_11325_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11325_Content|「你是肩负着光荣使命的存在，是祂重现于世的希望。」\n「做个好孩子，听话……待祂再度醒来，所有人都能够生活在不朽的永恒国度。」\n连出生也无法公开于世的隐秘之女，因某些理由成为了蹈海主祭的珍宝。无人在意的可怜婴孩摇身一变，成为了命运与神秘文明相连的圣女。\n那位苦行圣母亲手将她抚养长大，供奉与崇拜从小便围绕在她身边，只要是她想要的东西，总会有人双手奉上。\n如果融蚀现象不曾出现，「神明」的容器不曾衰弱，那她未来只会接过主祭的衣钵，按部就班地立于教徒之上。\n然而，她所获得的一切，都在某日向她索取了沉重的代价——她从未希冀过的命运，早已为她安排了无法反抗的结局。\n成为神祇之母，诞下预言之子——所谓圣女光荣的牺牲，不过是要她欣然地献出肉身与性命。\n第二颗心脏在她胸膛里开始跳动的那日，她的灵魂就成了奔腾的洪流，注定要消失在时间中。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    ConditionType_1 = "StageFirstClear",
    ConditionPara_1 = {8177},
    UnlockDesc = "AwakerStory_11325_UnlockDesc|同调率等级达到7",
    UnlockDesc_1 = "AwakerStory_11325_UnlockDesc_1|通关主线普通第5章「风暴之眼」"
  },
  [11305] = {
    ID = 11305,
    CnID = "唤醒体故事@深海淑女·故事四",
    BaseSortID = 81,
    ActorIndex = 15576,
    Title = "AwakerStory_11305_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11305_Content|目中无人的骄纵只不过是一重虚张声势的盔甲。在那精致的洋裙之下，包裹着一颗无人知晓的叛逆之心。\n身居被神圣叙事虚构的美好牢笼之中，墨菲比任何人都知晓人的伪善，神的伪善：教众看着她的眼神，不过是畏惧和怜悯，「养育者」对她的关爱，不过是对祭品的照料。使命的终点不会是荣耀，而是自己的死亡——她已然知晓结局，又岂会沉溺于教义所描摹的遥远王国。\n造神的计划，旧王的复苏，太多不切实际的众望被寄托于她——却从未有人关心过，她自己是否愿意为了不确定的未来接受必死的命运。\n金丝雀不愿永远困于笼中，于是振翅扑向布满荆棘的篱墙。决意赌上性命挣脱命运束缚的她，接下来要自己决定翱翔的方向。\n「我叫墨菲……可别想指挥本小姐！什么事该做，什么事不该做，我自己心中有数。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    ConditionType_1 = "StageFirstClear",
    ConditionPara_1 = {8177},
    UnlockDesc = "AwakerStory_11305_UnlockDesc|同调率等级达到9",
    UnlockDesc_1 = "AwakerStory_11305_UnlockDesc_1|通关主线普通第5章「风暴之眼」"
  },
  [11185] = {
    ID = 11185,
    CnID = "唤醒体故事@海之使徒·简介",
    BaseSortID = 82,
    ActorIndex = 15582,
    Title = "AwakerStory_11185_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11185_Content|身披黑纱，长袍之下掩藏着弥利亚姆瘦骨嶙峋的身躯。\n她静默无声，呈现出一副交织着虔诚与悲苦的面容，如同壁画当中的圣母像那般，带有无尽的神秘意义。\n她倾注全部身心，等待一个特殊的时刻。\n就快近了，那约定之日即将来临……",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11185_UnlockDesc|唤醒体等级达到1级"
  },
  [11254] = {
    ID = 11254,
    CnID = "唤醒体故事@海之使徒·故事一",
    BaseSortID = 83,
    ActorIndex = 15582,
    Title = "AwakerStory_11254_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11254_Content|人类将于本世纪登陆极地的传言愈演愈烈，在此情况下，弥萨格大学与密斯底亚协定审查会达成合作，组成了联合调查队。\n联合调查队于A.F.3@1年12月深入艾尔沃斯冰原，目的是在世俗探险队登陆前，回收可能存在的神秘学产物。\n……\nA.F.3@1年12月10日，约翰森调查员失足落入冰洞，意外发现冰原下存在着一处空洞。海拔太低了，融冰将在三日内淹没空洞，我们需要在气温继续爬升前完成探索。\nA.F.3@1年12月12日，有理由相信，世界上存在一个长期使用空洞作为祭坑的教团。在空洞底部，我们发现了不计其数的类人生物骨骼。是的，类人生物，其颅骨上连接了部分鳍状软骨。\n……\nA.F.3@1年12月13日，该死，该死该死该死！在骨山最上方，调查员发现了近期死亡的人类遗骸！！！\n教团可能尚未退出极地，基于审查会那愚蠢的「坚持」，此行没有允许唤醒体调查员同行，我们必须赶紧离开！\n——《关于封锁威尔德海航线的动议书·其一》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11254_UnlockDesc|同调率等级达到3"
  },
  [11196] = {
    ID = 11196,
    CnID = "唤醒体故事@海之使徒·故事二",
    BaseSortID = 84,
    ActorIndex = 15582,
    Title = "AwakerStory_11196_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11196_Content|弥利亚姆在校内过着简朴的苦行生活。独处，静思，默祷，清洁，劳作，周而复始，日复一日。\n他人的敬畏与戒备，议论与好奇，她都漠然处之。在远离故国的校园中，她似乎找到了新的精神修行方式。\n事实上，她并不在意与人交谈。只要你愿意分出一点时间，听她讲述那位不朽神祇的伟大，讲述存在于史前的遥远文明与贤明幼王统治的永恒国度。每谈及此，她的眼神中就会流露出听者不曾得见的怜悯。\n值得注意的是，弥利亚姆对图鲁抱有着异常的执著与尊敬，尽管图鲁没有对她表现出任何特殊的态度。\n如果有与弥利亚姆交涉的必要，拜托图鲁帮忙可能会使局面发生有利的转变。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11196_UnlockDesc|同调率等级达到5"
  },
  [11247] = {
    ID = 11247,
    CnID = "唤醒体故事@海之使徒·故事三",
    BaseSortID = 85,
    ActorIndex = 15582,
    Title = "AwakerStory_11247_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11247_Content|她诞生于人类史记载之前，已然无处考证的旧日文明。\n在那里，来自群星的子民建有辉煌的国度与不朽之神的庙宇。她在信仰中长大，从小虔心敬神，立志成为神明使徒。\n然而，神明的感召岂是如此易得，她渴求着奇迹与灵幻，却一次也不曾得见。\n直到图鲁即位为王，勤勉如她亦终于升上大祭司之位——那是她永生难忘的一刻，极度的恍惚与喜悦充盈着她的灵魂，令她的精神为之震颤。\n她终于得见奇迹，她终于领悟真意：这位幼王便是她所渴求的，不朽者在人间的化身。\n数年之后，一场覆灭文明的大洪水降临。她从图鲁口中听取了关于不朽的最后一个预言，然后返回神殿祈祷直到最后一刻。\n而后几度沧海桑田，新的人类重新在陆地上繁衍生息，史前之事再也无人知晓。\n自此，弥利亚姆的试炼才刚刚开始。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11247_UnlockDesc|同调率等级达到7"
  },
  [11163] = {
    ID = 11163,
    CnID = "唤醒体故事@海之使徒·故事四",
    BaseSortID = 86,
    ActorIndex = 15582,
    Title = "AwakerStory_11163_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11163_Content|未受感召者是可怜的，因其无法理解不朽的真意。世俗的纷争是无谓的，因其只是过程中的浅薄消遣。\n我曾直视，我曾品尝，我早已明悟此身使命。\n但是，但是啊……命运是何等残酷！您为什么……没有再次选择您最忠诚的祭司？\n——一定是您在赐予我试炼，您在考验我的信念。我在离故国最遥远的地方，在没有您的恩泽的时刻，我的信念经由万年，从未改变。\n我未能成为那个迎接您重生的人，但我为您的重生做了一切准备。我会为您另寻一片永恒的国土……不甘与荣幸皆在我身，我只能独自负担这份责任……\n请原谅我丑陋的嫉恨。只要能再度得见您的威仪，只要能再度建起您的王国，我愿去做任何事。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11163_UnlockDesc|同调率等级达到9"
  },
  [11170] = {
    ID = 11170,
    CnID = "唤醒体故事@沉睡之主·简介",
    BaseSortID = 87,
    ActorIndex = 15563,
    Title = "AwakerStory_11170_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11170_Content|年幼的王沉睡于王座之上，于梦醒时分示下诏谕，权威遍及天下王土。\n夕日未落，王已然感到疲倦。他厌倦了自身的权能，也厌倦了超人的智慧，厌倦了信徒狂热的崇拜和供奉，也厌倦了超越万古的长梦。\n没人知道他在漫长的睡眠中都梦到了什么，但他们应当庆幸自己享有此等无知的幸福。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11170_UnlockDesc|唤醒体等级达到1级"
  },
  [11354] = {
    ID = 11354,
    CnID = "唤醒体故事@沉睡之主·故事一",
    BaseSortID = 88,
    ActorIndex = 15563,
    Title = "AwakerStory_11354_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11354_Content|在此之前，我们所知的人类最古老的文明起源于双河地，有大量扎实的考古学资料可以证明这一点。\n不过，人类总是不会满足于已知之物，当面对浩瀚无垠的幽暗海洋时，人们不会停止向着未知的海洋扬帆远航。\n也许我们不是第一次得到提醒与暗示。神智学家们曾提出过这样的假说：宇宙乃是一个令人敬畏的循环，而今我们的世界与人类本身，只是其中的短暂一环。\n有太多事物无声湮灭在循环之中，没留下一丝可供论证的凭据——这还是值得庆幸的，有些力量太过久远极端，哪怕只是残存的遗迹，都能够对我们的时代产生不可估量的影响。\n——例如这一次，「警戒号」船员在南洋海底的意外发现，至少将人类对史前文明的认知拓展到了数万年前。\n我们由此得知了一个存在国家、君主与特殊信仰的文明，毁灭于一场世界性大洪水中，长久地沉眠于海底。\n若没有密斯底亚协定审查会在封锁工作上的协助，人类历史或许就将被改写——而如今的世界，还没有做好面对颠覆的准备。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11354_UnlockDesc|同调率等级达到3"
  },
  [11280] = {
    ID = 11280,
    CnID = "唤醒体故事@沉睡之主·故事二",
    BaseSortID = 89,
    ActorIndex = 15563,
    Title = "AwakerStory_11280_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11280_Content|有的唤醒体会在醒来后表现出对新躯壳、新生活的不适应，而有的则迅速接受了现状，较为主动地开始了第二次生命。\n图鲁不属于任何一种，从未有人像他这样露骨地表现出对当前世界的兴致缺缺。\n他的素质极为优秀，也许他对当下世界的形势与危机也早有洞悉，但他宁愿把大把的时间用于睡眠。\n尽管并非出自本人的愿望，他在学校的人类与唤醒体之间也颇有名气。研究员们观察着他的一举一动，时不时发上几篇论文；考古学系、天文学系经常发来各种名目的学术研讨邀请，大部分都会指名请他参加。\n图鲁在唤醒体之间也有相当大的影响力：墨菲一看见他就闷闷不乐，戈利亚似乎总想与他暗中较劲，弥利亚姆则将他的每一句话奉为圣旨。\n对于这些，他从未表现出什么特殊的态度，没有期待，也没有要求。\n有时，他会随心所欲地回应部分请求，有时则不会。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11280_UnlockDesc|同调率等级达到5"
  },
  [11349] = {
    ID = 11349,
    CnID = "唤醒体故事@沉睡之主·故事三",
    BaseSortID = 90,
    ActorIndex = 15563,
    Title = "AwakerStory_11349_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11349_Content|被从万千孩童中选出，被推上王座时，图鲁还不及那青金石御座高。\n但无人敢对他的漫不经心与久睡不醒置喙——所有人都知道，这是王正在聆听神谕的证明。\n贤明幼王所做的决断，必然会解决难题；所说出的预言，必然会应验。\n图鲁也就接受了这样的生活：进入「神明」的梦中，与那无法被理解的存在相见，以神谕治理国家，再度陷入沉睡……\n这个文明的运转，是由神明意志所决定的。顺势而下，应运而为，自己只要当好这独一无二的「传话人」便足矣。\n然而，图鲁也有唯一未能说出口的预言：国家将因洪水而覆灭，文明终将葬身海底。\n正因通晓一切，才更知毁灭无可改变——但至少在最后的时间里，不要让他们生活在恐惧与彷徨中。\n这是他身为国王，而非「神明代行者」所作出的决断。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11349_UnlockDesc|同调率等级达到7"
  },
  [11316] = {
    ID = 11316,
    CnID = "唤醒体故事@沉睡之主·故事四",
    BaseSortID = 91,
    ActorIndex = 15563,
    Title = "AwakerStory_11316_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11316_Content|超人的智慧给身体带来了过大的负担，他每日要昏睡十五小时以上，清醒时也总是困倦不已。\n在睡梦之中，他有时能感受到诸神的愤懑；有时能梦到交错的时空；有时甚至能步入深处，直面神明……\n他从未向神明祈求过启示与预言，然而不管怎样逃避，预言总会应验。\n他从未要求任何供奉，被崇拜、被敬畏都是他人擅自为之，他对一切全无兴趣。\n重生也不过是打扰了他的一场万古长梦。\n不必呼告，不必祈求。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11316_UnlockDesc|同调率等级达到9"
  },
  [11336] = {
    ID = 11336,
    CnID = "唤醒体故事@原初信徒·简介",
    BaseSortID = 92,
    ActorIndex = 15575,
    Title = "AwakerStory_11336_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11336_Content|必须留心，她那冷静、知性的话语具有着令人失神的魅力。不要好奇异形的头颅之下是否有另一副容貌，只需了解她对于这副类人的身体抱有长久的不满。\n她的灯火曾诱引着飞蛾，也曾将迷途者置于死地，而如今那其中似乎正透露出迷途者的茫然。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11336_UnlockDesc|唤醒体等级达到1级"
  },
  [11264] = {
    ID = 11264,
    CnID = "唤醒体故事@原初信徒·故事一",
    BaseSortID = 93,
    ActorIndex = 15575,
    Title = "AwakerStory_11264_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11264_Content|过去三年，蒙格三角海域发生了大量船只遇险事故，并伴有数起整船失踪事件。\n一名水手作证称，在参与事故救援时，他曾于遇险船只的甲板上目击到一名「头部发光的女人」。\n外勤调查员闻讯赶往蒙格三角海域，但船只一度失去音讯。当增援队伍找到船只时，该先遣船已经失去动力，正随洋流漂向蒙格三角中心。所有船员高度缺水，极度虚弱，并自述产生了强烈的幻觉。\n在对船员进行医疗检查时，从艾佛斯调查员的随身物品中发现了银芯，但调查员本人始终否认船只与唤醒体发生过接触。\n该银芯后被唤醒体系封存，编号6291-S-S-01，计划于A.F.315年作为预科调查员唤醒教学使用。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11264_UnlockDesc|同调率等级达到3"
  },
  [11331] = {
    ID = 11331,
    CnID = "唤醒体故事@原初信徒·故事二",
    BaseSortID = 94,
    ActorIndex = 15575,
    Title = "AwakerStory_11331_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11331_Content|大多数时间都静静占据着角落一隅的空间，如同真正的灯塔，在迷航时会出言将大家拉回正轨、给予指引。\n只有在与其他深海来客同处一室时，灯火才能照出她疯狂与偏执的影子。\n安静知性的外表之下，法洛思出人意料地对远洋航行颇具心得。尽管诱拐、献祭海员的嫌疑尚未洗脱，目前仍处于守密人的监管状态下，但法洛思还是帮助校方修订了不少航海相关资料。\n——根据校方合作船舶的水手反馈，法洛思的修订意见虽然有效，但经常会有意无意将航向引往蒙格三角海域。\n校方在获悉此事后，禁止了法洛思接触一切海洋相关资料。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11331_UnlockDesc|同调率等级达到5"
  },
  [11268] = {
    ID = 11268,
    CnID = "唤醒体故事@原初信徒·故事三",
    BaseSortID = 95,
    ActorIndex = 15575,
    Title = "AwakerStory_11268_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11268_Content|真神最虔诚的信徒，国王最忠实的臣民，用信仰之光照亮朝圣之路。\n永恒之国的倾塌沉没，于法洛思而言就像城楼失去了地基，藤蔓失去了土壤。对永恒之国的信仰支撑着她在世间浮游，但久寻不见的哀苦与无尽的孤独最终压垮了可怜的旅人。\n法洛思深深潜入她热爱又憎恶的大海，掀起滔天巨浪，海水翻腾犹如记忆中的祭礼焰火般绚烂，让她感到了丝丝慰藉。\n在被英雄斩下头颅时，那如炬目光看向的，应也是她无法割舍的永恒之国吧。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11268_UnlockDesc|同调率等级达到7"
  },
  [11366] = {
    ID = 11366,
    CnID = "唤醒体故事@原初信徒·故事四",
    BaseSortID = 96,
    ActorIndex = 15575,
    Title = "AwakerStory_11366_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11366_Content|回巢、返乡、归家，随便用哪个人类词汇形容她的愿望都无所谓。就算以唤醒体的身姿现世，她也无法忘却魂牵梦绕的国度。\n海底火山的呼吸不再低鸣耳畔，深海幻梦也已经是模糊的图像，回归永恒之国的执念却日渐狂热。\n小心她一时的温驯，为了回到王的御座之下，她甘愿付出一切。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11366_UnlockDesc|同调率等级达到9"
  },
  [11306] = {
    ID = 11306,
    CnID = "唤醒体故事@海月·简介",
    BaseSortID = 97,
    ActorIndex = 15573,
    Title = "AwakerStory_11306_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11306_Content|在孤寂之中迎来了灭亡的海洋精灵，于陆地上获得了奇迹般的延续。\n无论是生来乐天，还是为了逃避苦痛而选择遗忘，直率的纯真都散发着无穷吸引力，让人不由自主加入她的阵营——这或许是她扩大「同伴队伍」的小小计谋也说不定。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11306_UnlockDesc|唤醒体等级达到1级"
  },
  [11231] = {
    ID = 11231,
    CnID = "唤醒体故事@海月·故事一",
    BaseSortID = 98,
    ActorIndex = 15573,
    Title = "AwakerStory_11231_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11231_Content|在康沃尔郡南部海岸进行考察的过程中，我发现了一处不存在于任何地图中的废弃小村。经过勘察，我们确认了这是一处因融蚀现象爆发而被「抹去存在」的村落。\n在村落中，我们收集到了大量的异常海洋生物样本，包括：呈现食肉特性的砗磲、具有耐热能力的冰海天使，其中最违反常理的应为遍布各处的「两栖水母」。\n在一处已经成为水母巢穴的旧屋中，我们回收到了呈流体态的银芯，重量约为11.85德拉姆。将这份银芯带离现场时，考察队员遭受了异化水母的袭击，幸运的是，这些异常的两栖水母所有腺体都已腐烂，不再具有神经毒性。\n——《A.F.308年第三次生物系田野考察记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11231_UnlockDesc|同调率等级达到3"
  },
  [11183] = {
    ID = 11183,
    CnID = "唤醒体故事@海月·故事二",
    BaseSortID = 99,
    ActorIndex = 15573,
    Title = "AwakerStory_11183_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11183_Content|不要对水母的知性抱有什么期待，奥瑞塔并不能理解自己经历了什么，唯一能肯定的，就是她曾在那个无人村落居住过。每每聊到过去的故事，她都会用不懂装懂来转移话题，因此奥瑞塔对融蚀现象、灾厄异动等学科研究几乎起不到助力。\n但作为唤醒体中难得性格无害的个体，奥瑞塔深受唤醒体系师生喜爱，主导了融蚀生物学研究的诃勒特也对她格外关心。\n顺便一提，与水母群体意识融合的她获得了分裂增殖的能力。即使增殖出的只是普通水母，奥瑞塔也会兴奋地举着「同伴」挨家挨户炫耀——虽然分不清同伴个体的她并不清楚，自己每次捧出来展示的都是同一只水母。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11183_UnlockDesc|同调率等级达到5"
  },
  [11234] = {
    ID = 11234,
    CnID = "唤醒体故事@海月·故事三",
    BaseSortID = 100,
    ActorIndex = 15573,
    Title = "AwakerStory_11234_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11234_Content|三月\n欢迎来到大西洲巡回水族馆！我是本次的解说员奥瑞塔，登上水母篷车时请小心脚下哦！\n水箱里展示了来自热带海域的珍稀水母，锵锵！请看——\n四月\n这、这是怎么回事……大家去哪里了……馆长！馆长！水母们，奥瑞塔的水母们都消失了！\n水族馆从来没有水母展品？可我明明记得……\n五月\n因为展品太少，没有客人所以无法经营下去……呜……大家再见……\n如果，如果还能巡回展出的话，一定要再来找奥瑞塔哦！\n六月\n奥瑞塔好累……生病了吗……\n呀……是水母们！抱歉，奥瑞塔没办法为大家撒硅藻了。\n等奥瑞塔好起来，大家再一起游泳吧……",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11234_UnlockDesc|同调率等级达到7"
  },
  [11200] = {
    ID = 11200,
    CnID = "唤醒体故事@海月·故事四",
    BaseSortID = 101,
    ActorIndex = 15573,
    Title = "AwakerStory_11200_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11200_Content|海水格外澄澈的渔村，在仲夏夜被装点成银河的海岸，洋溢出巡回篷车的轻快笑声——那些已经不存在的记忆会时不时闪回，又随即被抛之脑后。\n只要身边有同伴不断涌现，就总能创造新的回忆，况且水母们也在呢——奥瑞塔便是如此认为的。\n毕竟在随波逐流中繁衍、增殖，以数量堆积对抗强敌，是水母的天性与宿命。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11200_UnlockDesc|同调率等级达到9"
  },
  [11318] = {
    ID = 11318,
    CnID = "唤醒体故事@石之眼·简介",
    BaseSortID = 102,
    ActorIndex = 15591,
    Title = "AwakerStory_11318_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11318_Content|不要靠近、不要触碰、不要直视、不要怜惜，世间或许本就存在只适宜独居于黑暗之中的生灵。\n纵然这并非她的本意，但若你因她孱弱的身形、怯懦的语调、稚气的服饰，而爱怜地直视她的双眼，便会堕入永恒的凝固与寂静之中。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11318_UnlockDesc|唤醒体等级达到1级"
  },
  [11347] = {
    ID = 11347,
    CnID = "唤醒体故事@石之眼·故事一",
    BaseSortID = 103,
    ActorIndex = 15591,
    Title = "AwakerStory_11347_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11347_Content|据《石之灾厄事件记录Ⅲ》记载，守密人自伦蒂尼恩济贫院带回这枚银芯。和银芯一同带回的还有一只小小的、遍布补丁的布熊玩偶。\n这枚银芯重约2.1克，纤细光洁，形似泪滴。与银芯产生直接接触的实验员会陷入凝滞状态，保持触碰银芯的姿势，直至被其他人唤醒。为防止误触，研究员朵尔将该枚银芯保存于封闭玻璃圆球内，替换了布熊玩偶的眼睛。\n「它看上去，好像每天都在落泪。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    ConditionType_1 = "StageFirstClear",
    ConditionPara_1 = {8030},
    UnlockDesc = "AwakerStory_11347_UnlockDesc|同调率等级达到3",
    UnlockDesc_1 = "AwakerStory_11347_UnlockDesc_1|通关主线普通第1章「东区秘事」"
  },
  [11245] = {
    ID = 11245,
    CnID = "唤醒体故事@石之眼·故事二",
    BaseSortID = 104,
    ActorIndex = 15591,
    Title = "AwakerStory_11245_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11245_Content|詹金贴在心理咨询室的门缝前，竖起耳朵偷听。\n茜尔维娅的声音温和而亲切，艾继丝的则如蚊子嘤咛一般，断断续续难以辨析。\n「艾继丝，你要学会拒绝。」\n「可是我……添麻烦……想……报答……」\n「艾继丝没有给任何人添麻烦。你看，守密人允许你在学校里自由活动，对你不加任何拘束，不就是信任你的表现吗？」\n「和我约好了，别再随便答应其他人的无理请求。尤其是卡拉布，你替她关禁闭和扫除，才会给守密人添麻烦哦？」\n「詹金，你怎么进来了？」\n「詹、詹金！是、是我自己答应卡拉布的！你、你别冲动！」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    ConditionType_1 = "StageFirstClear",
    ConditionPara_1 = {8030},
    UnlockDesc = "AwakerStory_11245_UnlockDesc|同调率等级达到5",
    UnlockDesc_1 = "AwakerStory_11245_UnlockDesc_1|通关主线普通第1章「东区秘事」"
  },
  [11344] = {
    ID = 11344,
    CnID = "唤醒体故事@石之眼·故事三",
    BaseSortID = 105,
    ActorIndex = 15591,
    Title = "AwakerStory_11344_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11344_Content|十二年前的一个清晨，伦蒂尼恩东区。济贫院门口出现一个被围巾重重包裹的女婴。这在人人自危的东区本不算稀罕事，但让年少的莎拉感到愤怒的是，寒冬料峭，残忍的遗弃者将女婴口鼻也裹在了围巾之下，加之这名女婴不哭也不闹，若非那双澄澈明净的眼睛在拍击下眨巴了几下，莎拉几乎以为她已经死了。\n正当莎拉以为自己要成为又一个乖孩子的「姐姐」时，时任院长将这孩子以一雷欧坊的价格，送给了东区市场的裁缝。\n「我们养不起那孩子，成为裁缝家的女儿，她虽然会吃点苦头，但至少能学一门手艺。」\n出生不过两个月的孩子，谈什么「手艺」呢？\n莎拉感受着空荡荡的胃，没有反驳院长的决定。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11344_UnlockDesc|同调率等级达到7"
  },
  [11232] = {
    ID = 11232,
    CnID = "唤醒体故事@石之眼·故事四",
    BaseSortID = 106,
    ActorIndex = 15591,
    Title = "AwakerStory_11232_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11232_Content|恐惧光、恐惧视线、恐惧爱、恐惧拥抱。\n渴望光、渴望注视、渴望爱、渴望拥抱。\n如果自己不会给他人带去伤害就好了，如果自己不会给他人添麻烦就好了，如果自己像提尤格一样是个聪明的孩子，如果自己像詹金一样是个勇敢的孩子，如果自己像……\n那么，就可以不被烈日灼痛，就可以不被他人嫌恶了吧？\n怀着不切实际担忧的玩偶，自阴影之中，向阳光的交界处胆怯地伸出白皙得几近透明的小手。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11232_UnlockDesc|同调率等级达到9"
  },
  [11297] = {
    ID = 11297,
    CnID = "唤醒体故事@破链者·简介",
    BaseSortID = 107,
    ActorIndex = 15587,
    Title = "AwakerStory_11297_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11297_Content|她并非饮血而生，曾几何时，她也沐浴着昙花般热烈而短暂的温情。背叛与牢狱之灾浇灌出了反叛的烈焰，复仇的火光烧遍麦西亚，在绵绵恨意的熏染中，她的内心已经不再向任何人敞开……",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11297_UnlockDesc|唤醒体等级达到1级"
  },
  [11294] = {
    ID = 11294,
    CnID = "唤醒体故事@破链者·故事一",
    BaseSortID = 108,
    ActorIndex = 15587,
    Title = "AwakerStory_11294_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11294_Content|埃夫罗塔斯考古团队受怪病所扰已有十天之久，目前情况仍未好转。\n怪病来得毫无征兆，但势头凶猛。患者一般会出现严重幻觉，伴随肢体感觉缺失、感官缺失等症状，并随着时间发展恶化，最终导致半身乃至全身瘫痪。虽然目前看来，疾病的传染范围局限于埃夫罗塔斯河西岸的考古现场，患者也多为考古现场的工作人员及驻场学者，但当局不能排除其向四周扩散的可能性。\n一名曾在考古现场工作过的工人向记者透露，怪病在十五天前已经出现苗头——正是在埃夫罗塔斯镣铐出土的那天。有关注相关考古新闻的读者想必会对这副保存完好、没有一丝锈蚀痕迹，却确确实实来自于古早文明的镣铐有印象。它已在昨日抵达雷欧王国，由弥萨格大学接手后续研究。而怪病与镣铐之间的联系，则更具有神秘主义色彩。\n「自从把它挖出来，营地里就变得不对劲了。」那位工人向记者指出，「很多人做怪梦，梦到一个被锁链锁在牢笼里的女孩，还有人半夜……这就是诅咒，是镣铐的诅咒！不可能有其他解释。」\n截至报道日，相关部门已经接管该区域，并严禁任何人员进出。埃夫罗塔斯考古行动现已彻底停摆。\n——《古老的诅咒？怪病席卷埃夫罗塔斯考古团队》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11294_UnlockDesc|同调率等级达到3"
  },
  [11261] = {
    ID = 11261,
    CnID = "唤醒体故事@破链者·故事二",
    BaseSortID = 109,
    ActorIndex = 15587,
    Title = "AwakerStory_11261_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11261_Content|希洛是一把锐利冰冷的刀。\n与她一同执行过任务的唤醒体都说，希洛是个很好用的武器，她足够强大，总是能完成任务，只要得到了击杀指令，不管面对的是多么强大的敌人，她也必定会突入重围，取走敌方的头颅。\n但仅此而已。\n她或许会保护同行之人，但那不过是对指令的遵从，而不是对队友的关心。她不信任他们，他们自然也无法将自己的后背交给她。\n他们不知道的是，对她而言，朝向己方的锋刃是卑劣的，是下作的，是应当被惩处唾弃的。\n她深知背叛的可恶，因而绝不会对同伴刀剑相向。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11261_UnlockDesc|同调率等级达到5"
  },
  [11275] = {
    ID = 11275,
    CnID = "唤醒体故事@破链者·故事三",
    BaseSortID = 110,
    ActorIndex = 15587,
    Title = "AwakerStory_11275_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11275_Content|女孩穿着朴素的衣裙，皮肤还因为刚才粗暴的洗刷而隐隐作痛。她不明白自己为什么会被士兵们带到这里来，贵族老爷的家不是奴隶可以随意进出的地方，而她还远远不到来这里伺候的年纪。\n穿着雪白长袍的夫人端坐在椅子上，女孩低垂着头，因为畏惧和紧张而不住颤抖。\n「我果然没看错……」夫人说，「很像，真的很像。」\n像？是说她像什么人吗？\n「很好，太好了。」夫人开心地拍了拍手，「就是你了。从今天开始我就是你妈妈，记住了吗？」\n妈妈？可是她已经有妈妈了。妈妈在家里，在她被带走时大声地哭。\n她的妈妈怎么办？\n疑惑与不解在女孩脑海中萦绕，她想询问答案，却也明白，主人的意思就是奴隶的命令，违背命令的奴隶则会被严厉惩罚。\n「记住了，夫人。」\n「真是个乖孩子。我想想……就叫你希洛吧，喜欢这个名字吗，希洛？一定很喜欢吧。来，穿上这个裙子给妈妈看看。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11275_UnlockDesc|同调率等级达到7"
  },
  [11378] = {
    ID = 11378,
    CnID = "唤醒体故事@破链者·故事四",
    BaseSortID = 111,
    ActorIndex = 15587,
    Title = "AwakerStory_11378_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11378_Content|高高在上的夫人拉着她的手，告诉她，自己将给予她世上所有的爱。\n她相信了夫人的温柔和老爷的纵容，相信了每一个微笑，每一个拥抱，却不知道自己在他们眼中不过是一个宠物，一旦威胁自身，就可以随时抛弃。\n他们亲手将她扔入牢笼，将她的信任砸得粉碎——但无论是狱卒的鞭打还是族人的折磨，都没有至亲之人的背叛来得那般疼痛。\n恨，好恨，恨他们用谎言换取她的真心，恨他们用她的人生造就了这场苦痛的闹剧。如果这就是相信他人的结果，那她将永远做自己的依靠。\n她的信赖只给予她自己。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11378_UnlockDesc|同调率等级达到9"
  },
  [11353] = {
    ID = 11353,
    CnID = "唤醒体故事@渴血患者·简介",
    BaseSortID = 112,
    ActorIndex = 15597,
    Title = "AwakerStory_11353_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11353_Content|嘘……不用惊慌，那只是潮湿地窖里老鼠腐烂的声音。从最黑暗的深渊底部，滋生出猩红的欲望。被囚禁的灵魂渴望鲜血，一如目盲者祈求光明，荒淫者沉迷爱欲。取悦她的方法也很简单：尽情地责骂她、羞辱她吧。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11353_UnlockDesc|唤醒体等级达到1级"
  },
  [11317] = {
    ID = 11317,
    CnID = "唤醒体故事@渴血患者·故事一",
    BaseSortID = 113,
    ActorIndex = 15597,
    Title = "AwakerStory_11317_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11317_Content|……\n实验日期：A.F.@1年@2月\n实验目的：观察记录融蚀患者嫁接组织器官后产生的变异反应\n实验步骤：@3@4\n选取实验体死去的哥哥进行嫁接实验，以观察直系亲属间的排异反应。这个可怜虫在躲避警察抓捕时被数枪打死@3实验很成功，伤口变红并增生出触手……血液宛若红宝石一般喷涌而出。\n@3@3\n实验者展现出惊人的忍耐力，她拒绝注射吗啡。\n实验后渴血欲增强，性情……难以形容，总之不是我擅长应付的类型。\n——节选自赫伯特《融蚀实验记录·第四组@1号》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11317_UnlockDesc|同调率等级达到3"
  },
  [11370] = {
    ID = 11370,
    CnID = "唤醒体故事@渴血患者·故事二",
    BaseSortID = 114,
    ActorIndex = 15597,
    Title = "AwakerStory_11370_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11370_Content|远离图书馆地下、墓地和雷娅，一直是学生们的共识。\n苍白羸弱的少女热衷激怒他人，随后愉悦地品尝对方的怒意，像伊甸园中的蛇妖一般，适时抛出隐秘的诱饵：来伤害我呀……来呀……\n大多数时候，她会收获白眼、疑惑与咒骂。唯有一次，她终于得尝所愿——尤乌哈希毫不犹豫将她揍了一顿，甚至取走她一颗牙齿。这是个对旁人毫无探究欲的家伙，一切在他看来都是理所应当。\n望着战士潇洒离去的身影，雷娅欣慰地笑了，软绵绵的晨光洒在她身上，又是晴朗的一天。\n她还有好多好多牙齿，都取走吧……谁都好，都取走吧……",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11370_UnlockDesc|同调率等级达到5"
  },
  [11313] = {
    ID = 11313,
    CnID = "唤醒体故事@渴血患者·故事三",
    BaseSortID = 115,
    ActorIndex = 15597,
    Title = "AwakerStory_11313_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11313_Content|A.F.@2年@1月\n亲爱的卡文迪许勋爵：\n\n请原谅，我冒昧请求弗雷管家为我取来了纸笔，强撑着最后一丝理智与体面写下这封信。自从我身患恶疾，再也没能见到母亲、波比还有您，这份思念足以令我发疯。\n被关在地下室已经……353天了？我不知道，也许是326天。\n这里很冷，到处是腐烂的味道。我的伤口流淌着黑色的黏液，又被老鼠啃得不成样子。但没关系，痛苦是好的，它让人保持清醒。\n「邪恶的吸血鬼」、「使家族蒙羞」……将我隔离无疑是明智的决断。我的灵魂早已被魔鬼控制，写下这封信的时候，我刚吸干一位死去流浪汉的血。弗雷管家说，是您命人从街上找来的。虽然味道有些变质，但我还是很高兴，原来您是在意我的。\n此外……能否提供一条毛毯？我现在没有任何能蔽体的衣物，伦蒂尼恩的冬天实在是太冷了。\n直到现在，我也十分怀念，幼时我们一起在韦廷宅邸度假的时光。\n\n您真诚的妹妹\n雷娅\n——节选自《肯辛顿吸血鬼事件·案卷综述：证物C-601》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11313_UnlockDesc|同调率等级达到7"
  },
  [11348] = {
    ID = 11348,
    CnID = "唤醒体故事@渴血患者·故事四",
    BaseSortID = 116,
    ActorIndex = 15597,
    Title = "AwakerStory_11348_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11348_Content|铁锈味在空气中蔓延。\n那是……「食物」的味道。\n少女缓缓睁开眼。长期被注射大剂量镇静剂，她的大脑一片混沌。面前躺着一只被咬断了喉颈的比格犬，似乎叫……斑比？波比？\n少女刚陷入回忆，腹部又传来剧痛——她被「食物」袭击了。此刻，被绑来的流浪汉正颤抖着双手，似乎在高声呐喊。\n「吸血鬼！怪物……怪物！！」\n然而，少女置若罔闻，只出神地抚摸着腹部的鲜血。\n大量温热的鲜血，像是滑腻的绸缎，欢快地溢出伤口，蔓延一地。\n原来，她还会痛、还会流血。\n少女无声落泪。她伸出沾满鲜血的细弱双手，轻抚上「猎物」的面颊。\n「接下来，能请你再用力一些吗？」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11348_UnlockDesc|同调率等级达到9"
  },
  [11224] = {
    ID = 11224,
    CnID = "唤醒体故事@红夫人·简介",
    BaseSortID = 117,
    ActorIndex = 15584,
    Title = "AwakerStory_11224_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11224_Content|如簧巧舌是花苞散发的蜜香，王臣是簇拥着摇曳花蕊的蜂蝶。\n欲望浇灌出的荆棘，已于不知觉间将花窗紧紧缠绕。\n即便人格为世人诟病，双手被冠冕划得鲜血淋漓，她也不会放弃已被拥入怀中的权力。\n毕竟，这才是蔷薇绽放所需的真正养分。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11224_UnlockDesc|唤醒体等级达到1级"
  },
  [11377] = {
    ID = 11377,
    CnID = "唤醒体故事@红夫人·故事一",
    BaseSortID = 118,
    ActorIndex = 15584,
    Title = "AwakerStory_11377_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11377_Content|「沙龙」不知从何时起，悄然在伦蒂尼恩上流社会中兴起。\n在神秘的沙龙中，有人得到了让巨匠为其留下画像的机会，有人得以与首相共进晚餐，更有甚者得到了来自女王的一个承诺。\n主理人、举办地点、举办时间都是谜团，人们只知道，每个人都能在沙龙中获得自己最想要的东西。\n但无人知晓，怎样的宾客才能得到主人青眼，获得一纸邀请函。\n就连八面玲珑的德克斯特勋爵，也在沙龙主人面前吃了闭门羹。\n「非常抱歉，主人现在更偏好邀请艺术名流。」\n「贵族？请静候未来的邀请。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11377_UnlockDesc|同调率等级达到3"
  },
  [11321] = {
    ID = 11321,
    CnID = "唤醒体故事@红夫人·故事二",
    BaseSortID = 119,
    ActorIndex = 15584,
    Title = "AwakerStory_11321_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11321_Content|最初，只是一杯替代了红酒的葡萄苏打水而已。\n在无人注意的角落，索蕾尔做出楚楚可怜的模样，与两三学生共饮。\n然后，是一场小小的下午茶。\n在学生食堂，索蕾尔对学生推来的马卡龙多加推辞，流露出几分不舍与真心。\n最后，是一场瑰丽沙龙的举办，是一朵蔷薇的盛开。\n休息室被花朵与珠宝装点，艳丽的蔷薇与稚嫩的学生推杯换盏，宾主尽欢。\n新任守密人目睹了这一切，并暗自祈祷她的下一步千万不要是「成为弥萨格大学校长」。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11321_UnlockDesc|同调率等级达到5"
  },
  [11374] = {
    ID = 11374,
    CnID = "唤醒体故事@红夫人·故事三",
    BaseSortID = 120,
    ActorIndex = 15584,
    Title = "AwakerStory_11374_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11374_Content|索蕾尔知道自己是美丽的，在心中，她将这份美丽称为上天的宠爱。\n只要眼泪汪汪地祈求，人们就会对她降下垂怜；只要稍稍装作可怜，暗生情愫的玩伴就会无条件偏袒她。\n但，美丽在真正的权力面前一文不值。\n面对想要将她献给贵族换取前程的父母，索蕾尔的眼泪头一次尝到了失败的滋味。\n有人能帮帮她吗？有人能带她逃离愚昧而落后的命运吗？\n有什么东西，有什么地方……能让这份美丽成为真正的武器吗？\n在索蕾尔掩面痛哭时，搅动命运深潭的使者降临在了她的面前。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11374_UnlockDesc|同调率等级达到7"
  },
  [11281] = {
    ID = 11281,
    CnID = "唤醒体故事@红夫人·故事四",
    BaseSortID = 121,
    ActorIndex = 15584,
    Title = "AwakerStory_11281_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11281_Content|直到成为唤醒体的现在，索蕾尔也无法忘记那些对她曲意逢迎的贵族，无法忘记那一张又一张写满谄媚的脸。\n那些笑脸是何等令人作呕啊，油滑、市侩、无处不透露着对她的渴望与算计，她却不得不为这样的面容编织温柔的网。\n她要编织最缜密的网，深入到每个阴暗角落，笼络每一个人，掌握所有把柄。\n她也必须像逐渐升温的水，让那些人沉溺其中，想要摘下假面时才发现已经无法逃离。\n但反应过来时，无法逃离的人却成为了她。\n不能逃离，不能松懈，不能放弃。\n索蕾尔已经没有了回头的权利，除了立于所有人之上，她没有第二条路可走。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11281_UnlockDesc|同调率等级达到9"
  },
  [11164] = {
    ID = 11164,
    CnID = "唤醒体故事@丰穰之息·简介",
    BaseSortID = 122,
    ActorIndex = 15596,
    Title = "AwakerStory_11164_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11164_Content|满头珠翠，轻纱缱绻，内心被隐藏在极致的妍丽之下。\n总有人觉得泰旖丝是个爱慕虚荣的轻浮家伙，但这也许也只是她所戴上的面具之一。\n「呀，小哥在写些什么呢？让我也来帮忙吧——」",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11164_UnlockDesc|唤醒体等级达到1级"
  },
  [11337] = {
    ID = 11337,
    CnID = "唤醒体故事@丰穰之息·故事一",
    BaseSortID = 123,
    ActorIndex = 15596,
    Title = "AwakerStory_11337_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11337_Content|席卷世界的洪水带走了文明的积淀，却也冲刷了历史的尘埃。\n灾难过后，人们从摩苏尔旧址遗迹中窥见了几丝被遗忘的历史。\n「树」矗立在两河交汇之处，流下鲜红的树液，顺水而下浇灌文明。\n「树」永世不灭，万古长青。\n古代史学界最后认定，「树」并不存在实体，祂是一种对古代文明的隐喻，是一种精神象征。\n在无人得见的角落，种子在世界的每一处扎根。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11337_UnlockDesc|同调率等级达到3"
  },
  [11272] = {
    ID = 11272,
    CnID = "唤醒体故事@丰穰之息·故事二",
    BaseSortID = 124,
    ActorIndex = 15596,
    Title = "AwakerStory_11272_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11272_Content|弥萨格唤醒并收容着许多唤醒体，但没有人比泰旖丝更独特。\n她帮助女学生挑选约会的妆容，她帮助失意之人重拾希望，她帮助精神崩溃的调查员走出阴霾。\n像恋人，又像姐妹，更像母亲。她总能构建出名为「爱」的泥沼，悄悄使人深陷，叫人不知不觉间变得想要为她付出一切——\n在第三次阻止学生饮下泰旖丝提供的神秘液体后，唤醒体管理处颁布了针对她的限制令。\n「未经守密人陪同，严禁泰旖丝靠近所有学生。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11272_UnlockDesc|同调率等级达到5"
  },
  [11334] = {
    ID = 11334,
    CnID = "唤醒体故事@丰穰之息·故事三",
    BaseSortID = 125,
    ActorIndex = 15596,
    Title = "AwakerStory_11334_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11334_Content|@2这个名字被多次书写在历史中。\n祭司、母亲、王妃、女王、女巫……这个名字被冠上了太多不同头衔，以至于史学家至今都难以确认，到底哪个身份才能代表我们如今所认识的唤醒体。\n泰旖丝本人并不吝于与我们分享她的过去——那全都是她，又不完全是她。\n「出身高贵是她。」\n泰旖丝永远是神殿中最闪耀的女孩，身为大祭司的孩子，她像天鹅般优雅，如月光般温润。\n「于树前跪拜是她。」\n泰旖丝是「树」上最为鲜亮的叶片，虔诚让她受到了「树」的恩惠。\n「被抽走全身血液的是她。」\n灾难降临，大厦倾颓之时，古老而愚昧的文明选择了最优秀的她。\n「脉管中流淌着树汁的是她。」\n被万民敬仰之「树」，拥有自己的选择。枝条扎根于体内，给予了信徒几乎永恒的寿命。\n「但，想要覆灭文明的不是她。」\n泰旖丝想要的，从来都不是世界的灭亡。\n「可泰旖丝小姐，您想要的是什么呢？」\n「诶呀——不是说好了吗？当我们之间结出果实时，你就知道答案了。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11334_UnlockDesc|同调率等级达到7"
  },
  [11299] = {
    ID = 11299,
    CnID = "唤醒体故事@丰穰之息·故事四",
    BaseSortID = 126,
    ActorIndex = 15596,
    Title = "AwakerStory_11299_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11299_Content|祂是实际存在着的。\n祂是神明投下的目光，是神明向宇宙舒展的枝条。\n祂享受历史的壮阔，渴求着文明的繁荣。\n祂想要跨越枯萎，想要超越死亡。\n她想要低沉的吟诵、沙土与咸味的风，想要银色的树叶和摩苏尔的月光。\n妖妇、魔女、女巫……世人的眼光不过是身外之物。\n只要哪怕一滴血能够逃脱黑色侵袭，祂们就能再次将永世拥入怀中。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11299_UnlockDesc|同调率等级达到9"
  },
  [11312] = {
    ID = 11312,
    CnID = "唤醒体故事@猩红·简介",
    BaseSortID = 127,
    ActorIndex = 15598,
    Title = "AwakerStory_11312_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11312_Content|我们怎么会忘记英雄尤乌哈希？他曾是最杰出的男儿。战士跪倒在日落黄沙里，温热的鲜血将他全身浇灌。秃鹫盘旋高空，为他唱起挽歌：\n无人会用泪水尊敬你，无人会用哭泣埋葬你，只因在生前你已名扬罗马。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11312_UnlockDesc|唤醒体等级达到1级"
  },
  [11328] = {
    ID = 11328,
    CnID = "唤醒体故事@猩红·故事一",
    BaseSortID = 128,
    ActorIndex = 15598,
    Title = "AwakerStory_11328_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11328_Content|银芯编号：B-005\n出土时间：A.F.1@1年@3月\n出土地点：弗兰德低地乡间，某不知名古罗马陵墓废墟\n详情记述：银芯持有者名为路德维希·普林，因一起招魂事件被当地宗教裁判所判处火刑。普林声称在第九次神圣东征的战场上获得此银芯，随后前往布拉班特附近，与「来自外星的仆人」、「隐形的伙伴」一起，为召唤「伟大的不可名状者」举办血腥祭祀。\n记录人：华德·菲利普斯\n——《唤醒体银芯获取报告：B-005》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11328_UnlockDesc|同调率等级达到3"
  },
  [11270] = {
    ID = 11270,
    CnID = "唤醒体故事@猩红·故事二",
    BaseSortID = 129,
    ActorIndex = 15598,
    Title = "AwakerStory_11270_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11270_Content|「4:30 沿着伊希斯河晨跑6英里。中途与路过的老奶奶发生口角，并踹飞一条贵宾犬。\n……\n12:00 享用午餐。蜂蜜煎饼、橄榄开胃菜搭配……五份烤羔羊肉？难以置信。\n13:00 前往鳟鱼格斗俱乐部。战绩：10胜0负，最快记录3秒钟——对手因过于害怕而主动弃权。\n19:00 与守密人一同前往科文特剧院观赏《牧人王》，因高声发表危险政治言论被扫地出门。\n22:00 被发现徘徊在圣玛丽安医院附近，合理推测是想伺机窃取医院血包。\n以上观察结束，鉴定危险等级：SSS。」\n——节选自《汉娜的唤醒体观察笔记》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11270_UnlockDesc|同调率等级达到5"
  },
  [11332] = {
    ID = 11332,
    CnID = "唤醒体故事@猩红·故事三",
    BaseSortID = 130,
    ActorIndex = 15598,
    Title = "AwakerStory_11332_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11332_Content|卡里古拉的御用炼金术师马库斯·安提斯以大量活人为代价，炼就的「魔像」。\n由于炼成仪式的不完善，每日须饮下大量人血。为卡里古拉杀死政敌，并助其加冕为罗马皇帝。\n暴君卡里古拉即位不到四年便被谋杀。他也被愤怒而恐惧的暴民锁在其被捣毁祭坛的地下，不得不忍受饥渴近千年。\n漫长岁月中，他靠吸食老鼠的鲜血苟活，承袭自血脉深处的饥渴令他发疯。\n不够，远远不够……\n@2时期，一位黎凡特巫师找到了他，许诺助其脱困，前提是在战场上杀死勒姆瓦希人。\n还有这等好事？\n他轻松完成了任务，不过，有个小小的插曲：因太过兴奋，他一不小心杀死了战场上所有的人，并喝干了他们的血——包括巫师和他自己的。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11332_UnlockDesc|同调率等级达到7"
  },
  [11178] = {
    ID = 11178,
    CnID = "唤醒体故事@猩红·故事四",
    BaseSortID = 131,
    ActorIndex = 15598,
    Title = "AwakerStory_11178_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11178_Content|@2年，阿卡古城。\n历经千年的饥渴终于爆发，杀戮，饮血，杀戮，饮血——最终，他面前只剩一望无际的沙漠与无数干涸的尸体，就连秃鹫都害怕靠近他。\n他跪在黄沙中，哈哈大笑：畅快！真@1畅快！\n接下来，就由他亲自为这场杀戮盛宴，画下完美的句号吧。\n战士咬开自己的手腕，他吸干了自己的鲜血，也一同倒在这片猩红的血池中。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11178_UnlockDesc|同调率等级达到9"
  },
  [11203] = {
    ID = 11203,
    CnID = "唤醒体故事@迷宫蛛·简介",
    BaseSortID = 132,
    ActorIndex = 15600,
    Title = "AwakerStory_11203_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11203_Content|在历史的怒火烧尽一切前，阿格里帕都是卡普阿最耀眼的明珠。\n她恣意妄为，皮鞭总是狠狠抽向沉默的角斗士；她不喜被人直视，那会暴露她内心的软弱。但若要论起调教奴隶，阿格里帕可是专业的，或许你会有兴趣参观她卧室里二十条款式各异的皮鞭——特意为你准备的。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11203_UnlockDesc|唤醒体等级达到1级"
  },
  [11285] = {
    ID = 11285,
    CnID = "唤醒体故事@迷宫蛛·故事一",
    BaseSortID = 133,
    ActorIndex = 15600,
    Title = "AwakerStory_11285_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11285_Content|@3修建于第二萨姆尼特时期，以精美的第三庞贝和勒姆瓦希化风格装饰，这是罗马时期富裕商人阶层的典型住宅。拥有两个中庭，四个triclinia以及@1@1\n……都在那场著名的奴隶起义中被付之一炬……据同时期的逸闻记载，废墟的地底封印着巨大的苍白蜘蛛，当地人称其为「迷宫之神」，并坚信踏入蜘蛛领地的人类将在无数通道和入口中迷失方向，最终成为其子嗣的宿主。\n有趣的恐怖故事，但不会阻拦我们@2@1\n——节选自《@2废墟考古札记》\n\n……情况很糟糕，古德曼爵士。莫雷蒂一行人现已失踪多日，我们都明白这和「迷宫之神」的传说没有一点关系，但它确实令人不安。眼下我们决定提早结束考察，返回杜伦。\n另外，考古队在废墟里发现一簇银色芯状物，或许和您之前提及的@1有关……\n——节选自克拉克森·约翰逊《致古德曼的一封信》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11285_UnlockDesc|同调率等级达到3"
  },
  [11177] = {
    ID = 11177,
    CnID = "唤醒体故事@迷宫蛛·故事二",
    BaseSortID = 134,
    ActorIndex = 15600,
    Title = "AwakerStory_11177_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11177_Content|算术：零分。奥瑞塔甚至都拿了2分。\n英语：不及格。花了很长时间才理解「轮班」和「狗屎」之间的差别\n……\n历史：不及格。声称卡里古拉是最杰出的罗马皇帝，因为他修了很多竞技场\n\n危险评级：C。与其他唤醒体相处时，呈现出一定程度攻击性。威胁不大，无需特别关注\n备注：该生自理能力几乎为零（又一个被奴隶制荼毒的家伙），需要时刻关注，不能再让她把雪花膏当作洁牙剂使用了。\n——节选自A.F.313年，《弥萨格年度学生档案》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11177_UnlockDesc|同调率等级达到5"
  },
  [11229] = {
    ID = 11229,
    CnID = "唤醒体故事@迷宫蛛·故事三",
    BaseSortID = 135,
    ActorIndex = 15600,
    Title = "AwakerStory_11229_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11229_Content|就算在角斗士们彻底烧毁了训练场，将她父母的头颅挂上高墙时，阿格里帕都难以置信——这些卑贱、温顺的奴隶怎么会有这样的胆量？\n在罗马，人被分为两种：奴役别人的，被别人奴役的。\n阿格里帕是幸运的。她是卡普阿最大的角斗士训练场老板的女儿。她横行肆虐、不可一世，没有什么是她不敢做、不能做的。\n可是现在，她像一只仓皇的兔子，瑟缩在地下室的角落，外面的狂欢在她看来和地狱无异。\n奴隶起义。多么陌生的词汇。阿格里帕只有十五岁，这个世界还有太多她不理解的东西。\n她在阴影中看到一双泛着红光的眼睛。那是尤乌哈希，训练场最大的摇钱树，因太过危险常年被锁在地下。\n两人素来不合，没人知道他们当晚的交谈内容。火焰舔舐的血腥之夜结束后，阿格里帕被发现死在阴暗的地底，身旁空无一人。她不是被奴隶杀死的——有人吸干了她的鲜血，连一滴都不剩下。\n当然，她的头颅最后也被砍了下来，就挂在她父母旁边，一起迎风招展，面朝罗马的方向。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11229_UnlockDesc|同调率等级达到7"
  },
  [11210] = {
    ID = 11210,
    CnID = "唤醒体故事@迷宫蛛·故事四",
    BaseSortID = 136,
    ActorIndex = 15600,
    Title = "AwakerStory_11210_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11210_Content|那是……令人目眩的天光与热浪，纵情声色的极乐狂欢。\n欢呼声如海浪般在耳畔嗡鸣，战士在竞技场上沐浴鲜血荣光。\n少女悻悻回家，她一如既往地挥舞皮鞭，无情抽向面前木讷的角斗士。\n\n这里才是她的战场。\n\n没有酣畅淋漓的对决，没有鲜花与掌声。高大的勇士们是最温顺的驯鹿，她所有的咒骂和怒火就像被吸入幽暗的空洞，连一丝风都不剩下了。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11210_UnlockDesc|同调率等级达到9"
  },
  [11266] = {
    ID = 11266,
    CnID = "唤醒体故事@仁爱主祭·简介",
    BaseSortID = 137,
    ActorIndex = 15599,
    Title = "AwakerStory_11266_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11266_Content|不必对他的黑色眼罩心存畏惧，交叉的黑暗不会遮蔽他的怜悯。目盲的躯体已然消亡，救赎的意愿却会永存，在他面前，一切都应被爱，一切都将被爱。\n父神的言永刻于石板，借这受祝的骨血，他将予以你们「赐福」。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11266_UnlockDesc|唤醒体等级达到1级"
  },
  [11237] = {
    ID = 11237,
    CnID = "唤醒体故事@仁爱主祭·故事一",
    BaseSortID = 138,
    ActorIndex = 15599,
    Title = "AwakerStory_11237_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11237_Content|伦蒂尼恩圣堂区异常事件报告（机密）\n\nA.F. 315年@2月@3日，伦蒂尼恩圣堂区异常事件中，圣堂区主教萨尔瓦多为救治弥萨格守密人及在场的伦蒂尼恩市民，使用了「赐福」的力量，由此暴露了其唤醒体的身份。\n过程中，由于链接者精神力不足，为避免影响链接者，萨尔瓦多主教选择自我消耗以支撑「赐福」，直到守密人与奥吉尔唤醒体将异常现象核心——仪式镜——击碎。随后，守密人接手了萨尔瓦多主教的链接，「赐福」治疗了在场所有群众，避免了人员伤亡。\n据查，萨尔瓦多主教的原链接者为前圣堂区主教，现伦蒂尼恩大主教@4。\nA.F. 300，大主教在接触圣灰后意外唤醒萨尔瓦多。随后5年间，萨尔瓦多以助理神父身份在圣堂区活动，并在■■■■■升迁后接替其成为圣堂区主教。\n事件后，守密人同意为萨尔瓦多主教的唤醒体身份进行保密，因而此信息并未同步至密斯底亚协定审查会。除了弥萨格大学核心人员，目前无人知道其唤醒体身份。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11237_UnlockDesc|同调率等级达到3"
  },
  [11190] = {
    ID = 11190,
    CnID = "唤醒体故事@仁爱主祭·故事二",
    BaseSortID = 139,
    ActorIndex = 15599,
    Title = "AwakerStory_11190_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11190_Content|主教阁下每次拜访学校，都会受到师生们热烈的欢迎。\n心智尚幼的唤醒体们会拉着他的手，要求他再讲几个洪积前的故事。学生们会主动靠近，询问主教是否愿意倾听自己的困扰与烦恼。就连那些看上去冷硬强大的唤醒体，和见多识广的教授们，也会在主教空闲下来时上前搭话：或是诉说自己的噩梦，或是探讨灵魂的真谛。\n他总是如此耐心，总是不厌其烦。不论是谁都能在他那里得到接纳与温暖。\n「当然，我的孩子，有什么是我能为你做的吗？」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11190_UnlockDesc|同调率等级达到5"
  },
  [11371] = {
    ID = 11371,
    CnID = "唤醒体故事@仁爱主祭·故事三",
    BaseSortID = 140,
    ActorIndex = 15599,
    Title = "AwakerStory_11371_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11371_Content|「……康斯坦联邦南部的本多斯曾流传着「赐福主教」的传说。洪积前，「赐福主教」出身中央教廷，虔诚而且善良，一手建起了当地唯一的孤儿院，并在瘟疫肆虐时收留了大量无处可去的病人及逃难者。\n瘟疫凶狠，人人皆苦，代行者日夜祷告，终于获得父神恩赐生命石板，以自身血肉为祭在人世间施展神迹。他让死的复活，让重病的康复。然而这位仁慈的代行者被恶魔陷害，最终死于火刑。\n巧合的是，与传说「赐福主教」活跃的相同时期，在原@2中部的@1（现康斯坦联邦南部近本多斯地区）存在过一名特殊的「血之异端」。根据《大陆审判所异端审判实录》记载，这名异端手握刻有恶魔印记的石板，以血肉为祭，会在月亮被遮蔽的夜晚举办邪恶仪式供养自身。该名异端于洪积前107年被审判所抓获，异端幡然醒悟，向唯一的父神虔诚忏悔，并死于火刑。\n同一个年代，同一个区域，同样使用石板和祭祀施展秘术——不可否认，「赐福主教」与「血之异端」间具有很多共同点。考虑到审判所具有很强的主观性，极有可能对被其视作异端的人士进行污名化处理，笔者不得不怀疑，传说中的「赐福主教」可能确有其人，甚至可能正是审判所记载中的「血之异端」……」\n——节选自《我们的神明：康斯坦联邦南部宗教与民间信仰》\n",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11371_UnlockDesc|同调率等级达到7"
  },
  [11171] = {
    ID = 11171,
    CnID = "唤醒体故事@仁爱主祭·故事四",
    BaseSortID = 141,
    ActorIndex = 15599,
    Title = "AwakerStory_11171_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11171_Content|「仁慈的父神曾经劝诫：你们要爱护天上的、地上的、水里的、土里的一切。因为万物皆是我的子嗣。」\n「因此，我要说：将所有苦难加于我身吧，让那些受生活所难、瘟疫所苦的得以解脱，让那些病痛、那些疯狂，全部同冰雪般融化。让你们，我的姐妹弟兄，得到恒久的幸福。\n「将我燃烧吧，将我的骨磨灭，将我的肉毁去。只要你们能够获得慰藉，我亦没有怨言。」\n——B.F. 1@1，5月30日，萨尔@1多·马丁@2·伊@1亚斯，于@3审判所留",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11171_UnlockDesc|同调率等级达到9"
  },
  [11339] = {
    ID = 11339,
    CnID = "唤醒体故事@歌者·简介",
    BaseSortID = 142,
    ActorIndex = 15574,
    Title = "AwakerStory_11339_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11339_Content|她是群星间的歌者，是熠熠生辉的星尘。\n她是金丝笼中的困鸟，是被随意丢弃的留声机。\n当荒星在坍塌的宇宙湮灭，她被迫获得生之希望，成为了无主深空中，眷恋故土的流浪者、永恒歌唱的寻觅者。\n「姐姐……虽然我们中，我才是能自由行走的那一个，但一直以来，都是你在支持我啊。」",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11339_UnlockDesc|唤醒体等级达到1级"
  },
  [11215] = {
    ID = 11215,
    CnID = "唤醒体故事@歌者·故事一",
    BaseSortID = 143,
    ActorIndex = 15574,
    Title = "AwakerStory_11215_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11215_Content|《P-063号歌剧院@2事件》中，我们从焚毁歌剧院的后台角落中发现了一只金属匣子，并回收了该枚银芯。\n弥萨格大学现存的仪器无法鉴定匣子的材质，朵尔教授在查阅@2文献后，结合其雕花工艺，分析匣子可能来自一个已于数百年前在爆炸中湮灭的荒星文明。\n该枚银芯置于匣中时安静而平常，但被取出时会发出阵阵嗡鸣声。朵尔怀疑该金属匣是某种信号屏蔽器，能阻拦让银芯共振的特殊频率信号。\n引发共振的银芯型号也已探知。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11215_UnlockDesc|同调率等级达到3"
  },
  [11160] = {
    ID = 11160,
    CnID = "唤醒体故事@歌者·故事二",
    BaseSortID = 144,
    ActorIndex = 15574,
    Title = "AwakerStory_11160_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11160_Content|与菲茵特团聚后，汀克特便在弥萨格大学安定了下来。在P-063号歌剧院@2事件中再次受伤的汀克特更加畏惧生人，因此变得深居简出。与高亢嘹亮的歌喉不同，她日常交谈的声音甘美清澈，但听过的人却寥寥。\n有好事者试图为汀克特在校园内的登台造势，还从不知何处找出了汀克特早年在歌剧院演出的海报，张贴满校园的各处宣传角。\n汀克特不愿意迎合这些愿望，那些热切的期望只会让她想要遗忘的过往回忆再次翻腾。\n「结束这荒诞的悲剧吧。陪在你的身边，我已经别无所求。如果可以的话，就让我被这个世界遗忘也无所谓。」\n「不要，汀克特。我们未来相伴的日子还很长，这里已经不是荒星，我也不再是你的拖累。你应当找到自己想做的事情，为自己而活。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11160_UnlockDesc|同调率等级达到5"
  },
  [11211] = {
    ID = 11211,
    CnID = "唤醒体故事@歌者·故事三",
    BaseSortID = 145,
    ActorIndex = 15574,
    Title = "AwakerStory_11211_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11211_Content|与一望即知身量娇小的姐姐不同，汀克特的畸形体现在其他方面。\n槲寄生也好，寄居蟹也好，汀克特仿佛某种脱离了其他个体就无法生存的精神体。\n在荒星时，她所做的一切都是为了治愈菲茵特的疾病，一切可能维系姐姐生命的方式她都愿意去尝试，哪怕要付出常人难以忍受的代价。\n贵族们的嘲弄与羞辱她都毫不在意，永远平静温和地与他们进行不平等的交易，甚至祈求他们的怜悯——那怜悯为她换来了逃离荒星的席位，而她在到手的瞬间毫不犹豫地拱手赠予了菲茵特。\n菲茵特却在最后时刻将汀克特推上了逃离荒星的星流——期望妹妹能够从此摆脱自己，在新的星球开启自己的人生。\n然而荒星湮灭后，汀克特又为了寻找菲茵特而踏上了全无自我的漂流旅途，受他人驱使摆布也不以为意。这样的汀克特被@2教会发现，又辗转落入了@3手中。\n汀克特不曾反抗。不如说，汀克特更希望有人来告诉自己怎么做是最好的——即便那是谎言、是欺骗、是只能暂留片刻的幻梦，也比手足无措地僵立原地要好。\n至少，那说明菲茵特的未来还有希望。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11211_UnlockDesc|同调率等级达到7"
  },
  [11193] = {
    ID = 11193,
    CnID = "唤醒体故事@歌者·故事四",
    BaseSortID = 146,
    ActorIndex = 15574,
    Title = "AwakerStory_11193_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11193_Content|事到如今，再和我谈「自己的生活」，或许有些太过为难了。\n我已经习惯了消散在高空之外，隐匿于星海之中。\n那些看客们注视的不是我，被当做八音盒赏玩的不是我，漂泊于荒芜星空的不是我。那是为生计出卖歌喉的工具，是为寻找菲茵特而流浪的行尸走肉。唯有相信他人的价值远高于自我，才能相信这一切付出都属值得。\n所以，事到如今，请不要让我再注意到我。\n\n「但是，妹妹啊，别再沉湎于那些已经过去的过去了。\n睁开眼看看吧，你独一无二的歌声，可是已经响彻宇宙了哦。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11193_UnlockDesc|同调率等级达到9"
  },
  [11303] = {
    ID = 11303,
    CnID = "唤醒体故事@窜行者·简介",
    BaseSortID = 147,
    ActorIndex = 15593,
    Title = "AwakerStory_11303_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11303_Content|大家很快接受了一个事实：有詹金的地方就有布朗，有布朗的地方就有詹金。而一旦布朗单独行动了，别怀疑，那背后一定有詹金的影子。\n「什么叫我偷的？我可是有不在场证明的！」\n女孩拿着被布朗「取」走的东西如是说。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11303_UnlockDesc|唤醒体等级达到1级"
  },
  [11166] = {
    ID = 11166,
    CnID = "唤醒体故事@窜行者·故事一",
    BaseSortID = 148,
    ActorIndex = 15593,
    Title = "AwakerStory_11166_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11166_Content|A.F. 315年@1月@2日，08:13 a.m.\n审查会现场响应第三小队及融蚀物品控制及管理（以下简称DISM）β7组成员抵达融蚀区域L-E-933（即南华克大街@2号，罗杰斯蜡像馆原址），接手第一小队与DISM α2组的任务，进行区域无害化工作。\n09:24 a.m.\nDISM成员詹姆斯在清除蜡像馆地下区域时出现头痛、恶心、晕眩等症状。\n10:47 a.m.\n第三小队成员罗兰德，DISM成员扎克瑞、博尔顿逃离地下区域。三人汇报称，地下区域的黑暗将他们吞入漂浮在一片星空之中，具有形体的颜色在空间中彼此交缠，绚丽的同时让人浑身冰凉。接着这些颜色凝聚成无数老鼠，并飞速向他们袭来。\n博尔顿拒绝继续作业，返回审查会伦蒂尼恩办公室。第三小队罗兰德与DISM扎克瑞则陪同第三小队队长费舍再次进入地下区域进行相关检查。\n13:03 p.m.\n经检测搜寻，第三小队队长费舍于地下区域残留的融蚀蜡中找到并回收银芯L3202。已交由弥萨格大学进行后续处置。\n——《融蚀区域L-E-933无害化处理报告》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11166_UnlockDesc|同调率等级达到3"
  },
  [11220] = {
    ID = 11220,
    CnID = "唤醒体故事@窜行者·故事二",
    BaseSortID = 149,
    ActorIndex = 15593,
    Title = "AwakerStory_11220_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11220_Content|詹金过于灵巧的双手，一度让人担心她会成为弥萨格大学新晋的《日报》常客——不是作为被采访对象，而是作为数起盗窃案的主谋。\n虽然她最终还是成为了《弥萨格日报》的常客，但那不是因为习惯难改——只要有足够的小蛋糕，就算是街头生存大师也乐意放下过去的手段，和自己的老鼠搭档一起好好享受难得的退休生活。\n她频频上报的原因只有一个：《日报》的好主编给的实在是太多了。\n嘘——小点声，你永远不知道她在哪个角落，准备用听到的信息去和汉娜换取更多的糖果和蛋糕。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11220_UnlockDesc|同调率等级达到5"
  },
  [11218] = {
    ID = 11218,
    CnID = "唤醒体故事@窜行者·故事三",
    BaseSortID = 150,
    ActorIndex = 15593,
    Title = "AwakerStory_11218_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11218_Content|「我才不是孤儿，」六岁的詹金说，「我妈妈只是去工作了，工作完了她会来接我的。」\n她不曾动摇，也不敢动摇。这个信念是她每晚从满是黑色黏液的噩梦中惊醒时的护身咒语，是每当她试图回忆母亲的面孔，却只能看到一片黑色阴影时的唯一安慰。\n她咬着牙在福利院的大门前站过了一个春夏秋冬。直到福利院解散的那天清晨，她才抹去没人看得到的泪水，带着老鼠朋友离开。\n「我是个孤儿，」十岁的詹金说，「我没有爸妈，我只有布朗。」\n她这么告诉自己，也告诉自己肩上的老鼠。事实也确实如此，人们或许会提防突然靠近的孩子——东区流浪儿在整个伦蒂尼恩都算得上有名——却没人会对窜过脚边的老鼠抱有太多疑心。默契配合之下，女孩偶尔也能吃一餐饱饭，在下水道里做上一个关于壁炉和点心的美梦。\n但寒冷的冬日从不怜悯任何人，它给她带来疾病与高热，带来在她身侧驻足的死神。女孩奄奄一息，只有老鼠在周围急切地打转，期望用叫声换来一点关注，任何人的关注。\n一个年轻的女人停下脚步，将女孩包裹在温暖的怀中。\n「我才不是孤儿，」十三岁的詹金说，「我有姐姐梅森，还有好朋友布朗！」\n女孩抱着老鼠站在破旧的房屋前，脸上满是开朗的笑容。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11218_UnlockDesc|同调率等级达到7"
  },
  [11241] = {
    ID = 11241,
    CnID = "唤醒体故事@窜行者·故事四",
    BaseSortID = 151,
    ActorIndex = 15593,
    Title = "AwakerStory_11241_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11241_Content|街头生活对她来说并非难事。\n饿了就去找工，没有工，那就凭借自己的双手讨生活。她与布朗的配合如此默契，以至于不需要他人帮助就可以过上有吃有喝的生活。\n「我们不需要任何人，」她和老鼠搭档发誓，「我们只需要彼此。」\n但每逢飘雪的夜晚，她仍会忍不住看向那些亮起昏黄灯光的窗户，看向里面那些在贫瘠的晚餐旁拥抱彼此，互相祝福的人。\n她确实不需要隐蔽的屋顶，不需要奢侈的高床软枕，她确实已经拥有值得信赖的伙伴，但她还是好奇，长久地拥有一个家会是怎样的一种感觉呢？\n这个问题在梅森将她收养之后，获得了解答。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11241_UnlockDesc|同调率等级达到9"
  },
  [11175] = {
    ID = 11175,
    CnID = "唤醒体故事@奇术师·简介",
    BaseSortID = 152,
    ActorIndex = 15572,
    Title = "AwakerStory_11175_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11175_Content|来跳舞吧！跳一支欢快的舞，跳一支疯狂的舞！随着她一起欢笑吧，将气氛炒热至最高点。\n到那时候，就该轮到主角登场了。\n在那聚光灯的交汇点，疯狂的魔术师已经将手探入了她的长礼帽。至于她从那无尽虚空中掏出的，是五彩斑斓的飘带，是展翅腾飞的白鸽，还是恐怖怪物的利爪……恐怕只有她自己才知道了。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11175_UnlockDesc|唤醒体等级达到1级"
  },
  [11251] = {
    ID = 11251,
    CnID = "唤醒体故事@奇术师·故事一",
    BaseSortID = 153,
    ActorIndex = 15572,
    Title = "AwakerStory_11251_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11251_Content|A.F.3@2年4月1日，银芯储存与管理室，弥萨格大学唤醒体系，伦蒂尼恩\nG411号银芯与G410号银芯一同，由德克斯特勋爵于「水仙夫人」处购得。个体长1.85厘米，最宽处0.4厘米，整体形状接近斜方六面体。无论从哪个角度和方位观测，G411都会以观测者的视觉中心为中心，向周围扩散出明黄色的菱形波纹。长时间注视会使观测者精神涣散，情感反馈减弱，甚至导致木头人综合征（可能症状有：完全的情感缺失、欲望缺失，及因食欲缺失而导致的营养不良乃至死亡等），需要及时进行心理和情感干预。\n尽管其负面效果与大部分银芯相比较为温和，但仍建议密封保存，取出后避免直视，以减少因受G411影响而产生情感障碍的可能。\n\n——摘自《弥萨格大学银芯储存记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11251_UnlockDesc|同调率等级达到3"
  },
  [11376] = {
    ID = 11376,
    CnID = "唤醒体故事@奇术师·故事二",
    BaseSortID = 154,
    ActorIndex = 15572,
    Title = "AwakerStory_11376_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11376_Content|「厌倦了平淡的公园吗？厌倦了无趣的动物展览了吗？那么到卡茜亚的魔法嘉年华来吧！喜欢动物的孩子们，这里有唱男高音的狮子，跳芭蕾舞的火烈鸟，表演杂技的大象，以及世界唯一的毛驴驯兽师！希望增进感情的爱侣们，可以试试我们独一无二的旋转活马，收获难得的浪漫体验！觉得生活中缺乏真刺激的勇士们，可以挑战由嘉年华主人亲自设计的镜子迷宫，如果能将那41个进去了就没出来的坏客人带走，还能获得丰厚的奖品哦！\n除了这些世界仅有的娱乐设施，魔法大师卡茜亚还将向你展示奇妙的狂欢世界，为你带来人体截断、大变活人、极限逃脱及更多魔法！幸运观众还能获得上台亲身参与表演的机会，体验卡茜亚大师精妙绝伦的切割技巧。保证颠覆你的认知，让你的日常生活变得更加索然无味！更妙的是，这一切都是免费提供，免费！你的快乐就是卡茜亚大师最好的酬劳！\n弥萨格大学的各位，本周末在食堂后的空地上，卡茜亚大师与你不见不散！\n\n注：嘉年华一旦进入便必须完全体验，不得中途离开。承受能力低及精神、心脏脆弱者慎入。\n嘉年华后出现食欲不振、肢体残缺、眼睛丢失及腹部开裂等症状的，本嘉年华概不负责。」\n——《魔法大师卡茜亚的魔法嘉年华盛大开幕！》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11376_UnlockDesc|同调率等级达到5"
  },
  [11320] = {
    ID = 11320,
    CnID = "唤醒体故事@奇术师·故事三",
    BaseSortID = 155,
    ActorIndex = 15572,
    Title = "AwakerStory_11320_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11320_Content|从幼年时起，卡茜亚就展现出了极高的模仿天赋。\n无论多么精妙的舞蹈，只要让她看一遍就能重复出来；无论多么复杂的魔术，只要教一次她就能熟练掌握。声音、表情、甚至是笑容和气质，卡茜亚都能做到完美复刻，甚至以假乱真。如果她有一个不同的出身，或者不同的职业，或许能凭借这个天赋获得一个不一样的人生。\n可惜，她只是一个在名不见经传的马戏团中长大的孩子。马戏团的人只想着用她的天赋敛财，而马戏团外的人——他们只管购买快乐，并不想付出同情。\n没有人关心卡茜亚的快乐，幸运的是，卡茜亚也并不在乎。每当她看着欢笑的观众，看着争吵的团员，看着对照片默默流泪哭泣的女占卜师，都只感到一种剥离的好奇：他们为什么要在舞台下做出这些表情？为什么要在没有人看到的时候坚持表演？为什么要说那是他们「情感的流露」？\n什么是快乐？什么是悲伤？割开她喉管的「资助人」所说的，濒临死亡的绝望和恐惧，又是什么感觉？\n作为人类的她找不到问题的答案，但作为魔法的孩子，作为可以从他人身上收集「情感」的生物的她，或许终于可以获得从未拥有过的体验。\n于是，她创办了魔法嘉年华，并将它带往世界各地。\n人们前来购买快乐，付出的代价却是所有的欲望。\n「来吧，来吧，来到我的嘉年华！只需要交出一点快乐，一点哀伤，就能看到本世纪最精彩的表演！」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11320_UnlockDesc|同调率等级达到7"
  },
  [11355] = {
    ID = 11355,
    CnID = "唤醒体故事@奇术师·故事四",
    BaseSortID = 156,
    ActorIndex = 15572,
    Title = "AwakerStory_11355_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11355_Content|卡茜亚将手伸进帽子，那里面空无一物。\n卡茜亚将手伸进门扉，那里面空无一物。\n卡茜亚将手伸进胸膛，那里面空无一物。\n收集来的喜怒哀乐，惊惧怨怒，人情冷暖，开场前的喧哗，转折时的欢呼，精彩时的哨声，闭幕时的掌声，散场时的冷落都从这空荡荡的胸膛中溜走了，不留一丝存在过的痕迹。\n卡茜亚对着镜子模仿起观众的表情，眼角的褶皱，肌肉的走势，唇角的弧度，分明与那些人一般无二，可其中感受不到任何真意。\n要是能感知到就好了，要是能超脱模仿就好了，要是能成为他们中的一员就好了……或者，要是有某人能够留下就好了……\n那样的话，一定就能填补这胸腔中的「空」吧。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11355_UnlockDesc|同调率等级达到9"
  },
  [11300] = {
    ID = 11300,
    CnID = "唤醒体故事@无名诗篇·简介",
    BaseSortID = 157,
    ActorIndex = 15583,
    Title = "AwakerStory_11300_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11300_Content|玫瑰的尖刺戳破诗篇的纸页，留下透明的血痕。酒精的气味挥散萦绕，无色的火舌四处蔓延。\n在那烈火当中，奥尔拉手捧着最后的诗章，为隐匿于花房的天才诗人的末路写下无声注解。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11300_UnlockDesc|唤醒体等级达到1级"
  },
  [11259] = {
    ID = 11259,
    CnID = "唤醒体故事@无名诗篇·故事一",
    BaseSortID = 158,
    ActorIndex = 15583,
    Title = "AwakerStory_11259_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11259_Content|A.F.3@2年初，名为西岱的城市在进行翻新时，于一处毁于火灾的花园中发现了异状：灰烬如藤蔓般爬在花房被焚毁的墙面上，藤蔓上绽放的灰烬玫瑰中闪烁着金属一样的色泽。\n循着藤蔓的引领，弥萨格大学的调查员拾取了这枚银芯。在触碰到那银色粉末的瞬间，她的指尖被灼伤成焦黑色，没有任何痛感，两颊却莫名滚下了两行泪珠。\n哀泣来得毫无理由，转眼间也消散于灰烬中。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11259_UnlockDesc|同调率等级达到3"
  },
  [11208] = {
    ID = 11208,
    CnID = "唤醒体故事@无名诗篇·故事二",
    BaseSortID = 159,
    ActorIndex = 15583,
    Title = "AwakerStory_11208_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11208_Content|奥尔拉身上仿佛有一股奇异的魔力，向往着诗与美的师生们总是会不由自主地被她吸引，聚集在她的身侧。\n奥尔拉并不喜欢发表自己的诗，但弥萨格的学生们还是想尽办法看到了她的只言片语。自她笔尖流淌出的诗句，每每在极短时间内风靡校园。\n晨露初起，有人在钟楼下轻声念诵她的词句；黄昏时分，宁菲亚坐在弥大广场的长椅上，翻阅她的集册；夜幕降临后，学生们汇聚在礼堂中排演她书写的篇章。\n但即便接到盛情邀请，奥尔拉也很少对这些活动投以目光，更遑论亲身参与了。那些言辞哀婉的语调，潸然泪下的场合，经常让她感到无所适从。\n「我又传播了新的哀伤吗？」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11208_UnlockDesc|同调率等级达到5"
  },
  [11263] = {
    ID = 11263,
    CnID = "唤醒体故事@无名诗篇·故事三",
    BaseSortID = 160,
    ActorIndex = 15583,
    Title = "AwakerStory_11263_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11263_Content|这是花与诗的城市，在此地，一首缱绻的情诗等价于一束新折的玫瑰，也能交换来三口之家一周的口粮。一篇佳作的横空出世，也代表着一名天才诗人将声名鹊起。\n那人曾是个成日与肥料枯枝相伴的花匠，她享受着雅逸诗句为她带来的奉承与追捧，不再料理园艺事务，甚至将温室上锁，不允许任何人再进入花房。\n他人问起，她也只答温室中藏着「灵感」。\n她们出身微末，是贵族忠仆的孩子。康斯坦联邦成立，旧贵族被清算，她们也随之失去了安身之所。\n那是陪伴小姐长大的女侍，却早早展现了对文字的天赋——可仆役怎能读诗呢？\n周围的环境时刻发生着剧变，诗歌的天分尚无法为少女带来生存的能力。一切的一切都让少女更加难以适从，更加忧郁悲伤。\n直到花匠向她伸出了手——那双被荆棘割破的手，赠予了她一座花园。在这个渺小的王国里，她们度过了人生最快乐的一段时光。\n平静的生活，从花匠收到的一首诗开始改变。\n好友的才华是如此动人，她想让更多人看见这首赠友诗。\n腼腆忧郁的好友不愿署名，花匠便在落款处签下了自己的姓名——「如果发表了，署名也方便他们寄赏钱。」\n花匠的变化也是从第一笔稿费开始的。\n她不明白，为什么自己突然就从保护者变成了累赘。\n她不明白，为什么好友能够轻松收获所有的爱与赞誉，而自己的辛劳努力，在天赋面前不堪一击。\n被欲望与妒忌冲昏了头脑，她开始利用好友的信任骗取她的作品。欺瞒的行为无法回头，种子从一开始就埋在花匠心中，随着天才诗人名号的传播开始发芽，在一次街头采访中长出了花苞——狂热拥趸们用诗句中那些隐秘缱绻的情愫向花匠提问，根本无法读懂诗文的花匠急得满头大汗，仓促离场。深夜回到花房，面对好友关切的神情，恐慌的花朵在此刻盛放。\n一场震惊西岱的大火后，天才诗人宣布封笔，带着她短时间内赢来的财富与盛名消失不见。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11263_UnlockDesc|同调率等级达到7"
  },
  [11179] = {
    ID = 11179,
    CnID = "唤醒体故事@无名诗篇·故事四",
    BaseSortID = 161,
    ActorIndex = 15583,
    Title = "AwakerStory_11179_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11179_Content|「奥尔拉，从今天开始，你的所有诗我都会帮你好好珍藏起来的。以后，我就用我的花，来换你的诗吧！」\n「柯蕾特，你一定会回来救我的……对吗？」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11179_UnlockDesc|同调率等级达到9"
  },
  [11302] = {
    ID = 11302,
    CnID = "唤醒体故事@猎颅魔女·简介",
    BaseSortID = 162,
    ActorIndex = 15590,
    Title = "AwakerStory_11302_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11302_Content|「欢迎来到达芙黛尔的交换商店，我们提供以物易物和收购头颅的服务，价格绝对公道，童叟无欺。」\n灰雾缭绕中，女人轻轻掸了掸古朴的木质烟斗，晃动的帽檐下，时隐时现的唇梢勾勒出充满暧昧的笑意。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11302_UnlockDesc|唤醒体等级达到1级"
  },
  [11363] = {
    ID = 11363,
    CnID = "唤醒体故事@猎颅魔女·故事一",
    BaseSortID = 163,
    ActorIndex = 15590,
    Title = "AwakerStory_11363_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11363_Content|达芙黛尔是以高昂的价格，将自己售卖给了弥萨格大学银芯研究室。\n在那之前，研究室负责人朵尔已经多次对只能由达芙黛尔发起的单向通信表达过高度不满。\n但只有达芙黛尔和某位已逝的弥萨格大学高层知道，这样的「单向通信」是通过怎样危险的交易才得以成立的。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11363_UnlockDesc|同调率等级达到3"
  },
  [11310] = {
    ID = 11310,
    CnID = "唤醒体故事@猎颅魔女·故事二",
    BaseSortID = 164,
    ActorIndex = 15590,
    Title = "AwakerStory_11310_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11310_Content|达芙黛尔在弥萨格大学的行踪堪称神出鬼没，毕竟，她掌握着在维度中自由穿梭的禁忌知识，来去自如，不受地下黑池银芯枢纽的限制。\n她总是出售一些来路可疑的神秘仪器或材料，有时也会协助其他唤醒体短暂逃离弥萨格大学的控制。\n后来，通过谈判，她在校园一隅、医务室旁的旧房间中开设了自己的「解忧百货」分店。\n当然，所有售卖的货品都必须得到弥萨格大学的登记与审查。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11310_UnlockDesc|同调率等级达到5"
  },
  [11365] = {
    ID = 11365,
    CnID = "唤醒体故事@猎颅魔女·故事三",
    BaseSortID = 165,
    ActorIndex = 15590,
    Title = "AwakerStory_11365_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11365_Content|在海港之城的街角有一家很小的交换商店，店主是一个擅长应对神秘事件的「能人」。\n洪水过后不久，彼时还不叫达芙黛尔的达芙黛尔来到了圣佩德罗附近，这座海港城市中便开始出现「头颅神秘失踪」的受害者。\n店主经过调查，找到了那时的它，并在尽全力制服它之后，与它做了一个交换。店主许诺，可以在生命结束后取走自己的头颅，但在此之前，必须作为店主的助手，不可再随意狩猎。\n于是经历千年流浪的它，开始与店主一起行动，一起生活。\n它曾在无数头颅中重温过那些主人生前的记忆，读取过欢欣雀跃也体味过憎恶怨怼，但这荒唐的快乐无非是消磨过于长久的生命、掩盖飘零而生的孤独而已。\n在与店主的相伴中，它才第一次与人建立真正的友谊：它发现自己需要的并不是无限的头颅那种虚假的安慰，只有通过真正与人的相处，才能解决长久的孤独和空虚。\n然而，这段短暂的快乐只持续了不到十年时间，从未停止调查生涯的店主意外离世。\n于是，它斩下了她的头，继承了她的外貌和商店，还有她的名字，成为了「达芙黛尔」。\n从那以后，达芙黛尔踏上了带着小小交换商店巡回的旅程，她仍会向寻求帮助的人们收取头颅作为交换，收集头颅作为嗜好品。\n但她再也没有随意猎杀头颅。\n再也没有。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11365_UnlockDesc|同调率等级达到7"
  },
  [11322] = {
    ID = 11322,
    CnID = "唤醒体故事@猎颅魔女·故事四",
    BaseSortID = 166,
    ActorIndex = 15590,
    Title = "AwakerStory_11322_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11322_Content|灰色黏稠的原质之海中一片空无，那些穿越维度的旅行者讲述的概念也停留在抽象的描述与想象。\n它想要用自己的双眼去确认那些人类的「神往之处」，想要亲眼目睹人间斑斓的壮阔奇景，想要亲身体会悲欢离合的个中滋味。\n但在那之上，它更想要一个特定的人，足以珍视、足以交付信赖的人。\n公正的交易意味着平等，意味着切割，意味着钱货两讫，意味着不多付出一分也不少攫取半分。但它渴望不一样的事物，渴望一种无偿的信赖，以消弭隔阂，以突破试探，以融解坚冰。\n它得而复失，但终将失而复得。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11322_UnlockDesc|同调率等级达到9"
  },
  [11255] = {
    ID = 11255,
    CnID = "唤醒体故事@荆棘女王·简介",
    BaseSortID = 167,
    ActorIndex = 15586,
    Title = "AwakerStory_11255_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11255_Content|旺达聪明、富有、漂亮，正如她所说的，她活着便是为了寻欢作乐。她将男人变成她的奴隶，又将月光般冰冷的双脚踏在奴隶的背上。头戴桂冠的维纳斯，她是邪恶与梦幻的化身，在这一片黑暗阴影中，唯有她修长的身影闪闪发光。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11255_UnlockDesc|唤醒体等级达到1级"
  },
  [11356] = {
    ID = 11356,
    CnID = "唤醒体故事@荆棘女王·故事一",
    BaseSortID = 168,
    ActorIndex = 15586,
    Title = "AwakerStory_11356_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11356_Content|行程信息：猎奇历史探秘——坎布里安城堡豪华七日游\n行程日期：A.F.3@2年6月18日-6月25日\n导游：托马斯·@2@1\n行程简述：\n来吧，一同揭开三百年前最令人闻风丧胆的闹鬼城堡——坎布里安城堡的神秘面纱吧！\n我们已经厌倦了在老旧书籍和无声电影里见到的魅惑女领主与她二十五个随从的香艳传说了，它们千篇一律，毫无新意！\n根据弥萨格某不愿透露姓名的专家透露，该地区最近又有了新的发现！@2@1长满了荆刺……\n尽快拨打电话@2@1@1这趟旅途必将令你永生难忘，冷汗直流！\n——节选自《伍斯特旅行团失踪事件·案卷综述：证物S-145》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11356_UnlockDesc|同调率等级达到3"
  },
  [11287] = {
    ID = 11287,
    CnID = "唤醒体故事@荆棘女王·故事二",
    BaseSortID = 169,
    ActorIndex = 15586,
    Title = "AwakerStory_11287_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11287_Content|旺达来到弥萨格的第一天，便因「肆意踩踏他人」遭到了严厉指控。\n据某不愿透露姓名的学生表示，他只是偶然路过图书馆，与旺达不小心有了一次眼神交汇，随后便被掀翻在地，@2被套上@3（该生拒绝透露更多细节）。\n伤害过程从发生到结束不超过五分钟，情节恶劣，令人发指。\n弥萨格纪律委员会（以下简称MDC）对该情况表示高度重视与深切同情，现已成立专案小组，后续将持续对旺达进行思想和行为上的彻底改造，以助其尽快融入校园生活。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11287_UnlockDesc|同调率等级达到5"
  },
  [11346] = {
    ID = 11346,
    CnID = "唤醒体故事@荆棘女王·故事三",
    BaseSortID = 170,
    ActorIndex = 15586,
    Title = "AwakerStory_11346_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11346_Content|在那场可怕的瘟疫来临之际，旺达下令将城堡的大门用铁焊死，过上了彻底与世隔绝、寻欢作乐的生活。\n这里有插科打诨的小丑，也有即席吟诵的诗人。有演奏的乐师，也有美食和酒浆。\n所有的欢乐与平安都在城堡内，城堡外则是被@2的黑暗世界。\n就在墙外彻底成为一片死地之时，旺达为她的数百名追随者举行了一场异常豪华的假面舞会。\n这是一次持续了三天三夜、靡丽而放荡的狂欢。当第三天午夜的钟声敲响，宾客们有的彻底发疯，有的化为一滩黑色的黏液。旺达的脸如陶瓷般开裂，从面具的缝隙中流淌出黑色的@2。\n受到惊吓的追随者依偎在旺达身边瑟瑟发抖，她却很平静。\n她一挥长鞭，命令@2彻底疯掉的人，余下人继续饮酒奏乐，不得停歇。\n光怪陆离的舞会在第四天清晨结束，华丽的大厅内满是黑色的@2浆与红色的鲜血。\n没人知道这里曾发生过什么。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11346_UnlockDesc|同调率等级达到7"
  },
  [11324] = {
    ID = 11324,
    CnID = "唤醒体故事@荆棘女王·故事四",
    BaseSortID = 171,
    ActorIndex = 15586,
    Title = "AwakerStory_11324_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11324_Content|「一味行淫，随情纵欲，当受永火的刑罚，作为鉴戒……」\n连续23天，修士都站在她的城门外，嘴里诵念着乏味的经文。\n旺达命人将他绑了进来。\n修士说：「何必为困苦忧虑。主的灵在哪里，哪里就得以自由。」\n她脱掉他的衣服。\n修士说：「何必为衣裳忧虑。野地里的百合花既不纺线，也不低头。」\n她砍断他的四肢。\n修士说：「何必为流血忧虑。凡有血肉者，无一不死。」\n旺达笑了：「吾不但要让你流血，吾还要将你变成吾的奴，生生世世。」\n「为何？」修士抬起头，「你不应当怜悯你的同伴，像我怜悯你么。」\n旺达端详着修士。他的眼睛很蓝，像是晴空的颜色。\n她挖掉他的眼睛。\n因不堪忍受酷刑，修士最终死去了。当地教区忌惮她的财权，竟无人敢指责她。\n临死前修士说：「@2近了，你应当……」\n许多年过去，旺达早已忘了修士的脸和姓名，只记得他的眼。即将被@2吞噬的那个夜晚，旺达又想到了那句未完的话。\n「@2近了，你应当……」\n她在模糊的意识中揣测修士的后文，却一无所获。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11324_UnlockDesc|同调率等级达到9"
  },
  [11277] = {
    ID = 11277,
    CnID = "唤醒体故事@迁移者·简介",
    BaseSortID = 172,
    ActorIndex = 15579,
    Title = "AwakerStory_11277_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11277_Content|温柯尔的办公室被称为弥萨格大学的北极星。那里永远灯火通明，任何可能存在阴影的角落都被各式各样的照明用具点亮——从提灯到煤油灯，从钨丝灯泡到蜡烛。\n对黑暗的恐惧甚至让她排斥睡眠，因此她总会端坐在最大的那盏灯下，在散落满地的草稿纸上书写着无人能懂的符号，不分日夜。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11277_UnlockDesc|唤醒体等级达到1级"
  },
  [11158] = {
    ID = 11158,
    CnID = "唤醒体故事@迁移者·故事一",
    BaseSortID = 173,
    ActorIndex = 15579,
    Title = "AwakerStory_11158_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11158_Content|时间：A.F. 299年@1月@2日\n地点：实验室UG-C03，@2@1，@4，伦蒂尼恩。\n参与人员：@1，@2，@4，@3\n实验对象：W\n受试者信息：\n躯体为成年人类女性，出生于A.F. 280年6月18日，原籍不明，于@2大学求学途中染病逝世，随后为地外精神生命体@1占据躯体且恢复生命，继续原有生活。\n@1具有精神迁移及置换的能力，且可以直观地观察融蚀。尽管人类躯体无法观察融蚀，@1种族的能力也让受试者从精神层面感知到了融蚀的存在。因此，在受试者于2年零8个月前初次观测到融蚀时，受试者便试图进行精神迁移以避免受到进一步侵蚀。\n尽管@1保留了对融蚀的感知能力，但受试者无法摆脱其影响，精神体迁移失败。经过多次尝试后，受试者主动联系@3大学，希望@3将其制成唤醒体，直接促成了本次实验。\n——节选自《实验记录：活体提取银芯的可能性》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11158_UnlockDesc|同调率等级达到3"
  },
  [11214] = {
    ID = 11214,
    CnID = "唤醒体故事@迁移者·故事二",
    BaseSortID = 174,
    ActorIndex = 15579,
    Title = "AwakerStory_11214_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11214_Content|汉娜：你是从哪里知道弥萨格大学能够帮助你的？要知道，大众对我们的认知可一直都是「偏僻的普通大学」，是拉蒙娜告诉你的吗？\n温柯尔：噢不不，不是，虽然确实是她将我领了进来，但我和拉蒙娜交往并不深。我的种族，@1，拥有跨时空间精神迁移的能力，所以我们知道很多东西……关于弥萨格的知识只是其中之一。\n汉娜：所以你是通过那些「知识」，知道穿过迷雾，直接敲开大门的方法的？\n温柯尔：我承认，我不知道迷雾的存在。当时我就是一直走，走着走着就到了。说到迷雾，你知道门口那段路有多恐怖吗？没有路灯就算了，起雾之后连阳光都变弱了，那么多黑影……\n汉娜：这也是你不喜欢离开办公室的理由吗，黑影恐惧？\n温柯尔：黑影？不不不，你不明白，除了影子还有那么多黑色，那么多地方可能藏着……它。\n汉娜：它？\n温柯尔：嘘！小点声！你会将它——不，它是没有智能的，但是为什么，为什么就算我到了这里也@2@3@1\n汉娜：温柯尔小姐，你还好吗？\n温柯尔：@2@3@1……\n汉娜：温柯尔小姐？\n温柯尔：够了，出去！我不想接受采访了！你的影子录音机笔记都是黑色的黑色黑色黑色出去出去出去！\n汉娜：温柯尔小姐——\n——摘抄自汉娜·皮斯利题为《0810，温柯尔专访（失败尝试1）》的录音",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11214_UnlockDesc|同调率等级达到5"
  },
  [11246] = {
    ID = 11246,
    CnID = "唤醒体故事@迁移者·故事三",
    BaseSortID = 175,
    ActorIndex = 15579,
    Title = "AwakerStory_11246_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11246_Content|温柯尔有过一个属于自己的名字。\n那个名字曾浸满父母的爱意，\n曾被好友反复地书写，纳入回忆，\n和生日一起在日历上标记。\n\n温柯尔有过一张属于自己的面庞。\n那副模样曾在父母的注视下成长，\n曾在好友的陪伴下露出欢喜，露出悲伤，\n曾和回忆一起定格在照片上。\n\n温柯尔有过一个属于自己的家，\n与卡达斯相距甚远，毫不相像。\n最终同父母的存在一起消亡。\n被黑色的@2吞噬，然后彻底消亡。\n\n温柯尔有一个深重的恐惧。\n它漆黑、可怖、吞噬一切、不讲道理。\n它将所有一切融解侵蚀，消磨殆尽，\n一旦沾染，存在本身都会化作灰烬。\n\n温柯尔只剩下一个曾经属于自己的名字。\n人类的躯体无法念诵，甚至无法模仿，\n她只能在极度疲劳的时候闭上眼，\n祈求一个能够听到熟悉的呼唤的梦乡。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11246_UnlockDesc|同调率等级达到7"
  },
  [11248] = {
    ID = 11248,
    CnID = "唤醒体故事@迁移者·故事四",
    BaseSortID = 176,
    ActorIndex = 15579,
    Title = "AwakerStory_11248_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11248_Content|生存既是本能，也是一个无法抛却的负担。在连记忆都无法留存的死亡面前，只有她是他们存在过的证明——她的父母，她的好友，她家乡的一切。\n所以她逃了，逃向尚未被黑色浸染的世界，逃向这颗覆盖了海洋的星球，在一个死去的人类少女身上获得了新生。\n但黑色的死神最不缺乏耐心。\n人类的双眼无法看见融蚀，但她知道意识边缘的寒冷意味着什么，脑海中的黑暗代表着什么——被人类称为融蚀的死亡追了上来，在她不知道的时候，将她的精神和躯体钉在了一起。\n她一次又一次地尝试逃离，一次又一次地失败，最终她筋疲力尽，精神也被撕扯到极限，只能拖着身体向唯一可能给予她救赎的地方走去。\n不论如何，她都希望能活下去。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11248_UnlockDesc|同调率等级达到9"
  },
  [11198] = {
    ID = 11198,
    CnID = "唤醒体故事@嘀嗒人·简介",
    BaseSortID = 177,
    ActorIndex = 15603,
    Title = "AwakerStory_11198_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11198_Content|朵尔曾经对她进行非常详细的研究，但无论是躯干还是四肢，无论是头颅还是盆腔，都没有发现任何支持她发声的部件。她究竟是如何说话的——这成了弥萨格无数未解之谜中的一个。\n在大多数情况下，她能与人进行正常交流，但有的时候，那个神秘的发声部件就像是具有自己的意识一样，会说出一些让人毛骨悚然，浑身发冷的话。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11198_UnlockDesc|唤醒体等级达到1级"
  },
  [11202] = {
    ID = 11202,
    CnID = "唤醒体故事@嘀嗒人·故事一",
    BaseSortID = 178,
    ActorIndex = 15603,
    Title = "AwakerStory_11202_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11202_Content|A.F. 297年@1月@1日03:47分，亚格罗共和国@3州@1@2@1镇东南方发生不明爆炸。冲击波在当地引发了3.8级地震，震感明显，波及到距@1@2@1镇5公里外的村落。\n事件后@1@2@1镇与其他区域失去了联系，周边居民则无法回忆起该镇的所在。基于此，审查会派遣成员前去调查，并于@1@2@1镇边缘检测出融蚀物质。\n将小镇封锁后，由弥萨格大学调查员进行了融蚀体清除工作，并于疑似爆炸中心的强融蚀区域回收E-1929号银芯。\nE-1929较为特殊，其诺斯指数长期处于不规则波动状态，且会自主发出齿轮运转一般的嘀嗒声，唯有在与强融蚀区回收的机械碎片连接时能维持短暂的稳定。基于这一特性，弥萨格大学唤醒体系以机械碎片包裹E-1929，在诺斯指数趋向稳定后迅速进行了唤醒。\n——《E-1929银芯获取及唤醒报告摘要》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11202_UnlockDesc|同调率等级达到3"
  },
  [11180] = {
    ID = 11180,
    CnID = "唤醒体故事@嘀嗒人·故事二",
    BaseSortID = 179,
    ActorIndex = 15603,
    Title = "AwakerStory_11180_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11180_Content|昨日18时，位于弥萨格大学亲王大楼地下的CB-101室遭到不知名人士的破坏。加固房门遭到严重破坏，室内外墙面均有黑色闪电状焦痕分布，现场一片狼藉。\n「瞬时的超强电流可以导致这样的痕迹，」对墙面的焦痕，电气工程专业的亚当姆斯博士这么评价，「这需要极大的电压。如果是普通仪器，它将十分巨大，很难掩人耳目。但如果是银芯……一切皆有可能。」\n在银芯常年处于唤醒系严加看管的情况下，很难想象有人能够私自使用银芯而不被察觉，也因此，更多的目光转向了体内具备银芯能量的唤醒体。\n「要我说啊，这事儿肯定是她干的。」一名不愿透露姓名的唤醒体系学生如此告诉记者。当被询问具体是谁时，他显得有些紧张，「就是『她』啊，被称为『嘀嗒人』的那家伙！你没听过她身体里连续不断的电流声吗？一说到电流我就想到她了，肯定是。」\n不少学生发表了类似的怀疑。但这位行动如发条木偶，面带诡异微笑的唤醒体并非孤立无援，几位调查员公开支持艾瑞卡，并呼吁所有人以事实为重，以证据为准，切勿因为个人偏见对他人造成伤害。\n对此，唤醒系代理负责人索科洛娃博士拒绝发表回应。事件仍在进一步调查中。\n——节选自《弥萨格日报》，《CB-101室爆炸事件初探》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11180_UnlockDesc|同调率等级达到5"
  },
  [11230] = {
    ID = 11230,
    CnID = "唤醒体故事@嘀嗒人·故事三",
    BaseSortID = 180,
    ActorIndex = 15603,
    Title = "AwakerStory_11230_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11230_Content|汉娜：在你看来，还是自动人偶时的你和现在的你，有什么区别吗？\n艾瑞卡：那时的我保留了「情绪」。\n汉娜：具体是怎么样的情绪呢，如果你愿意分享的话？\n艾瑞卡：抱歉，我不明白你的问题。\n汉娜：呃，就是，如果你觉得这个问题比较私密，可以不回答。\n艾瑞卡：我无法感知「愿意与否」，非常抱歉。\n汉娜：那……请告诉我你当时的情绪？\n艾瑞卡：血肉的我经历了爆炸而生还：高兴、欣喜。\n发现自己的精神转移并保存至机械人偶上：紧张，兴奋。\n发现意识逐渐不受控制，并产生强烈的破坏欲：紧张，恐惧，保护。\n汉娜：保护？\n艾瑞卡：非常抱歉，详细信息已丢失。\n汉娜：那么换个问题，这也是本报读者都希望知道的，为什么你现在没有情感了呢？发生了什么？\n艾瑞卡：因不明原因无法通过精神链接恢复理智，大学采取必要措施，以银芯辅助器械对所有情感进行压制，降低攻击性与危险性，保留智能，保留可用性。\n——节选自《弥萨格日报》，《唤醒体教职工专访：嘀嗒人》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11230_UnlockDesc|同调率等级达到7"
  },
  [11199] = {
    ID = 11199,
    CnID = "唤醒体故事@嘀嗒人·故事四",
    BaseSortID = 181,
    ActorIndex = 15603,
    Title = "AwakerStory_11199_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11199_Content|汉娜：你还记得在你解体前发生了什么吗？\n艾瑞卡：自动人偶行为开始失控，意识出现断层，且在断层期间会将所有的一切全部摧毁一切的一切都将覆灭在电流和火焰之下\n汉娜：艾瑞卡？\n艾瑞卡：……\n汉娜：我不会那么好运碰到「嘀嗒人效应」了吧……艾瑞卡？\n艾瑞卡：头部组件恢复运转，为刚才的不便向你道歉。\n如我刚才所说，自动人偶注意到自身对人类的威胁性逐渐增强，且由于自动人偶当时仍将自己视作人类，因此十分痛苦。\n汉娜：你之前说的保护是指保护人类？\n艾瑞卡：自动人偶期望保护，没错。\n汉娜：那你刚才为什么不告诉我呢？\n艾瑞卡：……\n汉娜：需要我换个问题吗？\n艾瑞卡：不。现在的我已不受情绪所困，可以回答。\n察觉到自身危险性后，自动人偶尝试在意识断片前对躯体造成短路，降低躯体自行造成破坏的可能性。\n保护最终还是失败，人类朋友死亡。\n自动人偶感到悲伤，后悔，绝望。\n自动人偶爆炸自毁，以确保自身不会造成更多的破坏，随后银芯被弥萨格大学回收，制作出了我，艾瑞卡，躯体编号EA307881。\n——摘抄自汉娜·皮斯利题为《0711，嘀嗒人专访》的录音",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11199_UnlockDesc|同调率等级达到9"
  },
  [11233] = {
    ID = 11233,
    CnID = "唤醒体故事@青炎舞者·简介",
    BaseSortID = 182,
    ActorIndex = 15562,
    Title = "AwakerStory_11233_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11233_Content|她在绿炎的簇拥下起舞，幽幽火光映出了舞者稚嫩而虔诚的脸庞。伴着谢内回旋的舞步，苍翠火焰点燃了所有宵小之徒的魂灵，烧却舞台上所有污秽。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11233_UnlockDesc|唤醒体等级达到1级"
  },
  [11314] = {
    ID = 11314,
    CnID = "唤醒体故事@青炎舞者·故事一",
    BaseSortID = 183,
    ActorIndex = 15562,
    Title = "AwakerStory_11314_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11314_Content|A.F.31@1年12月中旬，警方接到了@2花园第二剧场管理者的报案。报案人称，剧场一周内发生了四次小范围失火，「芭蕾幽灵」的流言在租用剧场的舞团成员中甚嚣尘上。\n为了保证芭蕾舞剧《天鹅挽歌》首次公演的顺利举行，警方与西区消防局展开了联合调查。\n公演前日，弥萨格大学最终接管了调查。调查员们注意到，多处起火点背后都有灵知残留的痕迹。最终，@3调查员在第二剧场地下废墟中发现了一名唤醒体。\n该唤醒体并非无理智个体，她自称「莉兹」。经过沟通，唤醒体莉兹最终承认了自己的纵火罪行。《天鹅挽歌》首场公演结束后，@3调查员将唤醒体莉兹带回弥萨格大学，进行了正式收编。\n\n根据历史记录，A.F.29@1年@2花园第二剧场大火燃起时，剧场正在上演芭蕾舞剧。当日丧生火海的，除了台下一众勋贵外，还有一位名为「伊丽莎白·萨勒」的年轻芭蕾首席。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11314_UnlockDesc|同调率等级达到3"
  },
  [11373] = {
    ID = 11373,
    CnID = "唤醒体故事@青炎舞者·故事二",
    BaseSortID = 184,
    ActorIndex = 15562,
    Title = "AwakerStory_11373_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11373_Content|莉兹是个令人省心的唤醒体，尽管态度远不能被称为「热情」，但她对学校一切事务都表现出了相当的配合。\n唯一令人在意的是，虽然莉兹成日成夜待在舞蹈教室里，却没有任何人见过她真正的舞姿。\n作为一名优秀的芭蕾演员，莉兹的名字曾出现在一些相关报刊上。可惜的是，因为融蚀现象的影响，唤醒体系情报科仅能确定莉兹曾在A.F.29@1年登上过第二剧场的舞台。\n校报记者汉娜·皮斯利曾提议，在校内召集舞蹈爱好者，用他们对舞蹈的热爱「敲开唤醒体莉兹的内心」。\n目前，这一提议暂未被唤醒体管理处通过。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11373_UnlockDesc|同调率等级达到5"
  },
  [11319] = {
    ID = 11319,
    CnID = "唤醒体故事@青炎舞者·故事三",
    BaseSortID = 185,
    ActorIndex = 15562,
    Title = "AwakerStory_11319_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11319_Content|加入舞团的第四十五天，我作为首席演员站在了舞台上。\n炽热的光线打在裙边，细碎的钻石折射出眩人的美。那光芒让我无法自如视物，但从雷动的掌声中，我知道我的表现比宝石更为夺目。\n在不停地回旋中，世上所有尘埃都将被纯净的舞蹈荡涤，向全世界送去舞蹈之美、艺术之美，这是我身为舞者的愿望和使命——\n\n但是，那些藏在舞台下阴暗角落里的人们，是怎么回事？\n\n莉赛特，那个行事洒脱磊落的女孩，她怎会与那位臭名昭著的老爷窃窃私语？\n安杰利卡，那个总是睥睨其他舞者的天才，她为何会对那名花名在外的公子提起裙摆？\n\n如此不堪……如此的污浊！神明啊，我的缪斯，请告诉我，我要怎么做，才能从黑暗中守护我的舞台，要何等的光明才能驱散这污秽——",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11319_UnlockDesc|同调率等级达到7"
  },
  [11352] = {
    ID = 11352,
    CnID = "唤醒体故事@青炎舞者·故事四",
    BaseSortID = 186,
    ActorIndex = 15562,
    Title = "AwakerStory_11352_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11352_Content|这里是应许之地，这里是艺术的理想乡，这里是无上的极乐之所——舞蹈理应成为舞者的归宿，理应维持着永恒的纯净。\n只要我燃烧着，那不堪的便无法玷污我们的圣堂……这是我的使命，我的希望……请允我熊熊燃烧吧，我会为了大家，烧尽那污浊的一切。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11352_UnlockDesc|同调率等级达到9"
  },
  [11329] = {
    ID = 11329,
    CnID = "唤醒体故事@24·简介",
    BaseSortID = 187,
    ActorIndex = 15601,
    Title = "AwakerStory_11329_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11329_Content|在孤独中，一个人要像一支队伍。24的脑袋有些拥挤——她们在黑暗中私语、窃笑，不断撕扯24的内心，渴望将她吞吃入腹。自街角下水道散发的恶臭、工区漫天纷飞的棉絮、过期的黑面包……过往早已逝去，无人记得东区的平凡女工，她终于褪去疲惫的肉身，却踏入新的泥潭。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11329_UnlockDesc|唤醒体等级达到1级"
  },
  [11216] = {
    ID = 11216,
    CnID = "唤醒体故事@24·故事一",
    BaseSortID = 188,
    ActorIndex = 15601,
    Title = "AwakerStory_11216_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11216_Content|唤醒体编号：MA-C06\n危险等级：A\n特殊收容措施：MA-C06目前暂被安排在7号唤醒体观察室内，配备昏暗的灯光。因害怕被@3夺取心智，MA-C06拒绝睡觉，室内只配备了一把椅子。\n由于持续良好的行为及友好态度，MA-C06已被批准允许使用温室，允许探索校园部分区域，前提是至少有一名调查员陪护。\n——《唤醒体收容档案·MA-C06》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11216_UnlockDesc|同调率等级达到3"
  },
  [11217] = {
    ID = 11217,
    CnID = "唤醒体故事@24·故事二",
    BaseSortID = 189,
    ActorIndex = 15601,
    Title = "AwakerStory_11217_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11217_Content|弥萨格使用从死者体内析出的银芯，炼制成唤醒体。\n雕塑家协会从活人体内催生出银芯，并炼制成唤醒体。\n这是两种截然不同的理念，后者虽拥有极高的上限，却显然违背了伦理道德，因此成为了屡禁不止的禁忌研究。\n蜡像馆事件后，24便被带回了弥萨格。她长期辗转校园观察室及研究室内，出行皆需专人陪护。\n毫无疑问，这是个极度不可控的活人唤醒体。在后续观察的小半年时间内，24体内又陆续分裂出了许多人格。\n她会忽然多出陌生的朋友、敌人，买了许多奇奇怪怪的东西，甚至在不知道的时候学会了说中文。\n她的人生永远不缺「惊喜」。\n「24是由一系列孤立的点构成的离散函数。」朵尔评价道，「不要相信她说的每一句话。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11217_UnlockDesc|同调率等级达到5"
  },
  [11167] = {
    ID = 11167,
    CnID = "唤醒体故事@24·故事三",
    BaseSortID = 190,
    ActorIndex = 15601,
    Title = "AwakerStory_11167_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11167_Content|24搬来不到一个月便发现家里遭了小偷。\n先是奶酪，随后是面包、牛奶、番茄……家里的食物总会悄无声息地少那么一点点。\n她耐心蹲守了好几天，终于发现了罪魁祸首——一只老鼠。它左摇右晃躲过了24为它设置的陷阱，抓起两朵香菇就消失在了地窖门后。\n24掀开地窖门，顺着潮湿发霉的阶梯下来，发现这里竟通向一个地下水道。\n老鼠举着香菇窜进阴影中。24跟了过去，在黑暗中望见一双明亮的眼睛，像小狼崽。她将碎布穿在身上，在接近零下的温度里盖着旧报纸，全身抖得厉害。\n24的心被微微刺了一下。\n「蘑菇最好不要生吃，会生病的。」\n小孩依旧沉默。\n24上去煮了一锅蘑菇汤，盛了一小碗摆在桌上，随后便睡觉去了。她每天凌晨6点就要起来上工，几乎没什么休息时间。\n等到第二天醒来，碗还放在原本的位置，但是汤被喝得干干净净。\n那以后，24时不时多做一点吃的，用以款待楼下的邻居。对方也会偶尔回馈她一些小礼物，通常是一些不知道哪里捡来的小首饰、玩具……\n\n新的默契，就此达成。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    ConditionType_1 = "StageFirstClear",
    ConditionPara_1 = {7755},
    UnlockDesc = "AwakerStory_11167_UnlockDesc|同调率等级达到7",
    UnlockDesc_1 = "AwakerStory_11167_UnlockDesc_1|通关主线普通第2章「以蜡像之名」"
  },
  [11238] = {
    ID = 11238,
    CnID = "唤醒体故事@24·故事四",
    BaseSortID = 191,
    ActorIndex = 15601,
    Title = "AwakerStory_11238_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11238_Content|那年11月的下雪天，24生病了。\n经过连续一周的高强度工作，她发了很严重的烧，在家里躺了好几天。\n朦胧中她似乎听到小老鼠在耳畔哀哀地叫着。过了不知多久，有人站到了她身边。\n她认得那双眼睛——是下水道里的那个孩子。她满身泥泞，将手中脏兮兮的药丸递给24。\n「给你的，吃吧。」小孩生硬地说道，声音很好听——原来她是个女孩子。\n24望着她手肘和脸上的伤口，没有问这些药是从哪里来的。她紧紧握着女孩的手。\n女孩不自在地哼了几声，像哄小孩一样酷酷地说：「我不走。你好了我再走。」\n好了也别走。\n24在心里回了一句。\n初冬的伦蒂尼恩下了整整一周的雪。雪停的那天24很高兴，因为她不仅退了烧，还收获了一个妹妹。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    ConditionType_1 = "StageFirstClear",
    ConditionPara_1 = {7755},
    UnlockDesc = "AwakerStory_11238_UnlockDesc|同调率等级达到9",
    UnlockDesc_1 = "AwakerStory_11238_UnlockDesc_1|通关主线普通第2章「以蜡像之名」"
  },
  [11172] = {
    ID = 11172,
    CnID = "唤醒体故事@星之芽·简介",
    BaseSortID = 192,
    ActorIndex = 15577,
    Title = "AwakerStory_11172_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11172_Content|菲茵特是一粒褪色的、难以破壳的种子。\n人们因她的残缺而怜悯她，因她的虚弱而爱怜她。\n知道她是自愿留在壳中之人，已然化作齑粉，成为星之尘埃。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11172_UnlockDesc|唤醒体等级达到1级"
  },
  [11326] = {
    ID = 11326,
    CnID = "唤醒体故事@星之芽·故事一",
    BaseSortID = 193,
    ActorIndex = 15577,
    Title = "AwakerStory_11326_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11326_Content|洪积282年6月，根据密斯底亚协定审查会递交的调查申请，我们派出一支调查队前往了新雷欧地区。\n自一年前陨石坠落事件后，该地区的异常死亡率就居高不下。\n此外，调查员还在坠落现场发现了数种变异植物。经仪器测定，这些植物含有疑似由陨石带来的高量辐射。\n然而在陨石坑内并不存在任何地外矿物。村民证言，在陨石坠落的第三天，一批白袍科学家就切割并带走了陨石。\n（备注：疑似民间科学组织，身份存疑。）\n经审查会与当地政府协调，居民已全部搬离，此地被官方宣布为生活禁区。\n据弥萨格大学物理实验室测算，该地区的生活禁令需要维持至少80年。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11326_UnlockDesc|同调率等级达到3"
  },
  [11271] = {
    ID = 11271,
    CnID = "唤醒体故事@星之芽·故事二",
    BaseSortID = 194,
    ActorIndex = 15577,
    Title = "AwakerStory_11271_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11271_Content|菲茵特看见了躲在实验室偷偷落泪的学生。\n这不是她最喜欢的，却是最喜欢她的一个学生。\n女学生从来不介意菲茵特的抗拒和疏离，不害怕菲茵特不受控的能力。\n会用生活费买下所有甜食，只因为担心她能量不够；会穿上笨重的防护服，只为给她梳理睡乱的长发。\n……要回报她，菲茵特是这么想的。\n因此，菲茵特做了些力所能及的事。\n——如果只是担心考试不合格而哭泣的话，那么威胁其他人放弃成绩就好了吧？",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11271_UnlockDesc|同调率等级达到5"
  },
  [11330] = {
    ID = 11330,
    CnID = "唤醒体故事@星之芽·故事三",
    BaseSortID = 195,
    ActorIndex = 15577,
    Title = "AwakerStory_11330_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11330_Content|这对姐妹中，有一人是不该出生的存在。\n在无法被观测的天琴座荒星上，菲茵特与汀克特在恶言中度过了半生。\n但究竟谁是那个不被承认的存在呢？\n姐姐菲茵特强大却无法自控，所掠取的生命力总像河流般逝去，只能靠舔舐残留的露珠勉强度日。\n妹妹汀克特美丽却难于自立，如浮萍般倔强却无处扎根的生命，只得围绕着姐姐回旋。\n也许，她们彼此都认为自己是不该存在的那人，只是菲茵特更早做出了决断——以自我了断做威胁，她将妹妹强行推上了离开的旅程。\n「离开吧，汀克特。不要让我绊住你。」\n「你要在星间歌唱，成为最受瞩目的色彩。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11330_UnlockDesc|同调率等级达到7"
  },
  [11308] = {
    ID = 11308,
    CnID = "唤醒体故事@星之芽·故事四",
    BaseSortID = 196,
    ActorIndex = 15577,
    Title = "AwakerStory_11308_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11308_Content|我有拥有愿望的资格吗？\n如果有的话，可以让我成为妹妹的一部分吗？\n让她变得完整，让我们变得完整。\n这样一来，我能毫无顾忌地表达「爱」，她也能心无旁骛地拥抱「爱」。\n亲爱的汀克特呀……这是我身为先出生的孩子，应该为你做的吧。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11308_UnlockDesc|同调率等级达到9"
  },
  [11283] = {
    ID = 11283,
    CnID = "唤醒体故事@本源知者·简介",
    BaseSortID = 197,
    ActorIndex = 15568,
    Title = "AwakerStory_11283_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11283_Content|她计算着出剑的速度，计算着躲避攻击的角度。\n她计算着出逃方案的可行性，计算着世界能够迈向未来的概率。\n直到最后，她都没有放弃演算。\n正如她从未放弃行走在这条无人之境上。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11283_UnlockDesc|唤醒体等级达到1级"
  },
  [11184] = {
    ID = 11184,
    CnID = "唤醒体故事@本源知者·故事一",
    BaseSortID = 198,
    ActorIndex = 15568,
    Title = "AwakerStory_11184_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11184_Content|■档案编号：AF315-C01\n■唤醒体代号：@2行者\n该唤醒体于A.F.315年@1月被首次观测。\n在首次开展「人工密境」实验时，受同源之物精神共鸣的影响，以我校@2级学生拉蒙娜·德克斯特精神领域为基础展开的「人工密境」意外突破了维度界限。\n时任守密人在该「人工密境」中，首次确认了维度外世界的存在，同时也确认了@2的力量将对拉蒙娜·德克斯特造成怎样的影响。\n此后，唤醒系科研所正式展开了针对「本源唤醒体」的研究。\n同时，对拉蒙娜·德克斯特力量控制课程的教案规划也正在提上日程。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11184_UnlockDesc|同调率等级达到3"
  },
  [11242] = {
    ID = 11242,
    CnID = "唤醒体故事@本源知者·故事二",
    BaseSortID = 199,
    ActorIndex = 15568,
    Title = "AwakerStory_11242_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11242_Content|「拉蒙娜」对于现身一事表现得非常克制。正如她所说的一样，只有守密人呼唤她时，她才会借拉蒙娜的身体现世。\n她总是来去匆匆，除了战斗外，她似乎不想再与我们的世界产生更多交集。\n是恐惧那些纠缠她的梦魇吗？还是害怕自己贪恋这些她已失去的……我们无从知晓。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11242_UnlockDesc|同调率等级达到5"
  },
  [11188] = {
    ID = 11188,
    CnID = "唤醒体故事@本源知者·故事三",
    BaseSortID = 200,
    ActorIndex = 15568,
    Title = "AwakerStory_11188_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11188_Content|她有过令人艳羡的出生：被当作唯一继承人抚养长大的孤女，何其幸运。\n她有过令人惊讶的天慧：一岁能言，二岁能辩，三岁时便开始了对世界的启蒙。\n她有过令人赞叹的才能：过目不忘，握剑成招。以不可思议的稚龄，满分通过了弥萨格大学严苛的预科课程。\n她有过值得互相依托后背、值得携手奔赴暗黑与未知的同伴。\n<Italic:她有过……>",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11188_UnlockDesc|同调率等级达到7"
  },
  [11219] = {
    ID = 11219,
    CnID = "唤醒体故事@本源知者·故事四",
    BaseSortID = 201,
    ActorIndex = 15568,
    Title = "AwakerStory_11219_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11219_Content|占据拉蒙娜身体时，「拉蒙娜」不曾行走于校园之中。\n萝坦的豪放大气、奥吉尔的腼腆忠诚、威廉的冷静自持、朵尔的严苛认真……没有人比她更将这些瞬间铭记于心。\n但她始终谨记着：这些美好之物，已经不再属于她。\n现在的她，需要全神贯注守护另一个命定之人……这也是为了守护另一个岌岌可危的世界，为了守护另一个天真的自己。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11219_UnlockDesc|同调率等级达到9"
  },
  [11182] = {
    ID = 11182,
    CnID = "唤醒体故事@本源缸中之脑·简介",
    BaseSortID = 202,
    ActorIndex = 15602,
    Title = "AwakerStory_11182_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11182_Content|天才与疯子只有一线之隔。作为弥萨格曾经最耀眼的天才，她的堕落也如同大厦倾倒，从那理性的废墟中爬出的，只剩下一只最疯狂的恶鬼。\n她如常披好科学的外衣，将生命、人性、爱与毁灭倒进坩埚，炮制成了摧毁世界的毒药。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11182_UnlockDesc|唤醒体等级达到1级"
  },
  [11362] = {
    ID = 11362,
    CnID = "唤醒体故事@本源缸中之脑·故事一",
    BaseSortID = 203,
    ActorIndex = 15602,
    Title = "AwakerStory_11362_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11362_Content|在一切的真相水落石出之前，没有人曾怀疑过朵尔会是那一连串耸人听闻的事件的真凶。\n毕竟她在弥萨格与融蚀战线中的存在始终如中流砥柱、高塔明灯一般，是所有人心底坚如磐石的依靠。\n当无数人类夜空中的明星被融蚀击溃消散，这位永不动摇的人类明灯终于也残忍地熄灭，化作了阴影中与黑暗同源的推手。\n龙卷风、洪灾、大地震……效率低下的凶杀显然不符合天才的规划，她用那未曾减少一分的智慧将她曾引以为豪的银芯科技改造为了「推动世界」的致命武器，在弥萨格看不见的地方送去了一份又一份毁灭的大礼。\n最终她被抓捕时，人偶的躯体已经不能被腐蚀的大脑精密控制，那张曾经平静如水的面孔上充斥着扭曲诡异的表情，仿佛只要与之对视就会坠入疯狂的深渊。\n所有人不约而同地选择忽略了她时而模糊的絮语，哪怕那可能真的透露了世界的真相。\n只因她的遭遇已经再一次证明，人类终究是需要意义才能生存下去的生物。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11362_UnlockDesc|同调率等级达到3"
  },
  [11298] = {
    ID = 11298,
    CnID = "唤醒体故事@本源缸中之脑·故事二",
    BaseSortID = 204,
    ActorIndex = 15602,
    Title = "AwakerStory_11298_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11298_Content|因该前身为「缸中之脑」的本源唤醒体有过挣脱S355拘束器的历史，当前已由诃勒特院长执行转移，安置至新型特殊融蚀限制器中。\n该限制器位于黑池深处，在保证限制器周围30米半径不存在任何其他仪器与物品的情况下，由黑池监测小组安排至少每60分钟一班的巡视监控。\n在监测中发现，该唤醒体始终保持意识清醒，几乎从未有过睡眠活动。该唤醒体曾试图对巡视成员讲述其之前进行的违规银芯改造实验，一位小组成员因与其进行短暂交流而陷入疯狂。\n目前所有巡视小组由三人构成，严禁与该唤醒体产生任何接触或谈话，并在巡视时全程佩戴隔音耳罩。\n……\n该唤醒体的保密限制级别已达到唤醒体收管最高等级，任何知情人员不得向弥萨格内外透露该唤醒体有关消息，如无院长批准并亲自护送，禁止任何人前往探视。\n——节选自《弥萨格黑池监测小组报告记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11298_UnlockDesc|同调率等级达到5"
  },
  [11357] = {
    ID = 11357,
    CnID = "唤醒体故事@本源缸中之脑·故事三",
    BaseSortID = 205,
    ActorIndex = 15602,
    Title = "AwakerStory_11357_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11357_Content|作为走在融蚀研究最前线的人，朵尔一直清醒地知道身后那湮灭的脚步正不断追赶，更何况，在被融蚀这件事上她早已再熟悉不过。 \n在对真相不断前进而不断失败的探寻下，朵尔慢慢意识到目前人类的肉体或许具有天然的盲目性，属于现实的人无论如何努力也无法看见彼岸的景色。 \n那么黑色的黏浆在消解身体的同时，是否同样会将灵魂引向真实的彼岸？ \n她与那些远古石板上的箴言静默对坐，任由融蚀侵蚀了脑缸。无论那道路尽头是什么，她都已无法回头。 \n幸运而又不幸，她用自身的存在做赌注，终于换来了进入世界内侧的机会，于是一瞬间，真实、虚无和毁灭同时淹没了她。 \n一次眨眼间，她见证了宇宙的一切，融蚀的本质、世界的真相，她渴求一生之物这里应有尽有。 \n所有科学的信仰和理性的坚持化为泡影，一直坚定如铁的精神壁垒陡然崩塌。 \n那个名为朵尔的天才已经消失，现在站在这里的，仅仅是一具被虚无占领的生骸。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11357_UnlockDesc|同调率等级达到7"
  },
  [11273] = {
    ID = 11273,
    CnID = "唤醒体故事@本源缸中之脑·故事四",
    BaseSortID = 206,
    ActorIndex = 15602,
    Title = "AwakerStory_11273_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11273_Content|所有意义如沙般消散，世界虚假的幕布在她眼中褪去，一切回归最原始的黑暗。\n在这漆黑舞台最后的演出上，科学的舞者依然全力起舞。\n她不再在意被融蚀缓慢吞噬，因那剧目的结尾早在一开始就已经写好。\n一如往昔，她会将天才的力量毫无保留地奉献给世界，以最接近真理的方式。\n如果你稍微追问，她会坚称自己仍保有对人类与世界的爱，她要结束人间一切的痛苦，将人们带回真正的、最初的家园。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11273_UnlockDesc|同调率等级达到9"
  },
  [11181] = {
    ID = 11181,
    CnID = "唤醒体故事@本源深海淑女·简介",
    BaseSortID = 207,
    ActorIndex = 15589,
    Title = "AwakerStory_11181_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11181_Content|她总是倨傲地以「神之母」自称，冷漠而充满敌意地将每个人排除在自己的安全范围之外。初次见面的人，很难将她与那个骄纵的小公主联系起来。\n「但她们本质上还是同一个人，」守密人却总是固执地向每个人传达，「只要你见过她一个人狼吞虎咽小蛋糕的模样就知道了。」",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11181_UnlockDesc|唤醒体等级达到1级"
  },
  [11311] = {
    ID = 11311,
    CnID = "唤醒体故事@本源深海淑女·故事一",
    BaseSortID = 208,
    ActorIndex = 15589,
    Title = "AwakerStory_11311_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11311_Content|记录者：埃里希·冯·维尔纳\n时间：19@1年11月7日\n坐标：68°14′S, 67°10′W\n\n由于航向上异常漂浮的大量抹香鲸尸体，我们被迫登陆这片被诅咒的冰原岛屿。在南岸峡湾的冰瀑下方，探险队发现一具约五十英尺长的头足类遗骸。其尸身呈深靛蓝色，体表密布磷光幽蓝的同心圆环，环纹边缘分泌出薄层黏液。我们取样提纯后，黏液中析出令人不安的大量蓝色晶体。\n该遗骸腕足吸盘直径逾两英尺，吸盘内壁雕刻着近似不明文字的纹路。主神经索呈半透明凝胶态，在零下三十度环境中仍保持微弱搏动（详见附图D-7）。随行生物学家哈里斯博士试图采集神经索组织样本，但在手术刀接触瞬间，整具尸骸突然粉碎化。肉眼可见的靛蓝色尘埃悬浮于整片实验室内。\n\n归航途中，哈里斯博士出现持续性谵妄。他反复在舱室墙壁绘制螺旋与多面体组合的几何图形，并嘶吼着「它们在南极冰盖下产卵」。第二日清晨，巡查的船员发现他溺毙于压载水舱，尸检显示其肺泡内充斥靛蓝色微生物（与章鱼尸尘同源）。船长下令焚烧所有接触过样本的衣物。\n但愿无人再接触到这潜藏于冰层下的噩梦。\n\n——《南极科考日志·第37号附录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11311_UnlockDesc|同调率等级达到3"
  },
  [11350] = {
    ID = 11350,
    CnID = "唤醒体故事@本源深海淑女·故事二",
    BaseSortID = 209,
    ActorIndex = 15589,
    Title = "AwakerStory_11350_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11350_Content|被唤醒后，诞妄·墨菲就经常做一个关于逃亡的梦，在那场梦的最后，她手握「母亲」的匕首，在皎白的月光下贯穿了自己的胸膛。随后梦戛然而止，睁开眼的瞬间，恰好对上了床前那尊象牙雕像。\n\n诞妄·墨菲在弥萨格内的行动仿若她的「养育者」的年轻版本，她终日身着缟素，不轻易与人谈笑，只有话题偶然流转到对甜食的喜好时，那无瑕的圣母面具会暴露出一条裂痕。\n（档案员批注：希望下次她想要品鉴小蛋糕的时候，可以当场提出，而不是在所有人的下午茶时间结束后，留一张字条要求送到她的房间里。）\n\n她习惯于与任何来自蹈海者的唤醒体保持距离。与另一个世界的自己不同的是，她从不刻意回避与相关者的接触，只是那冻结在脸上的冰冷表情与暗含敌意的讽刺，不知不觉中就驱离了那些不想碰硬钉子的家伙们。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11350_UnlockDesc|同调率等级达到5"
  },
  [11292] = {
    ID = 11292,
    CnID = "唤醒体故事@本源深海淑女·故事三",
    BaseSortID = 210,
    ActorIndex = 15589,
    Title = "AwakerStory_11292_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11292_Content|诞妄·墨菲曾经经历过一次死亡。\n在并非欣然地踏入名为「神降」的门扉之后，她目睹了「神明」于她的胸膛诞临。\n多可笑啊，那是一团无意识、无知觉的丑陋团块，她却不得不为之付出了鲜活灿烂的人生。\n更讽刺的是，倒错的命运始终不依不饶。神明降生于世的时刻，她在忍受着剧烈的疼痛中接纳了并非心甘情愿的牺牲。经历漫长的、宛若沉睡的时光后，墨菲惊愕地睁开双眼，发现眼前的景象与临终前别无二致。\n\n「墨菲」死去，「诞妄·墨菲」苏醒。\n\n她的链接者，是一团由她亲自诞下的，耳不能闻、口不能言的蠕动血块。\n神明诞下王女，王女重孕神明，而神明再次唤醒了她的遗骸，病态的命运紧紧纠缠着她，永无天日，不可断绝。\n她虔诚的母亲欣喜若狂，蹈海者伏地祝祷，她的尊荣得以延续，甚至比往日更盛。\n但那个「墨菲」终究是永远地消失了。曾经凭借一腔愚蠢的天真，妄图对不公命运发起叛逆的少女，拥抱着一度厌弃的虚荣冠冕，踏上了永远无法抵达彼岸的游轮。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11292_UnlockDesc|同调率等级达到7"
  },
  [11368] = {
    ID = 11368,
    CnID = "唤醒体故事@本源深海淑女·故事四",
    BaseSortID = 211,
    ActorIndex = 15589,
    Title = "AwakerStory_11368_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11368_Content|「神的女儿，同时也是神的孕育者。」\n这是她确认权威的方式，唯有保持万众瞩目的尊荣，她才能维持岌岌可危的平衡。是伪善又怎样？是虚妄又如何？谁不是活在「当下」的时刻？\n墨菲怀抱着包裹丑恶圣胎的襁褓，代行神的旨意，吐露出一个接一个的谎言。\n「祂已降临。」\n「神国必将上浮。」\n「请静静等候下一个星辰正位之刻。」\n与其任由伪善的他人虚构出幻象，不如将这座牢笼亲手妆点成自己满意的模样。只要她所渴望的「母亲」、「伙伴」、「仆人」都还陪伴在自己的身旁，无论是貌合神离的卑躬屈膝还是口是心非的故弄玄虚，她都欣然接受，且甘之如饴。\n「我叫墨菲，是诞下神明的王女。关于利莫里亚、关于蹈海者的夙愿……你不必打探，我自有安排。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    ConditionType_1 = "StageFirstClear",
    ConditionPara_1 = {118146},
    UnlockDesc = "AwakerStory_11368_UnlockDesc|同调率等级达到9",
    UnlockDesc_1 = "AwakerStory_11368_UnlockDesc_1|通关星辰篇普通第4章「乐园」"
  },
  [11252] = {
    ID = 11252,
    CnID = "唤醒体故事@本源破链者·简介",
    BaseSortID = 212,
    ActorIndex = 15567,
    Title = "AwakerStory_11252_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_11252_Content|她的记忆从进入牢狱的那天起，就已经充满了血色。\n过往平淡与温馨的回忆如同虚假的梦境，早已模糊而开裂，化为锋利的碎片一片片嵌入她的血肉。\n她记不清那曾经温柔的怀抱、关切的面庞，留在心中的只有永恒的仇恨与质问。\n疼痛，屈辱，背叛……一切痛苦到底因为什么？\n她日日质问，直到自由来临之时，始终无人回答。\n那么就让她自己来寻找答案，从那些哀嚎尖叫的胸膛中，亲自质问一颗颗肮脏的心脏。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_11252_UnlockDesc|唤醒体等级达到1级"
  },
  [11228] = {
    ID = 11228,
    CnID = "唤醒体故事@本源破链者·故事一",
    BaseSortID = 213,
    ActorIndex = 15567,
    Title = "AwakerStory_11228_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_11228_Content|我好像陷入了某种超自然事件，在此记录我的所有发现……\n我们本来正在对埃夫罗塔斯进行最后的考古收尾，一觉醒来后其他考古队成员都消失了，而这座城镇仿佛一夜回溯了千年。\n早已坍塌的古建筑拔地而起，还原了这座城镇真实的样貌，包括城镇中化为白骨的无数居民。\n兴奋、震惊与恐惧同时攥住了我的大脑，哪怕已经见过无数尸骨，我仍然因眼前的景象不停颤栗，如果任何一个人经历我现在所经历的，他只会比我更加惊恐。\n这座城镇里的所有人貌似都是被同一个人凶残地屠杀的，无数白骨横在街头、倒在房中。城镇的大门不知为何牢牢紧闭，门边挤满了试图逃出却依然被残忍杀死的尸骨，如同一座白骨垒作的小丘。\n我没有找到一个例外的死者，男人，女人，老人，小孩……无数的人都被某种巨大的钝器砸碎身躯或是头颅，面对着风干的白骨，我恍惚间甚至能看到满城流淌着鲜血的样子。\n这里到底发生了什么？\n……\n我茫然地四处搜寻，但没有任何线索，直到我进入了城镇的监狱。\n这里的景象尤为惨烈，凶手怀着巨大的愤怒摧毁了整个监狱，墙壁上有枯褐而扭曲的字迹，像是有人临死前以血写下控诉，我仔细辨认，那似乎是恶灵两个字。\n恶灵？这是指进行屠杀的凶手，还是说这座城镇真的经历过某种超自然事件？\n的确，以一个人的力量屠杀全城太过匪夷所思，恐怕只有真正的恶鬼才能残忍地收割如此多的生命。\n走出监狱后，这座城镇似乎发生了某种微妙的变化，我的鼻子总能闻到一股若隐若现的血腥味。\n就在我试图寻找出路时，一阵突兀的锁链声忽然在城镇中回响，仿佛有人在拖拽着什么沉重的东西前进。\n恶灵！是恶灵……恶灵找上我了！我拼命地跑，可无论跑到哪里，那恐怖的锁链拖拽声始终跟随着我。\n我跑不动了，躲在某个民居的桌子下，我锁起了房门，但那锁链的声音仍然追着我。我听见它来了，它离这里越来越近……\n我多希望这些不过是我的一场梦，只要醒来一切都会消失，等等……那声音好像消失了，恶灵或许已经离开了？\n……\n研究人员备注：正常的笔迹到此结束，只剩下最后扭曲的三个字，经过鉴定这三个字大约是：\n门开了\n——节选自埃夫罗塔斯考古团已故考古人员的日记",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_11228_UnlockDesc|同调率等级达到3"
  },
  [11174] = {
    ID = 11174,
    CnID = "唤醒体故事@本源破链者·故事二",
    BaseSortID = 214,
    ActorIndex = 15567,
    Title = "AwakerStory_11174_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_11174_Content|第一次见到她的人不会产生任何靠近或沟通的想法，生存的本能会拼命发出远离的预警。\n那是一个彻底疯狂的人，或者说一头彻头彻尾的野兽。\n如果能够重新选择，她或许会更愿意当一头野兽，也好过作为人经历的一切。\n她从不信任任何人，当她猩红的双眼看向你时，那眼中的不是怀疑，而是冷漠与杀意。\n她早已不屑怀疑，所有人在她眼中都是同样的卑劣。\n如果需要一条与她相处的忠告，那就是不要试图驯服一头真正的野兽，那不是任何温顺的存在，只要有一丝机会，她的利爪与獠牙就会贯穿你的喉咙。\n尽快在她盯上你之前逃跑吧，并祈祷她的下一个猎物不是你。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_11174_UnlockDesc|同调率等级达到5"
  },
  [11225] = {
    ID = 11225,
    CnID = "唤醒体故事@本源破链者·故事三",
    BaseSortID = 215,
    ActorIndex = 15567,
    Title = "AwakerStory_11225_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_11225_Content|她在那位夫人的关爱与教导下长成了善良而温柔的样子，如同一位真正的贵族小姐，然而只因一次对奴隶无心的帮助，她就被「父母」无情地抛弃了。\n斯巴达人从未接受她，而所有同族却也对她恨之入骨。\n她一瞬成为了所有人眼里的背叛者，失去了自我存在的位置。\n牢狱之中每个人身上都散发着浓重的恶意，仿佛某种能够传染的恶疾，明明他们之间从未相识。\n暗无天日的折磨仿佛永恒，她神经质地恐惧任何人靠近，每天无法入眠，只有偶尔昏迷时能安然闭上双眼，然而睁眼之后便又坠入无尽的噩梦。\n她究竟做错了什么？所有的事是如何走到这一地步的？\n她的怨恨茫然无处安放，无法理清命运的逻辑。\n是因为她有罪吗？\n但如果她有罪，那么所有的人的罪便十倍加之。\n那仇恨日积月累变成怨愤，无尽的愤怒日日夜夜燃烧着她的血液，终于有一天烧毁了那困住她的牢笼。\n缠绕她多年的锁链如今缠绕在一个个嘶喊的脖颈上，多年来锁链早已和她的身体融为一体，那实在是趁手极了，她握着沾满血色的锁链，去追索一个个肮脏的灵魂。\n红色，红色，温热的红色，腥臭的红色。\n看吧，她就知道，没有一个人的灵魂是洁白的。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_11225_UnlockDesc|同调率等级达到7"
  },
  [11206] = {
    ID = 11206,
    CnID = "唤醒体故事@本源破链者·故事四",
    BaseSortID = 216,
    ActorIndex = 15567,
    Title = "AwakerStory_11206_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_11206_Content|她来到世间所经历的一切仿佛都为了让她痛苦，善良、包容、同情、信任……所有人性柔软的部分都已从她的心中剔除，粘连着淋漓的血肉丢弃殆尽。\n她的字典中从未有原谅二字，能消解鲜血与仇恨的，唯有他人的鲜血与仇恨。\n以血还血，这是最公平的、无论战士与奴隶都信奉的法则。\n隐忍千年的火山一夕爆发，一只手从冥界伸出，爬上了人间的土地。\n那是一个复仇的恶灵，要让鲜红的河水流遍人间。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_11206_UnlockDesc|同调率等级达到9"
  },
  [147420] = {
    ID = 147420,
    CnID = "唤醒体故事@暮星·汀克特·简介",
    BaseSortID = 217,
    ActorIndex = 147397,
    Title = "AwakerStory_147420_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_147420_Content|她用歌声打动了千千万万的荒星人。\n不眠的夜里，孩子听着歌声沉入梦河。\n绵绵的细雨里，游子听着歌声不住叹息。\n失去爱人的风里，恋人听着歌声流下最后一滴眼泪。\n而现在，她的听众皆已化作风离去，只留下一地未完的故事……",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_147420_UnlockDesc|唤醒体等级达到1级"
  },
  [147418] = {
    ID = 147418,
    CnID = "唤醒体故事@暮星·汀克特·故事一",
    BaseSortID = 218,
    ActorIndex = 147397,
    Title = "AwakerStory_147418_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_147418_Content|位于金波特城西部山岭的农庄，如今已变成一片荒漠，再也无人居住。\n@2年6月15日，一块陨石坠落于此。数周后，陨石坠落区的生态系统开始变异，植物疯长、结出怪异果实；动物变异，一户居民全家精神失常并离奇死亡。\n弥萨格调查员在当地展开地毯式搜索，最终在井底发现了散发奇异色彩的银芯。据当时经手的调查员回忆，该银芯的色彩是「纯粹的、四处流动的色彩，且与已知光谱中的任何颜色都不尽相同。」\n\n——摘自《弥萨格大学银芯储存记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_147418_UnlockDesc|同调率等级达到3"
  },
  [147419] = {
    ID = 147419,
    CnID = "唤醒体故事@暮星·汀克特·故事二",
    BaseSortID = 219,
    ActorIndex = 147397,
    Title = "AwakerStory_147419_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_147419_Content|1.不要和D03产生直接眼神接触，否则她会以每秒20码的速度冲上来请求你帮她找姐姐。\n2.身上会源源不断地散发热量，我曾亲眼见到她手中的水仙花在短时间内迅速枯萎。哦，真是环保主义者的噩梦！\n3.晚上真的会发光！亮闪闪！救命我的狗眼@3有D03在的弥萨格真的不需要路灯了。\n4.在食堂与D03的手臂发生直接物理接触，我发誓我不是故意的！很奇妙的触感……非要形容的话，像是摸到了麦芽糖浆、羊奶酪、苹果布丁……呜，肚子饿了。\n5.听说暗影合唱团的那帮家伙曾邀请D03加入社团，然后以最快的速度踢掉了她。这很正常，人类的声带再糟糕也是有极限的，我能理解同学们受到的惊吓。\n\n——摘自汉娜《唤醒体观察笔记·D03》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_147419_UnlockDesc|同调率等级达到5"
  },
  [147421] = {
    ID = 147421,
    CnID = "唤醒体故事@暮星·汀克特·故事三",
    BaseSortID = 220,
    ActorIndex = 147397,
    Title = "AwakerStory_147421_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_147421_Content|「唱吧！歌声是温柔的风\n飞出云层，划过星穹\n世界从此与我无关」\n——摘自专辑《群星之彩》序曲\n\n曾是荒星著名的歌姬。\n在那场灾厄来临之际，她将手中的船票转赠给经纪人，因为「不能和姐姐分开」。\n然后她目送满载权贵的飞船悠然离去。那扇曾向她敞开的浮华之门，现在彻底关闭。留给她的，只有沙漠、姐姐和无数同胞。\n他们在静默中聆听死亡倒计时。\n\n十年，二十年，一百年……汀克特用歌声抚慰大家。\n直到喉咙溢出鲜血，她也无法改变姐姐和同胞一个个死去的现实。\n\n歌者汀克特独自穿行在白色的荒漠里，时常幻想姐姐还活着。\n她们像过去一样拥抱彼此，看着头顶的星穹一片片坠落，对岸战舰的残骸静静燃烧。\n她依然不曾放弃歌唱。即使声音嘶哑如破碎的风箱，将附近一切生灵吞噬殆尽。\n歌者只是麻木地、日复一日地唱着歌。\n只要还有歌声，「世界从此与我无关」。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_147421_UnlockDesc|同调率等级达到7"
  },
  [147422] = {
    ID = 147422,
    CnID = "唤醒体故事@暮星·汀克特·故事四",
    BaseSortID = 221,
    ActorIndex = 147397,
    Title = "AwakerStory_147422_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_147422_Content|「当一个人总是在回忆过去，说明他已经老了。」\n若是参照这句老话，汀克特应当衰老如宇宙中流转万年的恒星。\n她的意识里没有现在，也没有未来，只有被无意义延长、不断循环往复的过去。\n\n她曾见金色的烟火如海啸般升起，在宇宙星河中舒展羽翼；\n她曾见数万张不同的脸隐匿在黑暗中，跟随她的旋律纵情起舞；\n她曾见诸天呼唤着她，环绕着她，向她展示它们永恒的辉煌。\n而她的双眼只注视着这片苦难的大地。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_147422_UnlockDesc|同调率等级达到9"
  },
  [60980] = {
    ID = 60980,
    CnID = "唤醒体故事@哈姆林·简介",
    BaseSortID = 222,
    ActorIndex = 54117,
    Title = "AwakerStory_60980_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_60980_Content|初次见面时哈姆林总会让你想到某种来自东方的瓷器，洁白、华丽、优雅的弧线，有某种水波一样貌似温和的光泽，但又触之冰冷。\n在那副体面、精致、一丝不苟的外表下，是极致纯粹或者说极致空虚的灵魂。他的一生从头到尾只有一种念头，就像是只输入了一种指令的机器，丧失了其他所有的反应。\n一切对他来说，不过是如音符一样的排列组合。\n只有演奏、演奏、永不停歇地演奏。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_60980_UnlockDesc|唤醒体等级达到1级"
  },
  [60982] = {
    ID = 60982,
    CnID = "唤醒体故事@哈姆林·故事一",
    BaseSortID = 223,
    ActorIndex = 54117,
    Title = "AwakerStory_60982_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_60982_Content|A.F. 31@1年@1月@2日，一位热爱音乐收藏的著名富豪被管家发现半夜暴毙于家中的书房，身上没有一丝伤口或中毒迹象，嘴角甚至还诡异地留有堪称满足的笑意。\n经警方勘察认定现场为密室条件，经历了无数刑侦高手和法医的检验，最终判定死者为意外猝死。\n然而这位正值壮年、身体康健甚至热爱马术运动的富豪为何在这样一个平平无奇的安静夜晚突然猝死，所有医生也给不出合理的理由。在其家属不满的威胁下，最终警方联系了审查会接管调查。\n原本只想息事宁人的审查会，竟然真的误打误撞从富豪书桌上散落的乐谱中检测出了灵知残留的痕迹。这份诡异的乐谱被送往弥萨格，据研究，这份残缺的乐谱来自著名的《A小调安魂弥撒曲》遗失的后半篇章，然而乐谱的最后一页却依然并不完全，现场发现了许多笔迹狂乱的全新乐谱草稿，似乎是富豪在试图补全最后一页。\n在研究中发现，任何沉迷于乐谱的行为都会不同程度地导致癫狂，这份乐谱也很快被封存保管起来。经弥萨格学者推测，或许就是这项补全行为导致了富豪的疯狂与死亡，并以非常规的方式完成了唤醒仪式。\n之后很长一段时间校方都未搜索到任何这名未知唤醒体现身或伤人的线索，因而此事也逐渐被弥萨格的调查员们淡忘。\n只有音乐领域的学者们始终对那半份被封存的乐谱残篇念念不忘，一直期待着那传奇的安魂曲作者的出现。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_60982_UnlockDesc|同调率等级达到3"
  },
  [60981] = {
    ID = 60981,
    CnID = "唤醒体故事@哈姆林·故事二",
    BaseSortID = 224,
    ActorIndex = 54117,
    Title = "AwakerStory_60981_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_60981_Content|哈姆林并不总在学生们面前出现，即使他愿意出席弥萨格举办的音乐晚会，愿意指导水平堪忧的学生们的音乐课，但大多数时间，他都只是一个人在隔音的教室中、或是偏僻的树林里独自演奏，或者说练习。\n除开正式场合，他一直称呼自己所有的演奏为练习，仿佛那些练习永无止境，完美的鸣奏永远不会出现。\n「真是一位永葆学徒之心般勤奋又谦虚的大师啊。」早已陶醉于那些音乐的人们这样夸赞。\n但，哈姆林从来不知谦虚为何物，他向来懒于琢磨那些应酬客套的说辞，不如说他的言辞总是过于直接，过于严苛。\n关于音乐他总是患有最严重的强迫症，以至于音乐课这种陶冶放松的课程已经在学生中登顶压力最大榜单，哈姆林本人也荣获魔鬼教师的「美名」。\n如果想要获得这位冷淡的音乐家的关注，只需要在演奏时弹错一个半音，那张脸立刻会皱起眉头转视而来。\n其实他对他「折磨」过的人没有任何意见，只不过是把那种堪称狂热的追求与标准强加在了他人身上，即便那已经比他对自己宽容太多。\n他就像是在头顶悬挂了胡萝卜的马驹一样，为自己悬挂了永远无法抵达的准线。\n除开为那位优雅的舞者驻足过，他几乎不会主动与其他唤醒体交流，但面对他人的求助和搭讪，他却总是展示出出人意料的耐心。\n或许阻拦他的不是冷漠，而是过于单一的知识库吧。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_60981_UnlockDesc|同调率等级达到5"
  },
  [60983] = {
    ID = 60983,
    CnID = "唤醒体故事@哈姆林·故事三",
    BaseSortID = 225,
    ActorIndex = 54117,
    Title = "AwakerStory_60983_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_60983_Content|天赋这种东西似乎只是命运过于稀少的偏爱，以至于他在漫长的青春期中都不曾在周围的任何人身上得见，那已经成为了某种飘渺的意象，作为父亲鞭笞自己前进的符号。\n于是他坚信着只有始终坚持的勤奋才是通往完美的阶梯，一直到他站在世界舞台的顶峰，这对他依然是不变的真理。\n直到他遇到了忽然走上前并肩的那个人。\n那是多么耀眼的一位天才，原来那所谓天赋的礼物早已被一人独揽。\n从心底丛生的羡慕和一丝嫉妒中，他突然生出一股无言的迷茫和无助。\n那么我没有那样的东西，还能够到达完美的终点吗？\n走过的阶梯好像忽然化为飞灰，而头顶的大门依然那样遥远。\n他常常徘徊在簇拥着那个人的人群之外，仿佛故作清高地独处。\n但他每每注视着那个方向，心中总是不停排演开口的问好。\n那些平庸的蚊蝇始终围绕在那个人身边，散发恶意的低语。\n他实在是太笨拙的一个人，以至于长久缄默，无从辩解。\n那就用音乐吧，只有音乐是最完美的语言，而那个人一定会听懂。\n直到命运忽然连本带利收走了它所赠予的一切。\n天才早逝，庸人长命。\n从前那些人在背后的挑拨离间、蝇营狗苟他都未曾动摇分毫。\n此刻看着满桌未曾赠出的尚不满意的乐谱，却因痛恨自己而流下泪来。\n他忽然明白，在到达完美的天国前，必须用尽人间的手段。\n好在相比那些庸人，他已拥有足够的头脑。\n毕竟在他眼中，一切不过是如音符一般的排列计算。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_60983_UnlockDesc|同调率等级达到7"
  },
  [60984] = {
    ID = 60984,
    CnID = "唤醒体故事@哈姆林·故事四",
    BaseSortID = 226,
    ActorIndex = 54117,
    Title = "AwakerStory_60984_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_60984_Content|他的生活惯于单调枯燥，孤独对他而言是生命的常态。\n不甘、迷茫、怨恨早就在漫长的时光里消化殆尽，现在他早已和音乐融为一体，那是超越了所谓热爱的本能，无从违抗，不得逃脱。\n他所拥有的全部，也只剩下音乐。\n继续向上走吧，不要回望那九百九十九层阶梯。\n毕竟他已触碰到那终极的乐声、那支命中注定的长笛。\n请接纳这潮水般不绝的音乐，让它浸润你的灵魂、你的梦境。\n正如他也早将灵魂作为乐器，只为与你嗡然共鸣。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_60984_UnlockDesc|同调率等级达到9"
  },
  [66037] = {
    ID = 66037,
    CnID = "唤醒体故事@塔薇·简介",
    BaseSortID = 227,
    ActorIndex = 54116,
    Title = "AwakerStory_66037_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_66037_Content|塔薇不存在于当前的世界。\n她的存在将招致「无上意志」的注视，所以她不能存在，不可存在。智慧和沉默，是她所能给予这些孜孜不倦求索者的全部。\n在日复一日的守候中，她平静地为人类的命运献上自己的智慧、勇气和无声的祝福。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_66037_UnlockDesc|唤醒体等级达到1级"
  },
  [66035] = {
    ID = 66035,
    CnID = "唤醒体故事@塔薇·故事一",
    BaseSortID = 228,
    ActorIndex = 54116,
    Title = "AwakerStory_66035_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_66035_Content|在一场神秘的梦境中，我第一次见到她的身影。\n在笼罩着浓雾的、无尽与无穷的空间里，她看守着连接万千浩瀚宇宙的巍峨宏伟而不朽大门。在那座深深的大门裂隙后，奇异的幻光闪烁跳动着，仿佛传递着某种尚未经过解读的信息讯号。在捕捉到某个讯号的瞬间，我仿佛失去了自己的躯体，我茫然无措地漂浮在群星之间，周身都被不可思议的黑暗笼罩。我惶恐，惊惧，梦境汹涌震荡，沉重的门扉缓慢而不可抗拒地开启，无数类球体如万千星辰在门扉的背后闪耀，那深不可测的浩渺与不可窥视的图景令我感到一阵眩晕……而门的守卫者——塔薇只是永恒而无声地凝视着我。\n——华德·菲利普斯《银钥手记》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_66035_UnlockDesc|同调率等级达到3"
  },
  [66033] = {
    ID = 66033,
    CnID = "唤醒体故事@塔薇·故事二",
    BaseSortID = 229,
    ActorIndex = 54116,
    Title = "AwakerStory_66033_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_66033_Content|塔薇在弥萨格的现身有且仅有三次。\n第一次，她启迪「智慧」的火种。她开辟了梦境的通道，将稀世的智慧教授给蒙昧中探寻的弥萨格创始人。她提供了弥萨格最初的「智库」，和关于融蚀的知识与线索。\n第二次，她带来「变数」的预言。黑池沸腾翻涌，迎接「转变」世界之人的到来。\n第三次，她传递「终末」的讯号。她的痛呼与悲鸣响彻大地，却无力阻止那避无可避的混沌与毁灭的降临。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_66033_UnlockDesc|同调率等级达到5"
  },
  [66034] = {
    ID = 66034,
    CnID = "唤醒体故事@塔薇·故事三",
    BaseSortID = 230,
    ActorIndex = 54116,
    Title = "AwakerStory_66034_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_66034_Content|卡达斯并非她尝试守护的唯一的梦境。\n她亲眼见证了许多星球、许多星系的诞生与覆灭，过去与未来的历史沉淀为知识，收纳入她身后的终极之门中。她饱含悲悯的目光俯瞰着那些图景，化为梦境中的匆匆一瞥，消亡于无垠深渊的黑暗之中。\n她踏上过一片土地，但在她一回眸的瞬间内，她所珍视的一切存在就悉数溃败于「无上意志」的呼吸。\n一而再再而三的重复后，她终于意识到一个严酷的事实，她的存在本身即是噩梦的伏笔，她太过庞大的存在本身足以吸引「无上意志」的目光。她的干涉，只会为她所在意的世界招致更深的厄运。\n所以她退缩，她沉寂。\n直到她在无限空间的浮游意识碎片中，目睹到一片来自「祂」的，变数的可能性……",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_66034_UnlockDesc|同调率等级达到7"
  },
  [66036] = {
    ID = 66036,
    CnID = "唤醒体故事@塔薇·故事四",
    BaseSortID = 231,
    ActorIndex = 54116,
    Title = "AwakerStory_66036_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_66036_Content|身为智之质体的代行者、守门人，塔薇并非未曾探寻过自己本质的欲望。\n她渴望如她守望的人一般行走于大地，见证文明的变迁与历史的沧桑，将那些目之所及纳入名为「全知」的宝库。但她的存在不容许她擅离职守，所以她内心深处，或许最羡慕的是那名承载了自己一缕意志的少女……",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_66036_UnlockDesc|同调率等级达到9"
  },
  [76415] = {
    ID = 76415,
    CnID = "唤醒体故事@克莱门汀·简介",
    BaseSortID = 232,
    ActorIndex = 77925,
    Title = "AwakerStory_76415_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_76415_Content|每个人都有不同的人格面具，而她选择了最能麻痹人心灵的那一种——\\n\n她温柔地笑着，微笑地说着，每一个表情每一句话都那么熨帖，让前来接受心理咨询的患者，发自内心地认为自己遇到了此生的知己和引路者。\n这样就足够了。\\n\n注定灭亡的飞蛾不需要知道结局，只需要按照她的引导走下去。\\n\n在那看似温暖的救赎里，烈火焚身，再无法回头。\\n",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_76415_UnlockDesc|唤醒体等级达到1级"
  },
  [76412] = {
    ID = 76412,
    CnID = "唤醒体故事@克莱门汀·故事一",
    BaseSortID = 233,
    ActorIndex = 77925,
    Title = "AwakerStory_76412_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_76412_Content|我不相信罗伯特会吞枪自杀。是的，我不相信。\\n\n他获得过见义勇为奖章，破获了多起高难度凶杀案，是个心志坚定的资深探员。最重要的是，他很快就要结婚了，女孩和他两情相悦，所以这里一定有阴谋！有人谋杀了他并伪装成了自杀现场！\\n\n无论凶手是谁，我都会将他找出来，让他付出代价。这是我身为弟弟、身为探员必须要做的事情。\\n\n……\\n\n现场毫无线索，所以我不得不回到了家乡，这是罗伯特自杀前去过的最后一个地方。经过多方打探，我知道他进入了深山。\\n\n至于他进入那里的原因，我猜测和当地的传统有关：每家的第一个孩子，在成人礼时都会被父母带入山脉。\\n\n因为父母在我们小时候就搬离了这里，所以罗伯特并没有实践过这个传统。我想，是即将成家的责任感唤醒了他对传统的依从。\\n\n不管怎么说，我都要去深山一趟。写完这些字后，马上出发。\\n\n……\\n\n山脉里凿出了一个宏伟的建筑，我不知道它属于什么年代，我看不出来。我只知道这里一直在不间断地进行着残忍的仪式，那些残肢还有虫蛹……哕，我无法再写下去了。\\n\n……\\n\n这些虫蛹……不，不，那不是我的祖父母，不是我曾经的长辈……我不可能流着怪物的血脉。啊——\\n\n……\\n\n……我被那些举行仪式的怪物发现了，它们要将我也变成怪物！\\n\n……\\n\n如果看到这篇日记，杀了我，立刻……@2\\n\n……\\n\n赞美伟大的@2，嘶@2……赞美盲目痴愚@4……嘶嘶嘶……@1嘶……\\n\n——节选自已故涉事探员@3的日记，有删减",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_76412_UnlockDesc|同调率等级达到3"
  },
  [76413] = {
    ID = 76413,
    CnID = "唤醒体故事@克莱门汀·故事二",
    BaseSortID = 234,
    ActorIndex = 77925,
    Title = "AwakerStory_76413_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_76413_Content|「谢谢你，克莱门汀，我感觉好多了。你真是这个世界上最了解我的人。」\\n\n出入克莱门汀的心理咨询室时，守密人经常听到这样的声音。无论那些患者和唤醒体进门前如何，出来时都脚步轻快，笑容满面。\\n\n甚至有一次经过时，守密人看到克莱门汀在给误入咨询室的流浪猫做心理咨询。\\n\n结果也显而易见，所有做过心理咨询的人都对克莱门汀赞不绝口，这使得克莱门汀的影响力急速扩散，同时，也带来了麻烦——\\n\n「守密人，中午好。」\\n\n克莱门汀微笑着出现在你的必经之路上，而你并不吃惊，她不断响起的通讯器，已经说明了一切。那些对她信赖有加的患者，潜移默化间成为了她的耳目，或直接或间接地帮助她达成一个个目的。\\n\n「我想，就算你想要当这座城市的市长，那些接受过咨询的患者也会无条件帮你达成。」\\n\n面对守密人的玩笑，克莱门汀不在意地微笑。\\n\n「我对这些不感兴趣。」\\n\n是的，克莱门汀对这些不感兴趣。也幸好她不感兴趣。\\n\n不然那些在心理咨询中倾诉出去的幽暗秘密，足以让这座城市鸡犬不宁。\\n\n「现在，我只想探究你内心深处的秘密，守密人。」\\n",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_76413_UnlockDesc|同调率等级达到5"
  },
  [76416] = {
    ID = 76416,
    CnID = "唤醒体故事@克莱门汀·故事三",
    BaseSortID = 235,
    ActorIndex = 77925,
    Title = "AwakerStory_76416_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_76416_Content|事实上，真正的克莱门汀早在被逝去的伟大意志寄生瞬间就已经死亡。\\n\n从那满是血肉残骸的祭坛上破茧而出的，是拥有伟大本质、远超人类生命的新生者。\\n\n新的生命，旧的记忆。孕育自此星球的躯体，诞生于宇宙深处的灵魂。\\n\n这样充满矛盾的存在，令克莱门汀困惑，但很快，来自灵魂的饥饿让她无法思考。\\n\n人类的食物是如此乏味，只有痛苦的记忆稍能入口。而那记忆越是充满折磨与绝望，品味起来就越是甜蜜和美味。\\n\n那一刻，她终于明白了自己的生存方式。\\n\n「向我倾诉吧，痛苦也好，绝望也好，统统展示给我。」\\n\n她坐在办公桌后，满怀恶意地望着前来咨询的患者，脸上的表情却满是温柔，足以让任何人卸下心防。\\n\n那是昆虫狩猎时的伪装与假面。\\n",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_76416_UnlockDesc|同调率等级达到7"
  },
  [76414] = {
    ID = 76414,
    CnID = "唤醒体故事@克莱门汀·故事四",
    BaseSortID = 236,
    ActorIndex = 77925,
    Title = "AwakerStory_76414_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_76414_Content|起初，一些微不足道的痛苦，就能让她满足。\\n\n然后，对于甘美的渴求，让她在心理引导中加入了越来越多的恶意。\\n\n这恶意犹如河流积蓄奔涌，泛滥成灾，没过一个又一个心灵的岛屿。\\n\n然而还不够。远远不够。\\n\n唯有那亘古的长梦复苏，整个世界才会化为痛苦的汪洋，带来终极的喜悦。\\n\n所以，她兴奋，她祈求，她等待。\\n\n当一切化为混沌时，她将伏低头颅，欣然品味这世间最极致的哀恸。\\n\n哪怕这痛苦的汪洋，会将她也溺毙。\\n",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_76414_UnlockDesc|同调率等级达到9"
  },
  [81615] = {
    ID = 81615,
    CnID = "唤醒体故事@克珀珊特·简介",
    BaseSortID = 237,
    ActorIndex = 77922,
    Title = "AwakerStory_81615_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_81615_Content|她是船只航行时高高飘扬，指引方向的旗帜，也是船只沉没时，坚守职责到最后一刻的挽歌。\\n\n她的责任、她的义务、她的生命都与船只绑定，除此之外，别无他物。\\n\n因为，指引航向，就是她存在的意义。\\n",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_81615_UnlockDesc|唤醒体等级达到1级"
  },
  [81617] = {
    ID = 81617,
    CnID = "唤醒体故事@克珀珊特·故事一",
    BaseSortID = 238,
    ActorIndex = 77922,
    Title = "AwakerStory_81617_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_81617_Content|没有人知道那艘幽灵船在哪，也没有人能确定「它」是否真的存在。目前我所掌握的唯一线索，就是那个似乎有着某种诡异魔力的象牙头雕。\\n\n自从得到它后，我每天都在做同一个梦，是的，就是那艘不知道在哪的幽灵船。「它」的船身燃着如活物般蠕动的辉光，似乎通往凡人不可知维度的门扉，醒来后，我依然记得那些亵渎病态的低喃。\\n\n我多么希望自己疯了，或是忘掉这些古怪的、人类根本无法发出的音节，但不行。\\n\n那该死的梦境、那该死的知性辉光折磨着我，因此我必须去找「它」，在象牙头雕的指引下。幸运的是，密斯卡托尼克的教授们会与我同行，共同探索幽灵船及圣艾尔摩之火——他们是这么称呼那蠕动辉光的。\\n\n祝我幸运。愿主保佑我们。\\n\n——节选自《密斯卡托尼克超自然现象调查档案》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_81617_UnlockDesc|同调率等级达到3"
  },
  [81618] = {
    ID = 81618,
    CnID = "唤醒体故事@克珀珊特·故事二",
    BaseSortID = 239,
    ActorIndex = 77922,
    Title = "AwakerStory_81618_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_81618_Content|克珀珊特的每日行程十分固定，你只需要在特定的时间，去到特定的地点，就能找到她。\\n\n一般而言，克珀珊特6:00就会起床，进行冷水浴与体操。7:00是早餐时间，除燕麦粥、腌鱼外还需提供大量咖啡因补剂。\\n\n9:00-12:00，是克珀珊特的进修时间，她会在此期间修订海图或校准仪器。当下课铃响起时，克珀珊特会来到户外，挥舞旗帜充当交通员，这极大缓解了午饭时学院道路拥堵的问题。\\n\n克珀珊特的午餐时间取决于「路况」，但最晚不会迟于12:30。短暂休息后，14:00时，克珀珊特会准时出现在海边，观察风向与气候。此时需要注意克珀珊特、法洛思、希莱斯特三人的动向，避免她们「征用」博物馆模型船只，或引诱路人出海。\\n\n19:00为晚餐时间，为了麻痹彻底被长期航行摧毁的睡眠周期，克珀珊特需要摄入大量酒精及助眠酊剂，唯有如此，她才能在22:00成功入睡，否则克珀珊特会强制让自己保持清醒，以应对航行中可能出现的「意外」。\\n\n因此导致的情况包括且不限于圣艾尔摩之火现象失控，导致整个区域亮如白昼，或区域电压异常、失控，机器运转异常、失火等。\\n\n<Red:注意，在此期间绝对不要让艾瑞卡与克珀珊特进行接触！>\\n\n最后通知批评一则：\\n\n克珀珊特到来后，温柯尔尝试多次提取、研究克珀珊特胸口的@2，作为光源。已进行口头批评，如有人发现异常，请务必及时告知守密人。\\n\n——守密人%player%",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_81618_UnlockDesc|同调率等级达到5"
  },
  [81616] = {
    ID = 81616,
    CnID = "唤醒体故事@克珀珊特·故事三",
    BaseSortID = 240,
    ActorIndex = 77922,
    Title = "AwakerStory_81616_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_81616_Content|在学会说话前，在游轮上长大的克珀珊特就已经能够模拟海浪拍击船只的音节。\\n\n有时候那音节是「哗啦」，有时候那音节是「轰隆」，犹如大自然为她唱响的安眠曲，令她觉得安心，令她觉得亲切，令她觉得向往。\\n\n她总是能比其他人更快领悟大海的「脾气」，总是能比其他人更快读懂云层的「语言」，所有人都说她是天生的「领航员」。\\n\n实际上，在第一次听到这词汇时，年幼的克珀珊特还无法理解，她只是本能地想要帮助收留自己的船长和水手们，想让他们安全回家，而非折损于风暴或是其他船上的灾难。\\n\n了解她心愿的领航员于是说道：「成为领航员吧，克珀珊特，成为领航员，履行你的职责，那么你的心愿就会实现。」\\n\n懵懂的克珀珊特点了点头，就此，那位领航员成为了她的导师。他教导她如何观测星空、如何校准六分仪，并告诉她领航员们代代相传的歌谣，那不祥的歌谣。\\n\n「我不想被咸水拥入怀里，那太冷了，也不想化为什么磷火。」年幼的克珀珊特提出异议。\\n\n她的导师并没有教导她什么，只是摸着她的头，笑了笑。\\n\n因为时间，会教导她明白「领航员」职责的意义——\\n\n她是幽邃大海上，唯一的指引，唯一的希望。\\n",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_81616_UnlockDesc|同调率等级达到7"
  },
  [81619] = {
    ID = 81619,
    CnID = "唤醒体故事@克珀珊特·故事四",
    BaseSortID = 241,
    ActorIndex = 77922,
    Title = "AwakerStory_81619_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_81619_Content|直到最后一刻，克珀珊特都在努力履行自己的职责，但她领航的船只，仍旧沉没了。\\n\n每到夜深人静时，她就会梦到那些逝去的乘客：海水灌入船舱，海怪触腕横行，有人淹死，有人跳海，有人跪下来祈求最后的指引，却仍是希望破灭。\\n\n这残酷的现实在责备着她，折磨着她——她亵渎了自己的职业。\\n\n为此，她必须受到惩罚，那终生缠绕她、摧残她的雷电，就是惩戒。但还不够，她必须为自己的渎职赎罪。\\n\n幸运的是，那伟大的存在给予了答案：只要神国降临，世间一切都将变为乐土。\\n\n「那么，为了平息大海永恒无尽的咆哮，为了那些葬于大海的无辜者，为了指引众生的方向，我请求神国的降临。」\\n\n这是她最后的，最终的领航。\\n",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_81619_UnlockDesc|同调率等级达到9"
  },
  [81335] = {
    ID = 81335,
    CnID = "唤醒体故事@卡斯托尔·简介",
    BaseSortID = 242,
    ActorIndex = 77923,
    Title = "AwakerStory_81335_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_81335_Content|如果诞生于一个普通的家庭，卡斯托尔或许会成长为一个不善言辞，但如树木般亲切又踏实的青年。而现在，他是双子之中唯一保持了完整的身躯与灵魂之人，他像一块石头一样沉默着，等候着，将那颗少年时两人共同的火种埋藏在心中，不曾放弃，不曾转圜。\n那双已然成熟的、能刮起飓风的双翼收敛蛰伏，一只鸟儿静静等待着那笼门开启，再次翱翔于天空的时刻。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_81335_UnlockDesc|唤醒体等级达到1级"
  },
  [81336] = {
    ID = 81336,
    CnID = "唤醒体故事@卡斯托尔·故事一",
    BaseSortID = 243,
    ActorIndex = 77923,
    Title = "AwakerStory_81336_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_81336_Content|我在距离伦蒂尼恩十分遥远的、那片因贫瘠而鲜为人知的高原上执行任务时，正巧在一处仅剩下为数不多居民的山村中，发现了这样一则惊人的事迹。\n在那个怪物出现的夜晚，天空似乎都被某种怪异的暗影所遮蔽，雾气滚动在地面，而云层深处泛起一种黯淡的绿色，那绝不是单纯的自然现象，而是一种活着的、呼吸着的生命的投影。\n耸立着高树的荒芜山脉深处，突然传来一阵怒吼、咆哮般的声波，那不属于任何生物的啸叫声能勾起人们本能最深处的恐惧。\n一道庞大的阴影迅疾地飞过，整座山都随着那遮天蔽日的阴影一起震颤，所有树木的枝叶也随之一起震颤，发出整齐的呢喃般的簌簌声响。\n「我看见了！那些长长的、密密麻麻的触手，那双冒着绿光的眼睛，那绝对就是天上那恐怖影子的源头。它发现了我，甚至牢牢盯住了我！我真以为我的生命就要终结在那一刻，但或许是它刚刚已经饱餐一顿，在我因窒息而晕过去之前，它便大发慈悲地转身离开了。」\n这是对正式目击者仅有的采访，至今仍深陷噩梦之中的村民拒绝回忆更多的细节。但从已有的迹象观察，这个庞大的暗绿色怪物除了如飓风过境一般摧毁了部分山林、留下几具仅余血丝的野兽骸骨外，并没有表现出更大的攻击性，就像一头正常进食的猛兽一般。或许它靠近村落的行为，仅仅是来自于某种好奇的窥视。\n但面对任何未知的恐怖，我们显然需要予以最坏的设想，我将继续在@3高原进行为期半个月的调查，如果有其他值得注意的危险迹象，我会随时补充于任务汇报之中。\n\n——节选自《弥萨格境外调查笔记A.F.3@2年总录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_81336_UnlockDesc|同调率等级达到3"
  },
  [81334] = {
    ID = 81334,
    CnID = "唤醒体故事@卡斯托尔·故事二",
    BaseSortID = 244,
    ActorIndex = 77923,
    Title = "AwakerStory_81334_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_81334_Content|与卡斯托尔相处的感受通常呈现两种诡异的极端。\n表面上看，那过于正经而稳重的性格十分像是在伦蒂尼恩银行坐班了二十年的中年职员：一板一眼、不解风情，被枯燥的工作吸干了所有活力。当他板起脸时，也的确有一种不怒自威的圣子气质。\n而只要稍微深入接触，就会发现他那些看似古板的行为通通来自他那过于稀少的常识，和无与伦比的粗神经与耿直，乃至于会把任何人对他说的玩笑都完全当真。\n他时常会拿着一本厚厚的笔记，抓着守密人不停地刨根问底，活像一个仍在牙牙学语的婴儿，在面对那道过于真挚而诚恳的目光时，大多数人也很难对这些无知的问题说出什么鄙薄之语。\n除了与各类信仰有关的经文之外，卡斯托尔对任何新鲜的知识都求知若渴，尤其是关于现代社会与现代科学的种种，他甚至对实验研究产生了浓厚的兴趣，在被熔毁·朵尔无情忽视后，转而又将可怜的温柯尔纠缠得每日闻风而逃。\n如果坐在学校课堂中，他会是那类深受老师喜爱的勤奋学生，他并不认为学习是一件苦累的事，而是将能够自由地汲取感兴趣的知识当作一种由衷的幸福。\n不过比起教师的欣慰来说，某些喜爱吹嘘的唤醒体在面对这样富有逻辑的无穷追问时，反而会因为答不出后续而恼羞成怒起来，只留下一头雾水的卡斯托尔感慨学习的深奥艰辛、前路漫漫。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_81334_UnlockDesc|同调率等级达到5"
  },
  [81337] = {
    ID = 81337,
    CnID = "唤醒体故事@卡斯托尔·故事三",
    BaseSortID = 245,
    ActorIndex = 77923,
    Title = "AwakerStory_81337_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_81337_Content|追寻自由、逃离教会的代价是什么？双子预想过恐怖的刑罚、甚至预想过会失去自己的生命，但他们没想到的是，最令人痛苦的从来不是肉体上的折磨，而是针对灵魂的剐刑。\n卡斯托尔目眦欲裂地看着波吕克斯那对他倍加珍惜的、灵动而华美的翅膀被生生扯下时，嘴唇已被自己的牙齿生生咬烂，他发狂而愧疚地等待着，甚至渴望着同样的痛苦降临在自己身上。\n然而于丽埃特只是挥了挥手，如残破布袋一样重伤的卡斯托尔就这样完整地被带了下去，扔进了充满融蚀浆的水池中施行「罪孽疗法」。\n黑色的黏浆浸泡着受伤的躯体，渗入每一处伤口，覆盖每一片羽毛，令卡斯托尔愈加难以呼吸。\n于伤口反复地腐蚀又痊愈中，卡斯托尔恍惚的脑海里盘旋着那双被拔掉的翅膀，他在狭小的囚笼中焦躁地枯坐，恨不得替弟弟承受所有的折磨。他多么想当日被拔掉翅膀的人是自己，后来他又坚定地想，自己一定要靠这双翅膀带弟弟再次飞向自由。\n卡斯托尔在这地狱般的潭水中支撑了一日又一日，痛苦之中时间已无法被准确感知。像是等待了数十年那样久，等到卡斯托尔几乎死上一次，从那漆黑的地狱中再次爬出时，与他急切的双眼相对的，是一道冰冷而不屑的目光。\n「收起你那恶心的眼神，另外奉劝你一句，卡斯托尔阁下，你我不过是共同侍奉持灯者的圣子，人后无事之时，就不必太过亲昵了，令人徒增厌烦。」\n卡斯托尔不知道为什么弟弟将自己完全忘记了，但他终于明白了离开罪潭时，于丽埃特那样意味深长的眼神究竟是什么含义——只因她已将最能够控制自己的项圈牢牢牵在了手中，有恃无恐。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_81337_UnlockDesc|同调率等级达到7"
  },
  [81338] = {
    ID = 81338,
    CnID = "唤醒体故事@卡斯托尔·故事四",
    BaseSortID = 246,
    ActorIndex = 77923,
    Title = "AwakerStory_81338_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_81338_Content|双子生来便除了彼此一无所有，而卡斯托尔仍然一直在品尝着失去的滋味。\n被伤害、被遗忘、被背叛，那颗沉默的心并非铁石，但他仍然不断地爬起。\n「但没关系，我会将你的那一份一起坚持下去。」卡斯托尔看着面目全非的弟弟，盲目地相信着。\n他的心中紧紧攥着那朵微弱的火苗，不停逆着刀割般的风雪跋涉。\n总有一天，他要攀登上那自由的山顶，要用翅膀去触碰天空低垂的帷幕。\n他相信那条荆棘之路的尽头，一定是儿时弟弟许诺过的，明亮的天光。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_81338_UnlockDesc|同调率等级达到9"
  },
  [95009] = {
    ID = 95009,
    CnID = "唤醒体故事@凯蒂古拉·简介",
    BaseSortID = 247,
    ActorIndex = 77913,
    Title = "AwakerStory_95009_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_95009_Content|凯蒂古拉擅长用她标志性的笑容，令所有注视者从意识的最深处，渗出那股透着残忍、疯狂的寒意。\n那两杆形影不离的双枪，则用缭绕在枪管的火药尘粉，警示所有妄念痴心的宵小之徒，无名者的牺牲是一切伟大的基石。\n不过但凡跟她打过交道，你就会明白，狩猎这些平凡的不被阳光照耀的人，不过是她日常无聊时的消遣。\n毕竟当她真正开火的时候，枪口是没有火药的。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_95009_UnlockDesc|唤醒体等级达到1级"
  },
  [95007] = {
    ID = 95007,
    CnID = "唤醒体故事@凯蒂古拉·故事一",
    BaseSortID = 248,
    ActorIndex = 77913,
    Title = "AwakerStory_95007_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_95007_Content|■档案编号：DIOL-A3-1\n■唤醒体代号：■■■■\nA.F.3@2年，该唤醒体主动与弥萨格进行接触。\n\n「太阳！太阳！我看到了太阳！不！不！！摧毁它！不然我们都要死！」\n\n据目击者描述，当事人员在发现该唤醒体后，大喊着说出了上述发言，之后命令相关部队对其进行攻击。\n\n由于当事人员的错误判断，该唤醒体展示出了极强的攻击性，直接导致31组反唤醒体器材，76组常规装备，2栋教学楼遭到摧毁，合计财产损失@2@4，当前已移交至相关部门进行对应追责。\n\n经事后调查发现，该人员已被提灯教会洗脑，后续情况请移至相关文件查看，不在本档案进行叙述。\n\n在一段时间的交流后，谈判人员成功令该唤醒体解除了攻击姿态，随后该唤醒体将一封署名为德克斯特勋爵的信件交予校方，声称是某位失踪调查员的遗物，后续经德克斯特勋爵确认，该信件确实为其所写。\n\n目前已知经朵尔教授的协商，该唤醒体与校方达成了某种协议，校方以某种尚不明确的报酬为代价，换取该唤醒体承接某些校方不好或不便处理的委托。\n\n出于对该唤醒体所展现的破坏力的考量，尽管该唤醒体在之后的谈话中具有最高等级的稳定性及可交流性，委员会依旧决定将其列入DIOL中，并将以最高规格持续进行档案更新。\n\n愿银钥指引我们。\n\n记录员 L·纳迪亚",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_95007_UnlockDesc|同调率等级达到3"
  },
  [95010] = {
    ID = 95010,
    CnID = "唤醒体故事@凯蒂古拉·故事二",
    BaseSortID = 249,
    ActorIndex = 77913,
    Title = "AwakerStory_95010_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_95010_Content|■档案编号：DIOL-A3-9\n■唤醒体代号：■■■■\n\n根据持续的观察发现，该唤醒体并未对弥萨格表现出异常关注，甚至可以说兴趣缺缺，她只有在接受委托时会来到校内，然后快速地离去。\n虽然回传的调查报告显示，该唤醒体确实存在数次长时间于校园内逗留的记录。 \n\n但根据后续调查，其主要逗留原因是帮助学生解决一些问题，经判断不存在安全隐患，无需进行干涉。\n\n需要注意的一点是，该唤醒体似乎对守密人拥有远超他人的兴趣，曾多次给守密人带来被列为违禁品的@3物件，并邀请守密人参加各种与会人员不明的晚宴。考虑到守密人对弥萨格的重要程度，如果该唤醒体企图对守密人采取某种具有危险性的行动，需安排至少4名γ级武装人员，来确保守密人可以安全撤离。\n\n记录人 K·特拉克\n\n（写在档案背面的小字）\n嘿，兄弟，当然也可能是姐妹，这不重要。\n上一个倒霉蛋已经撂担子不干了，现在是我来负责这个该死的项目。\n如果你看到这个，说明你不是那种只会混吃等死的家伙，而是一个善于观察的人，你应该为你自己鼓个掌。\n听着，虽然我们一直说我们在「暗中监控」，但我感觉她早就发现我们了，只是不愿意搭理罢了。\n我不明白为什么我们要监控这样一个人，虽然跟她的第一次接触存在些许误会，但那本就是邪教徒所致，跟她本人不存在任何关系。\n况且她跟那些学生，尤其是守密人之间，用比喻形容的话，就是祖母给孩子买糖果的关系！总不能有人天天觉得自己祖母要把他献祭给邪教徒吧……不，等等，或许在某个地方还真的是这样，不过这不重要！\n重要的是，如果她真的有所图谋，我保证，事情已经在不知不觉中发生了，而不是等到委员会慢慢悠悠地研究出来那个******对策。\n呼，骂的好爽，总之，我已经计划将她从这个名单中移出去，在委员会真的做出什么对她而言不可原谅的事之前。\n一旦那帮**真的把她惹毛了，我保证，就不会是2栋楼那么简单了，希望到时候我已经死了，不然我应该会死得非常痛苦。\n如果你是即将监视她的人，记住，不要做什么过激的举动，如果你不喜欢她，就将她当做给学校处理脏活的佣兵就行了，除非对方明确表现出了不稳定状态，否则绝对不要跟她起正面冲突！\n当然如果你想要点小礼品……她应该也不会在意你曾经监视过她，大胆去要就行了，说实话，她口袋里的小零食真的蛮好吃的。\n——卡拉波利斯·特拉克，你一起辱骂委员会的好朋友。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_95010_UnlockDesc|同调率等级达到5"
  },
  [95006] = {
    ID = 95006,
    CnID = "唤醒体故事@凯蒂古拉·故事三",
    BaseSortID = 250,
    ActorIndex = 77913,
    Title = "AwakerStory_95006_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_95006_Content|■档案编号：DIOL-A3-27\n■唤醒体代号：■■■■\n\n根据该唤醒体（下文称为凯蒂古拉）的行为习惯、处事风格及对不同任务的态度，调查人员进行了相关推测，并在之后详细展开了调查，现在同步以下内容：\n凯蒂古拉是一名@2地区的孤儿，其父母于其幼年时期便将其抛弃。\n凯蒂古拉依靠未知的手段在该地区存活了下来，同时收留了许多境遇悲惨的孩童。需要注意的是，该过程中充斥着大量血腥、暴力的手段。在明确记录中，调查对象曾残忍地杀害了某位收留对象的所有家庭成员。\n在后续的很长时间内，凯蒂古拉及其手下的主要经济来源是承接不可告人的委托，如黑帮仇杀、帮派火拼、劫掠脏物等黑吃黑行为。\n据当地人的口述，同时结合该地区的一些数据，初步推断出存在某个时间点，以凯蒂古拉和其收留的孩童为核心的团体，成功整合了该区域绝大部分黑色组织。\n目前暂时无法得知凯蒂古拉是如何成为唤醒体的，但该地区提灯教会据点遭受摧毁的时间，与其成为唤醒体的推测时间相符。根据其对提灯教会的厌恶感，合理推断其成为唤醒体与提灯教会有所关联。\n据不完全统计，截至目前，已有43个提灯教会的据点遭到其摧毁，其中包括7个大型据点，12个降神祭坛以及17个实验场所。\n\n参考上述调查报告及该唤醒体的日常活动行为，委员会在荣誉主席K·特拉克的提议下，对凯蒂古拉的危害评级进行重新评估，现记录评估结果：\n经全体委员判断，该唤醒体对弥萨格不存在直接或间接的威胁，在现有合作条约不变的情况下，无需对其存在及行为进行干涉。\n因此，现决定将凯蒂古拉移出DIOL，同时冻结与其相关的一切调查行动，所有档案内容进行完全封存，禁止任何Ω级别以下的人员进行查看。\n\n记录员 K·特拉克\n（写在档案底部的小字）\n可喜可贺！终于让那帮草木皆兵的小子把这该死的项目取消了，不枉我浪费这么长时间推动这些事。\n这就是有关凯蒂古拉女士的最后记录了，后续不出意外，不会有新的档案填充进这个编号下了。所以无论是谁，现在可以合上这该死的文件夹，出门呼吸一下新鲜的空气，将精力放在更值得关注的对象上了！\n——卡拉波利斯·特拉克，你那变成社会闲散人员的好朋友。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_95006_UnlockDesc|同调率等级达到7"
  },
  [95008] = {
    ID = 95008,
    CnID = "唤醒体故事@凯蒂古拉·故事四",
    BaseSortID = 251,
    ActorIndex = 77913,
    Title = "AwakerStory_95008_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_95008_Content|（写在档案开头的小字）\n该死，你是怎么找到这份档案的，我明明已经禁止了任何人查阅这东西……算了，既然您能看到这份档案，说明您的权限远在我之上，这代表您是那几位之一，我自然无权阻止您知晓这些事情。\n\n但是请您牢记，这份档案理应不该存在于任何地方，下述内容也并非任何正式调查，而是个人基于某些现实情况，进行二次推论构成的非官方产物。\n\n我必须郑重地提醒您，这份档案的记录过程中包含大量无法详细描述的调查方法、个人思维的主观臆断以及收受调查对象贿赂的行为。如果您不在意我的上述行为，请继续往下阅读，我以我的人格担保，下述内容具有明确的真实性。\n\n■档案编号：■■■■-A■■-SSS\n■唤醒体代号：爆燃之主\n「我其实并不喜欢争斗。」\n我很意外会得到这样一个答案，毕竟所有报告中，调查人员都会在描述她战斗时，加入诸如「疯狂」「欢悦」「兴奋」等字眼。\n我本以为她对于战斗的看法是「不主动，不厌恶，不拒绝」，万万没想到她会对这种事情本身感到厌恶。\n随着谈话的继续深入，我渐渐明白了一些事情，当我询问是否能记下这些内容时，凯蒂古拉大方地肯许了我的行为。\n\n「你要知道，对于世界上的大部分人来说，活着就是一种奢侈。」\n我对这个说法表示认同，虽然我以及接触到的大部分人都过着优越的生活，我甚至可以随时前往伦蒂尼恩最大的歌剧院欣赏表演，但我清楚地知晓这个世界的真实样貌，以及我优越的生活背后有多少人在负重前行。\n\n「因此，在许多时候，强烈的斗争欲是你为了活下去所支付的报酬。」\n「我们没有办法选择生活的方式，你一旦踏入过泥泞，再想抽身就几乎不可能了。」\n我本想反驳这个观点，但当我仔细回想了几个案例后，发现他们都可谓不是一般人，而那些无名小卒，大多数只会存在于他们的回忆录里。\n「或许有些天真的人会说既然这样，那一开始就不要去做不就好了么？这种想法很好，我曾经把它刻在了某个坟墓上，来纪念一位贯彻落实了这条准则的人。」\n「为了在这个残忍的世界中保护大家，我必须展现得足够强大，疯狂，这样才能让那些无处不在的恶意有所忌惮。」\n「当然，我在战斗中表现得那些情绪并非虚假，我确实在享受战斗带给我的感觉。」\n「可能有些难以理解，但这就像你可能会喜欢你的工作内容，却不会喜欢工作本身一样。」\n听到这个解释之后，我立刻理解了她话中之意。确实，我很喜欢在工作中窥探别人的隐私来满足我那罪恶的好奇心，但这不代表我喜欢每天早上八点必须从床上爬起来，听从命令前往某个地方待上一整天。\n\n「在我刚被遗弃的时候，我跟很多女孩一样，迷茫，踌躇，不知所措。」\n「我希望得到他人的帮助，但世界给予我的，只有数之不尽的背叛和伤痛。」\n「渐渐地，我开始用残忍和疯狂构造抵御恶意的盔甲，饮鸩止渴般适应着世界的一切。」\n「直到最后，它们在永不停息的火焰中融化，与我的血肉合为一体。」\n像是为了印证刚才的发言一样，凯蒂古拉瞬间露出一个极度残忍、邪恶、疯狂的笑容，吓得我将杯中淡黄色的液体撒在了身上。\n哦，或许这是好事，因为这样可以避免万一我真的控制不住肌肉导致漏出了某些液体，可以很自然地解释成是刚才洒在身上的饮料。\n在离开的最后，凯蒂古拉都没有正面回答我的问题，但我想，我之前的判断是正确的，她确实不该存在于DIOL中。\n——记录员 卡拉波利斯·特拉克\n\n「我最初的愿望，只是想拥有一个家。」\n「一个没有背叛，没有痛苦，充满欢声笑语的家。」\n「可惜，直到那一天我才明白。」\n「这是这个残酷的世界中，最奢侈的妄想。」\n——凯蒂古拉",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_95008_UnlockDesc|同调率等级达到9"
  },
  [95097] = {
    ID = 95097,
    CnID = "唤醒体故事@波吕克斯·简介",
    BaseSortID = 252,
    ActorIndex = 77917,
    Title = "AwakerStory_95097_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_95097_Content|他是畸生而出的血肉，由剖开又缝补的肌肤、空洞的胸腔、污浊的心脏与无形的锁链构成。\n他被捧上高台，人们膜拜在他的脚下，声称他拥有无垢的灵魂。\n他究竟是什么？他在无数梦中茫然发问，那暗绿的湖水与空无一物的浓雾中，只有他的声音孤独回响。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_95097_UnlockDesc|唤醒体等级达到1级"
  },
  [95095] = {
    ID = 95095,
    CnID = "唤醒体故事@波吕克斯·故事一",
    BaseSortID = 253,
    ActorIndex = 77917,
    Title = "AwakerStory_95095_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_95095_Content|基于对波吕克斯那颗「圣心」与提灯教会的降神仪式之间可能存在的关系的考量，弥萨格曾组建了研究小组对「圣心」进行了一系列检查与实验。\n令波吕克斯遗憾的是，这颗「圣心」已经完全替代了他原本心脏的机能，融入了他的身体之中，无法直接摘除或替换。\n在观察实验中，研究人员发现这颗外形酷似眼瞳的「圣心」时常会产生非波吕克斯意志下的轻微抖动与转动，如同一只真正的眼睛。\n但经过光源测试后，证明「圣心」不存在类似视力的功能，这种活动更像是源于对其他生物或物品的感应。\n在不同放置物品的对照中，与融蚀、银芯相关物品的靠近更容易引起「圣心」的活动，在被融蚀生物与唤醒体面前，「圣心」的活动则尤为明显。\n在波吕克斯主动使用「圣心」的力量后，普通物品的物理及化学性质不会有任何改变，而在融蚀物品、生物面前，则出现了速度惊人的融蚀扩大现象。原本位于融蚀阶段早期的动植物肉眼可见地加速度过了发展阶段，快速转向融蚀末期的状态。当动植物原本受到的融蚀越严重，这样的扩散则越迅速。\n在建立了严格保护措施的唤醒体实验中，当面对「圣心」的力量时，唤醒体表示感受到有某种黑暗逼近的危险气息，实验因而被迅速叫停。波吕克斯也在校方的严正说明下，保证不会将圣心的力量对唤醒体使用。\n由于波吕克斯极其配合的态度和良好的自控力，弥萨格并未给波吕克斯佩戴强制管制道具，只是定期给波吕克斯安排了体检与力量使用训练。\n据说在听闻了实验结果后，唤醒体温柯尔曾尖叫着险些晕倒，并在自己的实验室和宿舍门上张贴了禁止波吕克斯靠近的告示，校方屡次劝说无果，波吕克斯本人对此则大度地表示会尊重温柯尔的要求。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_95095_UnlockDesc|同调率等级达到3"
  },
  [95098] = {
    ID = 95098,
    CnID = "唤醒体故事@波吕克斯·故事二",
    BaseSortID = 254,
    ActorIndex = 77917,
    Title = "AwakerStory_95098_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_95098_Content|比起卡斯托尔那样积极好学的态度，波吕克斯接触外界的风格则更加谨慎。\n观察、思考、怀疑，足够的思虑与小心让曾经的他能够在教会的重重控制下，带着卡斯托尔成功出逃。\n从儿时起，他便学会了揣度他人的想法，学会了撒谎，学会了用笑容遮掩真实的想法。哪怕是在亲密无间的哥哥面前，他仍会下意识地用轻松的笑容去安抚对方。\n「没关系的。」\n「一定可以的。」\n在那样庞然大物的手掌之下，弱小者需要拼尽全力才能寻到一丝可能的希望。\n经历了漫长的遗忘与欺骗后，如今的他更加不允许任何危险与失误的存在。哪怕听从泰旖丝的建议来到弥萨格后，在很长的一段时间里，他都保持了相当的警惕。\n在其他唤醒体看来，波吕克斯是一个话不多，却很有耐心，常常会对人露出微笑的友善家伙。但那些久经世故的年长者看到他后，则都纷纷感叹两兄弟之间的不同。\n据泰旖丝说，哪怕是在她的面前，波吕克斯也会有意无意地将卡斯托尔挡在身后——从他找回记忆以来，他已经不再愿意让卡斯托尔总是保护着他。\n詹金也曾煞有介事地向守密人告状波吕克斯的表里不一，声称自己不小心捡到卡斯托尔的东西时，曾看到波吕克斯骤然阴沉的面孔。「那个家伙平时的好脾气肯定都是装的！他私下里就是那种会吃小孩的变态！」\n然而在直面了守密人的力量后，波吕克斯对待守密人的态度就发生了一百八十度的转变，在「圣心」的剧烈反应下，他声称已从那伟大的灵魂中获悉了世界的真相，并毕恭毕敬地将守密人奉为了新的信仰。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_95098_UnlockDesc|同调率等级达到5"
  },
  [95096] = {
    ID = 95096,
    CnID = "唤醒体故事@波吕克斯·故事三",
    BaseSortID = 255,
    ActorIndex = 77917,
    Title = "AwakerStory_95096_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_95096_Content|在命运之神最初的设想里，他大概不应诞生于世。\n一开始从人造双子实验中诞生的只有卡斯托尔一人，就在这团无知无觉的胚胎要被处理丢弃时，波吕克斯挣扎着，从哥哥的血肉中扭曲撕裂而生。他吸食了他的生命，也拯救了他的生命，他们的血肉、灵魂与命运就此交缠。\n于枯燥的教会修行之中，两人的生活与命运原本别无二致，直到「神圣改造」仪式的开始，痛苦且无情的折磨让波吕克斯从圣子的宿命中惊醒。两个孩子做出了一生中最大胆的壮举，他们拿着一本过时的书籍描摹出了一幅世界的地图，然后从一个虚假的世界中逃向了另一个幻想中的世界。\n脆弱而短暂的美梦破碎后，残酷的惩罚未曾击垮他们的灵魂，但那宿命的残酷分叉已经将他们就此分隔了。\n于丽埃特下令将两人分开供养，罪潭中的卡斯托尔不知道的是，两人想象中的酷刑并没有实施在波吕克斯身上，于丽埃特几近仁慈地结束了剩余的惩罚，甚至很快将波吕克斯从禁闭的暗室中放出，转而投入了密集严苛的神学教导。\n波吕克斯满腹的不屈与疑惑在面对于丽埃特绝对从容的目光时，变成了某种不安与恐惧，她一定是掌握了某种他无力反抗的办法，才会如此好整以暇。\n他挣扎、伪装、从未放弃。他好像做了许多事……但他做了什么呢？镜子中只剩下一个陌生的灵魂，忠诚地戴上了那顶圣子的冠冕。\n他与他们的记忆，已经被彻底遗忘了。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_95096_UnlockDesc|同调率等级达到7"
  },
  [95094] = {
    ID = 95094,
    CnID = "唤醒体故事@波吕克斯·故事四",
    BaseSortID = 256,
    ActorIndex = 77917,
    Title = "AwakerStory_95094_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_95094_Content|他的一生都活在被操纵的丝线下，那早早写好的剧本是一场可笑的谎言，令他不停失去、遗忘、错过。\n在年少时他最渴望的是能够自由地挥舞翅膀，飞到那片湖水之外的世界去看看。\n直到他为这个愿望失去了一切后，他已无法将那样轻盈的、无忧无虑的生活当做全部的梦想。\n无尽的怒火将那颗漆黑的心脏点燃，他郁结成血的痛苦与仇恨，要用那些伪信者的死亡才能洗刷偿还。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_95094_UnlockDesc|同调率等级达到9"
  },
  [96418] = {
    ID = 96418,
    CnID = "唤醒体故事@杜勒赛因·简介",
    BaseSortID = 257,
    ActorIndex = 95786,
    Title = "AwakerStory_96418_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_96418_Content|葬骸城的奠基者，食尸鬼永恒的王。\n他的宴会值得最深切的期待——华丽的餐厅，优雅的舞步，还有那些他亲手用尸骸制成的雅致餐品，一定会令你永生难忘。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_96418_UnlockDesc|唤醒体等级达到1级"
  },
  [96421] = {
    ID = 96421,
    CnID = "唤醒体故事@杜勒赛因·故事一",
    BaseSortID = 258,
    ActorIndex = 95786,
    Title = "AwakerStory_96421_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_96421_Content|伦敦郡西北部的艾瑟灵顿废弃墓园自A.F.3@2年起便被本地居民列为绝对禁区。根据《泰晤士报》存档报道及苏格兰场失踪人口卷宗显示，近年来已有37人在墓园夜间的浓雾中失踪，其中包括：盗掘贵族坟墓的惯犯西里尔、避寒的流浪汉库克、巡逻时误入的警员格雷森、研究中世纪丧葬文化的牛津学者怀特等等。目击者证词均指出，所有失踪者都在雾浓度达3级时进入墓园，最终在雾中失去踪迹，搜救队从未发现任何遗留物。\n密斯底亚协定审查会在A.F.3@2年前始终将该区域列为低优先级观察对象，但随着德文郡公爵塞缪尔·寇松（以资助超自然研究闻名）的失踪，审查会收到来自王室的直接质询，最终针对墓园启动专项行动。\nA.F.3@2年7月，由审查会第七行动组组长伊莱亚斯·索恩带队，配备12名武装探员及3名灵媒，携带抗失温药剂与方向定位仪等银芯设备进入墓园。团队在浓雾中维持队形行进1.2公里后，于墓园西北角的残破食尸鬼雕像下发现隐蔽的六边形入口。\n索恩团队沿阶梯下行，经超过五千级阶梯，抵达地底神殿正厅时，现场情况与预设的 「尸骸堆积」 的形象完全不符。\n神殿实测面积约800平方米，地面平整度误差不超过3毫米，空气中未检测到任何尘埃颗粒。空间内无任何装饰性结构，仅中央矗立一座高2.3米的花岗岩祭坛，祭坛表面雕刻着连续的荆棘花纹。祭坛周围萦绕着稳定浓度的黑雾，黑雾核心处可见人形轮廓。\n祭坛顶部的塞缪尔·寇松公爵呈跪姿，衣物完整但已失去生命体征，尸检显示无外伤。在索恩团队突破黑雾外围屏障时，公爵尸体在黑雾中分解为分子级微粒，质谱仪未捕捉到任何残留信号。\n在分解完公爵的身体后，黑雾突然扩张并覆盖整个调查团队。根据成员事后陈述，全员在失去意识前，均曾清晰地听到一句来自男性的、优雅、温和、如同耳语般的话，内容为：\n「请不要探寻葬骸城。请不要打扰食尸鬼之王的用餐。」\n「这是最后一次敬告。」\n当团队恢复意识时，已位于墓园正门的锈铁栅栏外，所有设备均正常运作，但记录神殿内部的影像资料全部损坏。\n后续记录显示，审查会主席与密斯卡托尼克大学神秘学系主任曾造访墓园。此后，官方再未组织任何形式的勘探行动，而根据后续的监测数据，墓园浓雾仅在闯入者意图明确时才会触发攻击性反应，对无意误入者仅造成短暂方向混淆。\n至此，墓园与这座城市相安而存，只剩那些野心暗流涌动，只剩那些传说口口相传。\n\n——《艾瑟灵顿废弃墓园事件调查报告》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_96421_UnlockDesc|同调率等级达到3"
  },
  [96419] = {
    ID = 96419,
    CnID = "唤醒体故事@杜勒赛因·故事二",
    BaseSortID = 259,
    ActorIndex = 95786,
    Title = "AwakerStory_96419_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_96419_Content|离开葬骸城之后，杜勒赛因在人类社会中表现出了极强的适应性。这是一种必然，人类社会对他来说不是新的开始，而是一种回归。\n谈吐，举止，气度，礼仪……杜勒赛因的一切都无可挑剔，既保留着一名君主应有的气场，又丝毫没有长期身居高位的傲慢。\n杜勒赛因并不排斥社交，但他对政治、经济、学术之类的话题兴致缺缺，吸引他去到这些场合的理由只有一个——美食。\n除了品鉴之外，杜勒赛因也热衷于参与厨房相关的工作。从食材的选择到处理手法，从香料的使用到火候控制，杜勒赛因在美食方面的渊博知识与优秀品味征服了每一个与之交谈的人，他们发现，在这之前自己数十年的用餐都只是在囫囵求生，与一个为生存而进食的动物没有任何区别。即便是天生没有味觉的可怜虫，也能在他的描述里体验到美食的艺术，获得味觉上的新生。\n这当然和杜勒赛因的礼节有关，他清楚地知道人类与食尸鬼在食物品味上的差别。杜勒赛因尊重不同物种之间的差别，无意将自己的品味强加于所有人。\n「总有人喜欢将不同视为异端，在我的城邦里，这是非常不优雅的行为。我尊重人与人之间的差异。在这种差异中，我们才能看到更多关于食物之美的可能性。」\n「但你不同，守密人。作为这个世上如此特殊的存在……我想，你一定能像我一样，在这样的进食里，体验到无与伦比的美……」\n说这句话的时候，杜勒赛因的微笑在紫色的雾气中闪烁，像是一条优雅的毒蛇在你耳边嘶语，等待着将你带出、或者诱入伊甸园的那一天。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_96419_UnlockDesc|同调率等级达到5"
  },
  [96420] = {
    ID = 96420,
    CnID = "唤醒体故事@杜勒赛因·故事三",
    BaseSortID = 260,
    ActorIndex = 95786,
    Title = "AwakerStory_96420_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_96420_Content|从葬骸城黑暗的祭祀神殿中醒来时，剧烈的疼痛正席卷杜勒赛因全身。\n剧毒的效果尚未消退，刀绞般的疼痛如同一株带刺的藤蔓，从他的腹部开始生长，占满身体的每一个角落。他曾想过父亲会毒害自己，但他依然接过了父亲递来的那杯酒。\n聪慧，正直，英勇……在很早以前，杜勒赛因就具备了作为一位贤王的所有美德。从那个苍老的、闪烁的眼神里，他轻易便洞穿了父亲与他身后势力的想法，但他依然微笑着接过了父亲递来的毒酒，一饮而尽。\n在一个人类的城邦里，食尸是一桩不可饶恕的恶行。杜勒赛因曾经无数次尝试过向他们解释，解释尸体的味道，解释死灵的美。人与人之间永远无法相互理解，即便是至亲也一样，这是杜勒赛因学到的最后一件事。\n他没有想过自己会重新醒来。在剧毒之外，他感到另一种疼痛。黑色的雾气覆盖在他的身上，如同无数个食肉的爬虫，正啃噬他的躯体。一颗颗利齿刺破他的肌肤，一把把利刃剜去他的血肉。黑雾正在撕咬他。黑雾正在重塑他。他的躯体不断重生，又不断被啃噬。杜勒赛因张开嘴，在这空无一人的神殿中无声哀嚎。\n在那漫长的、极致的痛苦中，黑雾窜入杜勒赛因体内，与他的精神交融。当黑雾与他的精神世界连通的那一刻，杜勒赛因的味蕾中出现了一丝他从未品尝过的味道。剧毒，凌迟……所有的痛苦在那一刻消失，他的世界只剩下那一丝无上的美味。他兴奋地追寻着它，找到了它的来源——那是葬骸城的神明正在品尝的味道。那是他自己尸体的味道。\n在这可怖的折磨中，葬骸城的神明正与他融为一体。他们的肉体与精神相连，他们在彼此的痛苦与欢愉里哀嚎、欢笑。\n这场进食持续了一整个星期。在这场漫长的进食结束后，杜勒赛因重新从祭坛上升起。没有仇恨，更没有懊悔。他理解并感激那些杀害他的人们，在这场谋杀里，他品尝到了此生最极致的美味，获得了此生最极致的欢愉。\n满月升起，葬骸城在那一天安静垂首，迎接它愉悦的新王。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_96420_UnlockDesc|同调率等级达到7"
  },
  [96422] = {
    ID = 96422,
    CnID = "唤醒体故事@杜勒赛因·故事四",
    BaseSortID = 261,
    ActorIndex = 95786,
    Title = "AwakerStory_96422_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_96422_Content|他曾以为，自己的一生是为追求至高的美味而存在。\n王储的职责，至亲的隔阂，道德的规训……他将这一切痛苦抛诸脑后，寻求着味觉艺术的极致。从王储到君主，从人类到神明，一刻不曾停息。他精通了所有烹饪的方法，感知着每一具尸体最细微的差别。他得偿所愿，而在欢愉之后，他总觉得自己似乎遗漏了些什么。\n直到吃下赛琳涅的尸体、见到她的魂灵的那一刻，他才幡然醒悟。那些尸体生前的故事，那些魂灵遗憾的夙愿，才是他一直在追寻、一直在品味之物。\n进食是为了铭记，每一场筵席，都是亡者与生灵的重逢——杜勒赛因将这句话刻入葬骸城的王座。那些寻求他庇护之人，他将赐予他们铭记与安息。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_96422_UnlockDesc|同调率等级达到9"
  },
  [100417] = {
    ID = 100417,
    CnID = "唤醒体故事@皮克曼·简介",
    BaseSortID = 262,
    ActorIndex = 77926,
    Title = "AwakerStory_100417_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_100417_Content|半人半食尸鬼的绘者，拥有他人难以企及的天赋，创作出的食尸鬼画作能模糊画中世界与真实世界的边界，让观看者真正地身临其境。\n不过皮克曼从来不认可疯癫的超现实主义画家这个称谓。在他的宣告里，自始至终，他都是一个只会刻画真实世界的写实主义者。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_100417_UnlockDesc|唤醒体等级达到1级"
  },
  [100419] = {
    ID = 100419,
    CnID = "唤醒体故事@皮克曼·故事一",
    BaseSortID = 263,
    ActorIndex = 77926,
    Title = "AwakerStory_100419_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_100419_Content|美术学院绘画系的课程繁冗庸常，其中大部分没有在我的人生中留下丝毫痕迹，但我至今仍能回想起A.F.3@2年那节模仿绘画课。\n马修先生在艺术协会中极具名望，他的教室人满为患。我们簇拥在马蒂斯的《奢华、宁静与愉悦》前，此时我偶然注意到，角落里一个消瘦的年轻人正在速写本上疯狂地涂抹着。我凑到他面前，准备看看他的模仿画作，却看到一片墓群的杂乱石雕。\n「看呐！正在分娩的食尸鬼女王，正在筹备一场婴儿的血宴……多么疯狂，多么优雅！」\n他兴奋地抬起头来望着我，瞳孔在煤气灯下呈现出奇异的血红色，仿佛蒙着红苔藓的棺椁。我感到恐惧、晕眩，却无论如何也无法挪开眼。在那双眼睛里，我看见了完全不属于这个世界的景象。\n皮克曼，在我第一次见到他的时候我就知道，他和我们不一样，他的人生注定是艰难而不凡的。\n熟识以后，我偶尔会去参观他的画室。我亲眼见到他用腐朽的尸体做模特，用自己的鲜血做颜料。站在那些疯狂的画作面前，我仿佛能听到画布里传来的啃噬声。\n艺术界无论是哪个派别，没有人认可皮克曼的创作，所有的画展与沙龙都将他拒之门外。他看起来毫不在意，仍然乐观坚定地追求着他的艺术，但他的纯粹让他从来都无法藏起自己的失落与痛苦。他的天赋令人震撼也令人恐惧，没有人能真正接受这一点，我也一样。\n在离开前的最后那段时间，皮克曼陷入巨大的痛苦与兴奋交织的状态，我原本以为那是某种必然会发生的心理层面问题，直到某天，我亲眼看到他那弯曲的四肢与利爪、亲眼看到他眼中那疯狂的世界。那是我无法抗衡的恐惧，我只能尝试将它忘记。在我准备彻底结束与皮克曼的联系之前，他主动找到了我，向我作了告别。\n如今我站在现代艺术馆光洁的展厅里，看着那幅被丢弃在角落的皮克曼真迹时，依然能听见画布深处传来指甲刮擦的声响。《地下狂欢》，那是我第一次见到皮克曼时他所创作的画，也是他留给我的告别礼物。皮克曼身上或许有一些不应接近的禁忌谜题，但我仍然把这幅画留了下来。无论他身上发生了什么我不应知道的事，至少有一点是肯定的——他是我见过最具天赋的艺术家。\n昨夜，我又梦见大一的绘画课教室。年轻的皮克曼在房间的角落，冲我大声地笑着。\n「食尸鬼？不，埃弗，从头到尾，我画的都是真相、是人类！」\n月光在他眼中分裂成无数惨红的星点。那是深渊首次向我展露微笑。\n\n——节选自《画家埃弗回忆录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_100419_UnlockDesc|同调率等级达到3"
  },
  [100415] = {
    ID = 100415,
    CnID = "唤醒体故事@皮克曼·故事二",
    BaseSortID = 264,
    ActorIndex = 77926,
    Title = "AwakerStory_100415_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_100415_Content|A.F.3@2年2月12日\n在雕像工作室参观时，将已经完成的雕像作品涂抹上颜料。色彩设计称得上别出心裁，但是和原本雕像组的设计体系违背。\n事后答应免费承担所有雕像作品的上色工作。或许以后的确有可以共同创作的机会。\n证明人：珊\n……\n\nA.F.3@2年4月9日\n企图在钥冢中挖掘尸体作为模特，未遂。被现场抓获后，邀请巡查人员扮演尸体。\n证明人：奥吉尔\n……\n\nA.F.3@2年4月11日\n窃取厨房食材作为画作参考对象。虽然食材被成功拯救，但香料腌制的时机与食材风味都被破坏殆尽，失去了价值。\n至于食材属性与来源……就暂时不方便透露了。\n证明人：杜勒赛因\n……\n\nA.F.3@2年6月29日\n私自潜入校秘典书库，将自己创作的巨幅画作挂在墙面中央。午夜时分，受学校银芯能量密度影响，异形生物从画作中跑出，对部分未受保护的藏品造成破坏。\n事后主动申请进行维修工作，过程中破坏的藏品比怪物破坏得还要多。校方已紧急中止了他的维修行为。\n证明人：诃勒特\n……\n\nA.F.3@2年7月23日\n潜入黑池，企图使用池水作为颜料。塔薇并没有打扰他，但黑池本身的力量让他遭受了不小的伤害。\n我还真有些期待，他会用黑池创作出一幅怎样的图景来？\n证明人：阿利斯泰尔\n……\n\n——《皮克曼档案·违规记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_100415_UnlockDesc|同调率等级达到5"
  },
  [100416] = {
    ID = 100416,
    CnID = "唤醒体故事@皮克曼·故事三",
    BaseSortID = 265,
    ActorIndex = 77926,
    Title = "AwakerStory_100416_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_100416_Content|在收到那份来自葬骸城的邀请之前，皮克曼原以为这世上永远不会有自己这样的人的容身之地。\n在王邸餐桌上见到的那极致疯狂的景象令他辗转难眠。那双能够看到不同世界景象的眼睛，在这宴席上得到了真正的餍足。\n当他从梦境中醒来、葬骸城从他眼前消逝时，皮克曼的遗憾很快便成为了无尽的渴望——他渴望着再次去到那座梦中的城邦，渴望再次见到那无尽疯狂的绝景。沿着这份渴望，他尝试了一切疯狂的举动。最终，他跃入融蚀裂隙，用融蚀液作画，将自己彻底暴露在那可怖的黑色之中。\n每个人都有自己需要完成的事。他有着能看到世界疯狂真相的眼睛，他坚信自己生来就是为了艺术而燃烧的，这是他的使命。\n如他所愿，融蚀为他带来了癫狂与痛苦，也让他再次见到了在葬骸城中所体验到的景象，他眼中那倒错的世界，在融蚀的侵蚀下变得更加狂野绚丽。在漫长的痛苦中，他拿起画笔，日复一日、一刻不停地画着。他是一个忠于职守的写实派画家，他必须要把这些只有他能看到的景象记录下来。\n痛苦变得愈发强烈，当皮克曼已无法再握紧手里的画笔时，他明白自己的时间就要到了。完成最后那幅画的最后一笔之后，他躺进自己早已准备好的棺木，等待死亡的来临。\n融蚀带来的疼痛与混乱让皮克曼的大脑变得浑浊，在死亡冰冷的怀抱中，他安然地闭上了眼。但第二天，明亮的月光再次唤醒了他。融蚀的痕迹与痛苦奇迹般地消退了。在长达数天的生长中，他的肢体变得修长而弯曲，他的犬齿与利爪变得坚硬而锋利。他嗅到了来自坟墓与魂灵的味道，世界疯狂混乱的景象在他的眼里变得从未有过的清晰。\n他欣喜地望着自己半人半食尸鬼的躯体，巨大的幸福感涌上心头。命运为他降下了诅咒，也为这诅咒弥补了他罕见的天分。葬骸城的经历唤醒了他体内微薄的食尸鬼的血脉，在融蚀的催化下，他完成了自己的转变。\n身边的墓碑如同欢聚的人群，围着他跳笨拙的舞蹈。巨大的血月睁开猩红的眼，向他微笑。他的艺术并不属于这个世界，如今，他已经知晓自己将要去往何方。\n皮克曼躺在属于自己的那道棺椁之上，张开双臂，加入这场孤独的狂欢。\n他将要离开人类的城市，去往那个属于他的应许之地。\n他知道，他所追求的一切，正在那里等待着他。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_100416_UnlockDesc|同调率等级达到7"
  },
  [100418] = {
    ID = 100418,
    CnID = "唤醒体故事@皮克曼·故事四",
    BaseSortID = 266,
    ActorIndex = 77926,
    Title = "AwakerStory_100418_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_100418_Content|异类。怪胎。流淌着怪物血液的坏种。亵渎艺术的疯子……\n皮克曼的眼前铺开一张画布，谩骂声与其他声音一同在画布上涂抹出艳丽的色彩。\n他跃入这个绚烂的世界，在疯狂的色彩中徜徉。他殷切地盼求着，将别人领入自己的画作，带他们见证世界最真实的样子。\n现实的尖刺无数次洞穿他的心脏，人与人之间的互相理解比打开两个世界的边界更加困难。\n从人类到食尸鬼，从人类城市到葬骸城，这条道路曲折漫长。他一次次被中伤，又一次次站起。他早已明白，不存在真实也不存在虚假。痛苦与疯狂，就是世界的真相。而他的职责，就是将这一切忠实地描绘出来。\n描绘的意义，只在于描绘本身。\n他将全部的生命与激情献予绘画。他的期许鲜有回应，他的追逐从未停息。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_100418_UnlockDesc|同调率等级达到9"
  },
  [123304] = {
    ID = 123304,
    CnID = "唤醒体故事@茉夏·简介",
    BaseSortID = 267,
    ActorIndex = 94450,
    Title = "AwakerStory_123304_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_123304_Content|严格来说，她并不属于这个濒临崩溃的疯狂世界，但她欣赏这里。\n欣赏这个世界燃烧的壮丽景色，欣赏这些人类在绝望下的痛苦与崩溃。\n信仰已死，社会停转，道德崩坏，自然也不需要再伪装成无聊的「正常人」——\n她终于可以名正言顺释放内心的野兽，展露真实的自己，成为真实的自己。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_123304_UnlockDesc|唤醒体等级达到1级"
  },
  [123301] = {
    ID = 123301,
    CnID = "唤醒体故事@茉夏·故事一",
    BaseSortID = 268,
    ActorIndex = 94450,
    Title = "AwakerStory_123301_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_123301_Content|A.F.3@2年@1月17日，在接到审查会通知@4地区有繁星黎明会正在举行人牲献祭后，我第一时间动身前往该地区进行调查。\n当我到达时，已经是傍晚，该地区因不明原因被浓雾包围，几乎无法视物。\n我并没有携带驱散雾气的装置，但考虑到事情的严重性，我仍是冲进了雾中。如果时间能够倒流，我一定不会再做出这样疯狂的举动，因为、因为雾中有恐怖的@2……\n当那些无法描述形貌的扭曲之物，以非人的速度袭向我时，我根本无法做出任何反应。我的身体陷入僵硬，动弹不得。\n但我终究没有死。那个女孩，那个迷一样、来自雾中的女孩救了我。\n她喊的也许是「龙卷风」？我没听清，我只看到一个斧子从雾中飞来，劈开那恐怖之物的脑袋。然后那个女孩拿下斧头，扛在肩上。\n「雾里可是很危险的，不想死的话，就离开这里。」\n说这话时，她的表情是微笑的，是那种年轻少女的甜美笑容，但我不知为何却觉得这笑容比雾中的怪物更加令人毛骨悚然。\n一个人类，或者说拥有人类形态的东西，穿行在怪物横行的浓雾中，却还能毫发无损，并保持这种「甜美」的笑容……\n恐惧之下，我终于爬了起来，惊叫着和她拉开距离。\n很快，浓雾占据了我的视线，我再次陷入什么也看不见的境地。但她的笑声，她那天真的、青春少女的笑声，一直在雾中回响着。\n——《档案：@4地区繁星黎明会调查》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_123301_UnlockDesc|同调率等级达到3"
  },
  [123302] = {
    ID = 123302,
    CnID = "唤醒体故事@茉夏·故事二",
    BaseSortID = 269,
    ActorIndex = 94450,
    Title = "AwakerStory_123302_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_123302_Content|在大多数学生看来，茉夏绝对是最适合成为朋友的人。她总是带着微笑，兴高采烈地附和着话题，且不会轻易拒绝对方提出的要求，因此总有人邀请她一起逛街、聊天、吃饭。\n但只有少数人才知道她的真实面目。在这些人面前，她再也不用伪装友善，不用掩饰对规则和秩序的蔑视。\n「什么朋友？只是无聊打发时间罢了。要是不这样做，可是会被当做问题学生，被诃勒特院长带去问话——真麻烦。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_123302_UnlockDesc|同调率等级达到5"
  },
  [123303] = {
    ID = 123303,
    CnID = "唤醒体故事@茉夏·故事三",
    BaseSortID = 270,
    ActorIndex = 94450,
    Title = "AwakerStory_123303_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_123303_Content|她的人生似乎总是充满了意外：先是遇到肆虐的未知迷雾，再是莫名其妙被召唤到异世界。\n当召唤仪式完成，初次踏上异世界的土地时，茉夏见到了熟悉的浓雾，而在浓雾中，是人们的惨叫。\n那是人牲在逃避邪教徒的抓捕。\n人牲？邪教徒？多么……令人兴奋的新鲜词汇。\n这代表新的世界，运行着弱肉强食的丛林游戏，而恰好，她从来都不是弱者。\n她平静地在雾中狩猎着邪教徒，高兴得甚至哼起了歌。\n「一个一个又一个……在无人知晓的浓雾里，我尽情发泄♪」\n「敲开你的脑壳，深入你的大脑，让我们在追逐中打发时间♪」\n在这随意的哼唱中，茉夏察觉到内心空洞的饥渴——\n这个疯狂的世界无法填满她内心的空洞，但却能缓解她灵魂上的、对于破坏与癫狂的饥饿。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_123303_UnlockDesc|同调率等级达到7"
  },
  [123300] = {
    ID = 123300,
    CnID = "唤醒体故事@茉夏·故事四",
    BaseSortID = 271,
    ActorIndex = 94450,
    Title = "AwakerStory_123300_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_123300_Content|总有一日，她会回到自己的世界。\n\\n但在此之前，她想看到这个世界的结局——\n\\n那个被称为「守密人」的人，是会被这疯狂恐怖的世界吞噬，还是绽放出光芒，为这摇摇欲坠的世界带来真正的救赎与光明？\n\\n这是个谜团，是个挑战，是个赌注。\n\\n而她，想知道答案。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_123300_UnlockDesc|同调率等级达到9"
  },
  [126933] = {
    ID = 126933,
    CnID = "唤醒体故事@徐·简介",
    BaseSortID = 272,
    ActorIndex = 125346,
    Title = "AwakerStory_126933_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_126933_Content|优雅、妩媚，拥有致命魅力的东方「神明」。传说当她挪开扇面，你将在扇下看到自己最爱之人的面容。\n然而传说只是传说，祈祷她未将目光投向你吧，当她如无孔不入的夜雾般渗进你的记忆，除了狂乱的痴迷……你的颅内就不会剩下任何其他东西了。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_126933_UnlockDesc|唤醒体等级达到1级"
  },
  [126930] = {
    ID = 126930,
    CnID = "唤醒体故事@徐·故事一",
    BaseSortID = 273,
    ActorIndex = 125346,
    Title = "AwakerStory_126930_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_126930_Content|A.F.@16@1年，一艘其航行痕迹未出现在任何勘探手段获取范围内，亦未经过任何手续批准的货轮，悄无声息地停靠在伦蒂尼恩货运港口。\n该货轮后被证实，来自远东区域磐龙古国@2港口。\n货轮入港当夜，供职于该港口的工作人员及附近居民，均表示在梦中见到一名黑发黑瞳、象牙色皮肤的东方女性。描述该女性的外貌时，目击者不约而同地使用了「令人着迷」、「熟悉」等字眼，同时，多位男性目击者在讲述过程中出现木僵现象。\n弥萨格调查员迅速对货轮进行搜索，奇怪的是，除了无处不在的窃笑声，以及明确出现的灵性反应，没有发现任何银芯的痕迹。\n德克斯特勋爵次日进入货轮货舱，在一只「被数次搜索过」的陶瓷制花瓶中，发现了一枚表面流淌着薄薄雾气的银芯。\n截至A.F.314年，该银芯被证实无法以任何手段被唤醒。\n直到现任守密人@3进入弥萨格，该银芯自行完成了唤醒仪式，觉醒为自称「徐」的唤醒体，并主动要求与@3进行链接。\n——摘自《弥萨格大学银芯储存记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_126930_UnlockDesc|同调率等级达到3"
  },
  [126929] = {
    ID = 126929,
    CnID = "唤醒体故事@徐·故事二",
    BaseSortID = 274,
    ActorIndex = 125346,
    Title = "AwakerStory_126929_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_126929_Content|没有几个人真正知道徐是什么时候出现在校园内的，就像她在远东自然而然地漫步于宫廷、王帐以及各种结社。\n所有人都天然地对她有一种熟悉感，仿佛多年老友，甚至心头挚爱，即使祂们从未一起经历过什么。\n只有极少数唤醒体会对徐表现出异乎寻常的戒备，或者说只有极少数实力强悍的唤醒体，能察觉到徐如同雾气般缭绕绵延，渗入对方记忆的异常能力。\n弥萨格校务处曾认真研讨过是否需要对此加以限制，甚至单独为此研制反制设备，徐通过某些交易和一则承诺，消解了这种担忧。\n「妾身的意图，并不在这些小家伙们身上。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_126929_UnlockDesc|同调率等级达到5"
  },
  [126932] = {
    ID = 126932,
    CnID = "唤醒体故事@徐·故事三",
    BaseSortID = 275,
    ActorIndex = 125346,
    Title = "AwakerStory_126932_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_126932_Content|……非其所祭而祭，则谓之淫祀，惑民费财，屡禁不止。\n沿海诸民，均有祭祀杂神旧习，好修淫祠野庙。花费众多，耕织荒置，然乡里不觉其患。当政者数毁房庙，官兵即撤，不日复燃。\n更有外邦流民，定居于乡里，将外邦教派教标倒悬，取@3字形相似者，谓之约「井」，挪为己用。\n庙中所祭主祀及陪祀，皆为生平可查者，多是枉死妇人，初时信众亦多为农妇、戏子、野娼之流。\n妻带夫入，母带子入，娼带客入。凡壮大，则植党营私，屡有数村托举一人之奇观。或入仕途，或私豢民兵，相争相斗。\n@4@4@3@2\n以下字迹均已辨识不清，另有几行十分工整的@3文字，经语言学系翻译，译文如下：\n「不要脸皮的老匹夫，立意偏颇，好生没趣。妾身无聊，养些蛐蛐来斗，也偏要嚼几句口舌。」\n「干你屁事。」\n——摘自《野狐斋杂志抄本节选》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_126932_UnlockDesc|同调率等级达到7"
  },
  [126931] = {
    ID = 126931,
    CnID = "唤醒体故事@徐·故事四",
    BaseSortID = 276,
    ActorIndex = 125346,
    Title = "AwakerStory_126931_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_126931_Content|你有没有觉得世界太过安静，以至于想摔碎什么来听到响动的时刻？\n爱欲是她掷出的一只银瓶，被这只银瓶惊动的猎物……为所爱屠戮，被所爱屠戮，直到心神衰竭，只剩下躯壳。\n然后，这些被榨干的躯壳，会再将更高更多的权柄献予她，把目之所及全都染上腥膻可口的混乱。\n永不停止的混乱。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_126931_UnlockDesc|同调率等级达到9"
  },
  [129599] = {
    ID = 129599,
    CnID = "唤醒体故事@莫丝·简介",
    BaseSortID = 277,
    ActorIndex = 130901,
    Title = "AwakerStory_129599_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_129599_Content|语言不通？不是问题，比手画脚一样能够实现交流。无法控制的能力？在这所学校就如同家常便饭，几天实验就可以解决。\n凭借开朗的笑容和率直到近乎野性的性格，莫丝很快获得了其他唤醒体的欢迎。虽然她经常因为忘了自己的能力而造成巨大破坏（上天保佑那被重建了3次的喷水池），但那又怎么样呢？她不是故意的。\n大概。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_129599_UnlockDesc|唤醒体等级达到1级"
  },
  [129598] = {
    ID = 129598,
    CnID = "唤醒体故事@莫丝·故事一",
    BaseSortID = 278,
    ActorIndex = 130901,
    Title = "AwakerStory_129598_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_129598_Content|北大西洋漩涡M-默斯克斯首次出现于A.F. 1■■，在接下来的数百年间，其规模逐渐扩大。截至A.F. 29■，M-默斯克斯已经发展成直径约260-300英尺（80-90米），水流约5英里（8千米）宽的大漩涡。\n除去水流带来的强大吸力及其影响（附近水域的鱼类及渔船都为其所害），M-默斯克斯之下还存在一个更大的威胁——融蚀裂隙。经过学院成员长时间的观察和研究，确定M-默斯克斯的形成与其下融蚀裂隙有直接关系，并于A.F. 313正式对其进行清除。\n在裂隙中，学院发现了大量生物和船只残骸，并获取编号为O-1841的银芯。\n——节选自《M-默斯克斯事件记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_129598_UnlockDesc|同调率等级达到3"
  },
  [129596] = {
    ID = 129596,
    CnID = "唤醒体故事@莫丝·故事二",
    BaseSortID = 279,
    ActorIndex = 130901,
    Title = "AwakerStory_129596_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_129596_Content|莫丝唤醒体的情况较为特殊，未拘束状态下，能力发动并不以唤醒体自身意志为准。其周围会不定期产生类似漩涡M的特殊能量场，搅碎处于能量场内部的物体。\n当莫丝接触内部包含水（包括血液等体液）的人或物体时，会加速该位置的能量场产生。由于该现象不受莫丝本人的控制，加上其唤醒初期长期处于癫狂状态，危险度极高。\n为此，唤醒体系与物理系、化学系等多系进行了跨院合作，在多次尝试后终于研制出能抵御其破坏力的合成金属「莫丝钢」，并将之制作成口笼和拘束器，予以莫丝佩戴。\n莫丝唤醒体的精神于考德威尔研究员进行的第十一次「O-1841唤醒体接触实验」后开始趋于稳定，该实验中，莫丝将漩涡M-默斯克斯的影响转移至了自身，从而极大降低了对周围的危害。\n但还需注意，莫丝仅凭自身无法长时间维持该状态，唯有借助「莫丝钢」拘束器，莫丝才可以长期稳定地将漩涡M的影响维系在自身内部，同时引导其能力进行战斗。\n恢复神智后，莫丝展现出了她开朗的本质，且对诺缔拉唤醒体表现出了原因不明的亲近。这似乎与两者精神本源的经历有关。\n——节选自《莫丝唤醒体报告》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_129596_UnlockDesc|同调率等级达到5"
  },
  [129597] = {
    ID = 129597,
    CnID = "唤醒体故事@莫丝·故事三",
    BaseSortID = 280,
    ActorIndex = 130901,
    Title = "AwakerStory_129597_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_129597_Content|即使她知道如何正确地组织语句，她也无法告诉你她出生于何处。事实上，无论是哪个家，她现在也只能回忆起雪白的沙滩，茂密的丛林，和无边无际的大海。\n但如果你问她家在何处，她会用生硬的词语和热烈的肢体语言告诉你：家在海上，随着洋流四处游荡。\n长久无人陪伴的人无法判断何为孤独，但在那艘船上她尝到了亲情，也获得了友谊：她与那以鹦鹉螺为名的伙伴分享好吃的烤鱼、漂亮的贝壳，分享一个关于陆地、关于远行、关于冒险的梦想，并在最后分享一个归于黑色海浪和漩涡的死亡。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_129597_UnlockDesc|同调率等级达到7"
  },
  [129600] = {
    ID = 129600,
    CnID = "唤醒体故事@莫丝·故事四",
    BaseSortID = 281,
    ActorIndex = 130901,
    Title = "AwakerStory_129600_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_129600_Content|在一切被急流吞没之前，在无垠的大海和微咸的海风中，在那艘船上，没有血缘的家人和朋友让她明白了孤独的含义，并不愿再落入其中。\n可为了她最好的朋友，她小小的家人，她甘愿再次回归那漆黑的死寂。\n在一切被黑暗覆盖之后，她以另一种姿态获得了新生。虽然这样的生活多有不便——她时常忘记自己的力量会给周遭的事物带来巨大破坏——但获得更多朋友的可能性依旧让她无比快乐。\n当然，如果她最好的朋友能够想起她们曾经的故事，那就更好了。\n「比更好更好，更更更好！」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_129600_UnlockDesc|同调率等级达到9"
  },
  [134315] = {
    ID = 134315,
    CnID = "唤醒体故事@阿拉克涅·简介",
    BaseSortID = 282,
    ActorIndex = 77918,
    Title = "AwakerStory_134315_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_134315_Content|被网围困的织网者，命运剧院的剧作家与永恒的观众。\n丝线从指间垂落，缠绕成幕布、剧本与牢笼——每一根都由阿拉克涅亲手纺出，又将她层层裹缚。\n观众席永远空无一人，唯有她自己在台下凝视台上自娱自乐的演出，循环往复，永无终场。\n她的存在，是剧院的幽灵，也是命运的具象。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_134315_UnlockDesc|唤醒体等级达到1级"
  },
  [134319] = {
    ID = 134319,
    CnID = "唤醒体故事@阿拉克涅·故事一",
    BaseSortID = 283,
    ActorIndex = 77918,
    Title = "AwakerStory_134319_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_134319_Content|我于3@2年秋末前往旧城区的「命运剧院」参加次女高音职位的面试。\n抵达时为下午四时十七分，天色阴沉，无雨。剧院正门未锁，观众席空无一人，根本没有面试官的身影。\n可是舞台中央正在上演一出木偶戏——没有提线人，没有乐声，只有几具苍白的人形傀儡在无声地舞动。它们的动作精准无比，关节转动时发出细微的咔哒声，令人毛骨悚然。而那些丝线……那些从穹顶垂落的丝线，竟似有生命般微微震颤，时而绷紧，时而松弛，仿佛在应和某种不可见的节奏。\n就在我试图转身离开时，贵宾席第五号包厢传来一道女声。 \n「欢迎你，克莉丝汀。」\n那声音既非年轻也非苍老，像是从百年尘封的丝绸帷幕后渗出的回响，诡异而恐怖。\n我浑身发冷。还未做自我介绍，她怎会知道我的名字？而且这些人偶……\n我拔腿奔向出口，可就在我即将触到门把手的刹那，黑暗中涌出无数蜘蛛——眼中闪烁着幽光，它们吐出银白的蛛丝，试图封堵我逃跑的路线。更惊悚的是，那群蜘蛛竟然口吐人言，一直重复那句「唱吧，我的天使，为我歌唱吧……」。\n我拼命撕扯、奔跑、尖叫，最终竟真的逃了出来。 \n……\n从此我害怕来自贵宾席第五号包厢的视线，于是要求歌剧院将这个包厢封存。\n然而……如今每当我站在聚光灯下高歌，总感觉头顶有丝线轻轻牵动我的眉梢。\n难道我也变成了被丝线操纵的木偶？我不敢继续细想。\n\n——节选自《歌唱家克莉丝汀回忆录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_134319_UnlockDesc|同调率等级达到3"
  },
  [134317] = {
    ID = 134317,
    CnID = "唤醒体故事@阿拉克涅·故事二",
    BaseSortID = 284,
    ActorIndex = 77918,
    Title = "AwakerStory_134317_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_134317_Content|幕布尚未完全升起，灯光已如潮水般倾泻而下。\n弥萨格的观众们屏息凝神，等待命运的主角登场。\n舞台很小，小得几乎容不下俄狄浦斯的脚步。可当那个穿校服的少年举起手，声音穿透简陋的舞台时，他说出的第一句台词竟如神谕降临： 「我就是那不幸的人，命中注定要弑父娶母。」\n……\n「我究竟犯了哪一条神律呢……我这不幸的人为什么要仰仗神明？为什么要求神保佑，既然我这虔敬的行为得到了不虔敬之名？」名为安提戈涅少女质问着神律的不公。\n……\n哈姆雷特在丹麦的城堡中踱步思考。「生存还是毁灭，这是一个值得考虑的问题；默然忍受命运的暴虐的毒箭，或是挺身反抗人世间的无涯的苦难，通过斗争把它们扫清，这两种行为，哪一种更高贵？」\n……\n审判席上，约翰·普罗克托缓缓抬起头，宣告了他的答案：「因为我在那些登上绞刑架视死如归的人面前连粪土都不如，我怎么能名誉扫地地活下去？」\n……\n那些关乎命运的词句，演成了今天这一出戏剧。\n阿拉克涅站在侧幕，手指无意识地掐进掌心。 \n那些因剧中人物而共情的眼泪，谢幕之时如雷鸣般响亮的掌声……\n台下观众的种种面孔尽收眼底，她忽然觉得，那颗长久以来无谓跳动的心，终于找到了节拍。 \n此时此刻，她的声音、她的存在，已悄然嵌入这浩荡的命运之流——不再只是观看命运的眼睛，而是正在书写的崭新剧本。观众的命运、表演者的命运以及剧作家的命运，因一出正在上演的戏剧得到了连接……\n心之胜利，原来如此安静，又如此震耳欲聋。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_134317_UnlockDesc|同调率等级达到5"
  },
  [134316] = {
    ID = 134316,
    CnID = "唤醒体故事@阿拉克涅·故事三",
    BaseSortID = 285,
    ActorIndex = 77918,
    Title = "AwakerStory_134316_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_134316_Content|阿拉克涅起初并不清楚自己能看见命运。 \n世界对她而言和其他人一样，模糊、喧闹、充满偶然。\n两岁那年，她说出了人生中的第一句话。 \n不是「妈妈」，也不是「爸爸」，而是站在门廊下，对着照顾家族数代的老管家轻声说：「晚安」。 \n那天晚上，管家因心脏病猝然离世。她攥着他留下的怀表，在门房外哭到睡去。那时她还不懂死亡与命运，却已尝到了命运提前泄露的苦涩滋味。\n五岁，在晚宴宾客脸红耳热的欢呼声中，她学着母亲的样子，踮起脚尖跳起笨拙的华尔兹。 \n脚上那双红舞鞋鲜艳得像血，也像某种预兆。她转圈时跌倒了，没人会发现她眼中一闪而过的画面，好像注定要跌倒似的。\n七岁生日，父亲送她一件名为「摩伊赖」的纺轮，那是命运三女神的名字。 \n她在林间奔跑，笑声清脆，却在绊倒时听见咔的一声，纺轮断了。 \n她蹲在落叶里，手指抚过裂痕，忽然发现仿佛有无数丝线从断口涌出，缠绕她的指尖，直通向看不见的远方。\n后来，她第一次走进歌剧院，第一次结识挚友，第一次亲手埋葬爱犬…… \n每一个「第一次」，都伴随着无声的终幕在她眼前闪现。她开始明白：所谓开端，都早已定下了命运的终局。\n从此，视线再无法停留于表象。人脸成了薄纱，她一眼便能望穿其下奔涌的命途：谁将病逝于夏末，谁会在婚礼前夜自缢，谁的孩子将在十年后亲手埋葬他……惊喜消亡，期待枯萎。所谓「未来」，不过是她提前拆封的讣告。\n她曾试图提醒周围人即将到来的厄运，却总在言语出口的刹那，促成预言的实现。 \n面对他们惊惧退避的眼神，那一刻她终于明白： \n「看见，并不等于能改变」。\n命运之网早已织就，她的「预知」不过是网眼间偶然透出的一缕光——照见结局，却无力扭转经纬。\n于是她拿起那件名为「摩伊赖」的纺轮。 \n断掉的纺轮早已被修复，但裂痕仍在。她日复一日地纺织着，关于命运的天赋奇异地与这纺轮融为一体。 \n从此，所有人的命运，皆在她指间流淌、交织，织成一张横跨时空的巨网。无形之间，她也被这张永恒的网困在其中。她见证着无数欢笑与泪水，无尽的支点、无尽的可能性裹挟着命中注定的毁灭一次又一次上演……\n而阿拉克涅不会停下。不是为了编织，而是为了维系——若她停止，整张命运之网或将崩解，连同千万人生一同归于虚无。 可是她也看到，当命运之网编织完成，祂的苏醒也将带来无可避免的毁灭……\n她作为织者、也是被缚者，成为了观众、也成了囚徒，是剧作家、亦是剧中人。\n能看清他人的命运，究竟是好事还是坏事？ \n阿拉克涅早已不再追问。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_134316_UnlockDesc|同调率等级达到7"
  },
  [134318] = {
    ID = 134318,
    CnID = "唤醒体故事@阿拉克涅·故事四",
    BaseSortID = 286,
    ActorIndex = 77918,
    Title = "AwakerStory_134318_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_134318_Content|作为命运之网的编织者，那个维系千万人生死经纬、掌中流淌着过去与未来的存在，阿拉克涅有着一个近乎浅薄的爱好。\n她热爱戏剧。并非迷恋情节的跌宕或台词的华美——那些早已烂熟于心，作为剧本的创作者，情节的每一处转折、演员的每一句台词她都了如指掌。 \n可她仍一次次走进剧场。\n她真正渴求的，是踏入剧场那一刻身临其境的「在场感」。\n当幕布升起，观众席沉入黑暗，舞台却成为唯一真实的世界。那一刻，时间不再是单向奔流的河，而是在限定空间的演绎——过去、现在、未来在此重叠，一切不再是纸张之上的剧本，而是正在「此刻」发生的生命震颤。\n而她，终于不再是那个站在命运之外，只能凝视丝线却无法触碰的旁观者。 \n在剧场里，她可以短暂地封存记忆、站上舞台，让自己成为那个颤抖着说出遗言的少女，抑或是作为放任演员自由表演的观众，卸下先知的重负，因演员的一颦一笑而屏息、流泪、颤抖。不是作为预言者，而是作为一个活生生的人，以无知者的姿态，与角色同频呼吸、为一句台词心碎。哪怕明知结局无可更改，哪怕悲剧注定降临。这份幻觉，却让她短暂地挣脱了永恒观众的宿命。\n不被隔绝于命运之外，而是被允许进入其中——哪怕只是一瞬，哪怕只是幻影。\n这微小的沉溺，已是命运给予阿拉克涅最奢侈的恩典。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_134318_UnlockDesc|同调率等级达到9"
  },
  [139857] = {
    ID = 139857,
    CnID = "唤醒体故事@沙耶·简介",
    BaseSortID = 287,
    ActorIndex = 130226,
    Title = "AwakerStory_139857_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_139857_Content|当一切被血肉侵蚀，当日常被错乱颠倒，嘶鸣的杂音中，蒲公英飘落到了这片荒原。\n伸出手吧，牵住她吧。\n爱会突破表象，将你与你所爱之人，再次锚定。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_139857_UnlockDesc|唤醒体等级达到1级"
  },
  [139858] = {
    ID = 139858,
    CnID = "唤醒体故事@沙耶·故事一",
    BaseSortID = 288,
    ActorIndex = 130226,
    Title = "AwakerStory_139858_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_139858_Content|和将要发生、还未发生的一样，和铭记在心里、永远不会遗忘的那些事一样。\n无论外表变成什么样子，无论世界变成什么样子，极其不同，又极其相似的两个人，会得出同一个回答。\n「我们有想要见到的人。」\n「我们会不顾一切找到他们，找到能够与他们一同存在的世界。」\n「如果那条路途太过遥远，我们就会一直在找到他们的路上，在寻觅里度过漫长的一生。」\n或许是因为这样，在血肉的嘶鸣声中，那枚璀璨的银芯被放进了守密人的掌心。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_139858_UnlockDesc|同调率等级达到3"
  },
  [139860] = {
    ID = 139860,
    CnID = "唤醒体故事@沙耶·故事二",
    BaseSortID = 289,
    ActorIndex = 130226,
    Title = "AwakerStory_139860_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_139860_Content|沙耶很快就成为了一名受欢迎的学生，极强的学习能力、求知若渴的好学精神——在弥萨格，拥有这些品质的唤醒体，甚至远比她特殊的体质更为稀有。\n出乎意料地，沙耶对拉蒙娜展现出了异乎寻常的兴趣，或许是由于拉蒙娜跟守密人之间的羁绊，又或许是由于拉蒙娜跟德克斯特之间特殊的父女关系。\n介于沙耶与人类完全不同的善恶观与道德观，学院一度建议拉蒙娜采取特殊的安保措施，然而当事人拒绝了此项提议。\n她们谈话的内容无人知晓，但极偶尔地，在某个弥萨格温暖的午后，草坪上温柔的风，会参与她们之间不为人知的长谈。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_139860_UnlockDesc|同调率等级达到5"
  },
  [139859] = {
    ID = 139859,
    CnID = "唤醒体故事@沙耶·故事三",
    BaseSortID = 290,
    ActorIndex = 130226,
    Title = "AwakerStory_139859_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_139859_Content|「沙耶」究竟是什么？解开答案的钥匙，存在于某个遥远的彼方。\n「……被命名为沙耶的那个生物——她会出现在这个宇宙的理由，不是偶然，而是出自作为生物，被预设好的本能的结果。其所指向的，乃是一切生物的终极目的，繁殖。她与她的眷属，是能够跨越异次元之壁、播撒种子的生物。……」\n「……根据推测，沙耶这个个体，是否在她们的种族中，也是一个例外的存在？人类是一个因为智性而颠覆了本能的种族，这个物种的缺陷，是否也被沙耶继承了？在学习人类的过程中，人类与本能矛盾的感情观念，或许使沙耶的繁殖本能也被一并摧毁……」\n「——总有一天，以爱为名的祝福会降临到她头上。灼热的恋爱在她心中燃烧，她将可堂而皇之地游遍世界，再次恢复闪耀与光辉。」\n要用善恶来衡量她吗？还是要用爱意的真挚与否来衡量她呢？\n可能这一切根本就没有答案，带着那个世界无解的答案，意外来到许久之前，什么都还没有发生的这个宇宙的沙耶，被记忆中的答案引领着，想着遗忘的彼方，继续前行。\n她等待着蒲公英盛开的那一天。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_139859_UnlockDesc|同调率等级达到7"
  },
  [139861] = {
    ID = 139861,
    CnID = "唤醒体故事@沙耶·故事四",
    BaseSortID = 291,
    ActorIndex = 130226,
    Title = "AwakerStory_139861_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_139861_Content|离人类最远的种族，在学习如何成为人类的过程中，变得连与本能违背的地方都与人类相像。\n如果没有爱，那原本要创造的世界就是毫无意义的。\n如果有爱，那就只有创造有两个人所在的世界才是有意义的。\n只是如此恐怖和残忍而已，只是如此纯真和光辉而已。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_139861_UnlockDesc|同调率等级达到9"
  },
  [142872] = {
    ID = 142872,
    CnID = "唤醒体故事@庞托斯·简介",
    BaseSortID = 292,
    ActorIndex = 141302,
    Title = "AwakerStory_142872_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_142872_Content|原本应该翱翔于夜空的英雄史诗戛然而止，他选择坠入深渊，把自己献祭给更加伟大莫测的存在。\n从此他再也不用面对分离、平庸，和无可奈何的衰败。\n他把自己的亲人、友人、敌人，都永远留在了与他融为一体的厄波扬斯。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_142872_UnlockDesc|唤醒体等级达到1级"
  },
  [142873] = {
    ID = 142873,
    CnID = "唤醒体故事@庞托斯·故事一",
    BaseSortID = 293,
    ActorIndex = 141302,
    Title = "AwakerStory_142873_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_142873_Content|A.F.2@17年8月，以纳拉@1湾为圆心，半径@3英里内，出现多起异常灵性事件。\n@1封来电声称目击到已被登记死亡的数名人类个体，在@3旧址附近出没，这些个体后经查证，均亡故于@2港镇在1@19年发生的爆炸事件，该爆炸原因迄今仍未查实，涉事人员均有不同程度的记忆缺失症状。\n「我见到她了，我发誓……她仍然和我与她分别时一样年轻，但这绝无可能。」\n「她和我告别已经是@2年前的事了，但她还是那么美丽，她只是和他们一同站在悬崖边，远远地向我微笑。」\n「……当我们被珍视，我们会始终拥有再次选择的机会，EBWYN@2OS，Ebwy@1noss……」\n录音材料结尾被近似海水涌动声的不明杂音污染，该目击者于20小时后因器官衰竭在家中死亡，死亡时的年龄为76岁。\n该材料寄达弥萨格大学后次日，已退休的唤醒体系研究员，亦是该目击者钱伯斯·考德威尔的远方亲属，艾琳·考德威尔，收到了钱伯斯带来的O-@1银芯。\n据艾琳·考德威尔回忆，钱伯斯的身形样貌，均与年轻时无异。\n他在消失前只留下了一句话。\n「请将祂带去弥萨格，祂要在那里等待最后一位厄波扬斯的归人。」\n——摘自《弥萨格大学银芯储存记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_142873_UnlockDesc|同调率等级达到3"
  },
  [142871] = {
    ID = 142871,
    CnID = "唤醒体故事@庞托斯·故事二",
    BaseSortID = 294,
    ActorIndex = 141302,
    Title = "AwakerStory_142871_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_142871_Content|弥萨格大部分师生都非常乐意在外勤时寻求庞托斯的帮助，且庞托斯也从来不吝于伸出援手。\n慷慨、爽朗、稳重可靠，就算明显与校内部分成员存在严重摩擦，这名唤醒体给人的第一印象依然好得惊人。\n然而，虽然庞托斯本人已与弥萨格达成协定，不再扩大厄波扬斯的居民规模，但经历数次「结束路径特殊」的外勤行动后，依然有大量移居申请递交到校务处。\n在茜尔维娅对申请者们进行集体心理辅导的同时，校务处迅速增补了以下两条外勤条例。\n1、如非极度紧急情况，严禁向庞托斯求援。\n2、如非极度特殊情况，严禁进入厄波扬斯。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_142871_UnlockDesc|同调率等级达到5"
  },
  [142869] = {
    ID = 142869,
    CnID = "唤醒体故事@庞托斯·故事三",
    BaseSortID = 295,
    ActorIndex = 141302,
    Title = "AwakerStory_142869_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_142869_Content|庞托斯花了很长时间去追查蕾莎的死因，她经历过太多场艰难的战斗，取得过太多场卓绝的胜利，或许是药物、或许是不为人知的魔术，总会有一个原因，一个令蕾莎死在一只孱弱的海怪手上的原因。\n直到很久，很久之后，他的某位未曾加入厄波扬斯的人类同行者，长出了第一根白发。\n逐渐跟不上的体力，逐渐迟钝的反应，以及哪怕没有诉诸于口，但溢于言表的对于安定平静生活的渴望，一切都是如此熟悉。\n庞托斯突然明白了，那个始终不见踪影的敌人的名字——「衰老」。\n蕾莎隐居的原因，蕾莎被打败的原因，令他一生的可能性从此消失，只剩下仇恨的原因，就只是这么随处可见，又无法抵挡的东西。\n但这没有任何关系，他的毁灭到来得太早，获得的力量又太过让他满意。\n无论要向怎样的存在效忠，无论要付出什么样的代价，它都不会再发生在厄波扬斯。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_142869_UnlockDesc|同调率等级达到7"
  },
  [142870] = {
    ID = 142870,
    CnID = "唤醒体故事@庞托斯·故事四",
    BaseSortID = 296,
    ActorIndex = 141302,
    Title = "AwakerStory_142870_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_142870_Content|「你到底是不允许衰老发生，还是不允许任何你无法控制的事情发生？」\n他没有回答，他也不需要回答。\n深渊比灾难更早选中了他，因为他未宣于口的执念与深渊如此契合。\n听从、陪伴、一成不变，如同深渊无法挣脱，如同深渊令一切窒息，又留存一切。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_142870_UnlockDesc|同调率等级达到9"
  },
  [146395] = {
    ID = 146395,
    CnID = "唤醒体故事@蚀灭·萝坦·简介",
    BaseSortID = 297,
    ActorIndex = 145363,
    Title = "AwakerStory_146395_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_146395_Content|无论是哪个维度的萝坦似乎都不喜欢言语，蚀灭·萝坦更是如此。在她面前，语言是多余的，力量本身就是最完美的修辞。\n在如君王般从容优雅的外壳下，她那双如濒死恒星般的异色瞳孔里，燃烧着她最为真实的渴望——她是星海深处升起的远古之力，是混沌在愤怒中铸就的白骨利刃。万物在她眼中只分两种：值得一战的，和不值得挥剑的。\n那对由星天之鲸的骨骼所铸就的巨剑始终饥渴，正如她对力量之巅的渴望永无餍足。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_146395_UnlockDesc|唤醒体等级达到1级"
  },
  [146399] = {
    ID = 146399,
    CnID = "唤醒体故事@蚀灭·萝坦·故事一",
    BaseSortID = 298,
    ActorIndex = 145363,
    Title = "AwakerStory_146399_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_146399_Content|《弥萨格大学天文观测站异常报告》\n\nA.F.@3年起，北半球多座天文台陆续报告了银河系边缘区域的异常光谱衰减现象。初始数据显示，至少三颗已编目恒星在极短时间内从可观测范围中消失，其光谱残留与任何已知天体衰亡模型均不相符。没有超新星爆发的辐射特征与黑洞吸积的引力透镜效应，恒星如同被某物一口吞噬，干净利落，不留残渣。\n\nA.F.@3年3月，审查会天体异象小组在第四颗恒星消失坐标处捕捉到一组极低频的灵知波动。同年8月，第五次消失事件发生后，天文观测站终于借助改良后的银芯长程探测阵列捕捉到了短暂的视觉信号：一个由白骨构成、外形近似鲸鱼的巨大生物，腹部密布尖刺状突起，口腔内部呈现出与物质界不相容的高温光谱。它张开巨口的瞬间，恒星的光芒如同溪水流入深渊，悄无声息地消逝。\n影像仅持续0.7秒便因探测阵列过载而中断。事后检测发现，阵列中三分之一的银芯材料出现了不可逆的结构崩塌。\n\nA.F.@3年冬，天文台监测到灵知脉冲信号突然改变方向，其目的地正是笔者所在之处。\n审查会进入最高戒备状态，然而预想中的灾难并未降临。信号在接近近地轨道时收束至无害状态，最终定位于西北海域的一座无人火山岛。当第一支勘探队登岛时，他们在火山口的玄武岩壁上发现了深深嵌入的、由某种未知骨质材料构成的巨剑，以及剑旁盘膝而坐、仿佛等候已久的人形个体。\n\n该个体为女性外表，通体覆有骨质甲片与异族铠甲纹饰，双瞳异色。在勘探队接近时，她睁开眼，语气中不含任何敌意，只有一种近乎傲慢的平静。\n「你们之中，有谁值得让我出手吗？」\n勘探队面面相觑，无人作答。沉默片刻后，她重新闭上双眼。\n「那就去找一个来。我等着。」\n\n此后，审查会与弥萨格大学联合将该岛屿列为特级监控区，并派遣多名唤醒体前往协助调查。经过长达数月的远程观测与谨慎接触，该个体最终同意在「获得足够强大的对手」这一条件下配合审查会的管理，编入唤醒体名录。\n恒星消失事件自该个体被收容后完全停止。但检测数据显示，那些被吞噬的恒星能量，似乎仍以某种形式存储于个体体内——在长时间的观测期间，她的诺斯指数依然在持续攀升，且未表现出任何衰减趋势。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_146399_UnlockDesc|同调率等级达到3"
  },
  [146398] = {
    ID = 146398,
    CnID = "唤醒体故事@蚀灭·萝坦·故事二",
    BaseSortID = 299,
    ActorIndex = 145363,
    Title = "AwakerStory_146398_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_146398_Content|抵达弥萨格之后，蚀灭·萝坦的安静维持了两天。第三天的黄昏，她带着她的骨剑出现在公共训练场。\n\n弥萨格的唤醒体们有着骄傲的资本，会出现在训练场的尤其如此。但对于这位无礼的不速之客，他们始终保持着高度的警惕。在火山岛的简单接触后，关于蚀灭·萝坦的传说已经在唤醒体之间流传开，他们知道自己将要面临的是一位怎样的对手。\n然而事实证明，他们的警惕还不够。\n\n当第一位上前挑战的唤醒体被一剑拍飞出训练场边界、击倒二十米外的石墙时，整个训练场陷入前所未有的亢奋之中。第二位，第三位……在@3年这个普通的黄昏，先后有九名唤醒体对蚀灭·萝坦发起了挑战。\n\n据在场的校刊记者汉娜描述，蚀灭·萝坦在整个过程中没有说过任何一句话，如同一座沉默而坚不可摧的灯塔，屹立在唤醒体们如海潮般猛烈的进攻中。那两柄骨剑如灯光般在晚霞中闪耀，优雅的弧线精准地终结着每一位对手的攻势。\n\n那一天，蚀灭·萝坦的铠甲折损超过80%，肩膀与腹部有两处极为严重的创伤，骨剑上留下了一道巨大的豁口，几乎断裂。而以这一切为代价，她成为了最后唯一还站在训练场上的人。\n\n她看着墙壁上被剑划出的深痕、地面上那些巨大冲击力留下的深坑、还有那些神色复杂地盯着她的唤醒体们，露出了来到这个世界后的第一个笑容。\n\n「很高兴和你们见面。你们可以叫我蚀灭·萝坦。」",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_146398_UnlockDesc|同调率等级达到5"
  },
  [146396] = {
    ID = 146396,
    CnID = "唤醒体故事@蚀灭·萝坦·故事三",
    BaseSortID = 300,
    ActorIndex = 145363,
    Title = "AwakerStory_146396_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_146396_Content|她最初的记忆只有愤怒。\n没有面孔，也没有形体的边界，只有无穷无尽的、沸腾翻涌的暴力本能。她是星海深处凝聚的混沌，是亿万年间酿成的灾厄。她撕裂，焚烧，吞噬，不为任何目的，只因为那是她唯一知道的事。\n直到那位白纱的「神明」到来。如同一颗恒星被从内核剖成两半，她感到自己的力量如潮水般退去，血肉与骨骼从精神中被连根拔除，汹涌的怒焰被活生生地从灵魂上剥离。\n\n神明无法平息她的愤怒，于是选择将她的灵与肉分离。\n混沌之兽不再存在，她的躯体化为利维坦，带着她全部的力量沉入虚空。而她，一个仅剩精神的残骸，在空荡荡的意识中醒来。\n怒火并未熄灭，而是转变为了更为持久、更为令人畏惧的东西：渴望。对力量的无穷尽的渴望，驱使着她重新站起来。\n她开始行走，开始战斗。她在荒芜的星海之间流浪，挑战一切挡在面前的强者。每一场胜利都像是往空洞的躯壳里填入一把沙砾，她渐渐从沙砾中磨出了形状，磨出了意志，磨出了属于「蚀灭·萝坦」的轮廓。\n\n然后，她听见了那头鲸的歌声。\n将身躯化为整个世界的星天之鲸，束缚奴役万千生灵的庞然大物，她在祂身上看到的不是欲望与恐惧，而是亲切。她的记忆开始恢复，她知道那是她的力量，她知道，从始至终，祂就是属于她的。\n于是，她来到祂的面前。\n于是，她向祂拔出剑。\n\n巨鲸的权能如决堤的洪流涌入她的身体，几乎将她撕碎，但从始至终她依然站立，星海之中，多出了一具巨鲸的尸骨。\n被奴役的星球重获自由。死于欲望的魂灵们抬头仰望，将她称作救世者、守护神，将王冠送至她的身前。\n蚀灭·萝坦没有回应那些赞颂。她只是站在巨鲸的尸骸之上，感受着体内翻涌的新生力量，听着灵魂深处那道从未消失的呼唤变得前所未有的清晰。\n那是星天之鲸的声音，那是她自己的血肉在呼唤着她。\n\n她的手触碰利维坦的颅骨，分离了无数纪元的精神与肉体重新交融。骨甲覆上她的身躯，力量充盈她的身体。\n混沌之兽重生了，但她已不再是当初那头只知暴怒的灾厄。漫长的流浪，无数的战斗，那些曾被她击败和击败她的对手们，已经将这纯粹的混沌锻打成了拥有意志的锋刃。\n她闭上眼，享受着体内翻涌的、完整的力量，但她也清楚地知道，这并非终点。\n\n星天之鲸的权能，利维坦的力量，那些吞噬过的星辰……一切都是身后的阶梯。她提起骨剑，转身走向下一片未知的星海。\n她渴望着，下一场令她沸腾的战斗。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_146396_UnlockDesc|同调率等级达到7"
  },
  [146397] = {
    ID = 146397,
    CnID = "唤醒体故事@蚀灭·萝坦·故事四",
    BaseSortID = 301,
    ActorIndex = 145363,
    Title = "AwakerStory_146397_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_146397_Content|蚀灭·萝坦从不回望身后的尸体。\n被击败的对手、被踏碎的荒原、被吞噬的星辰……她一一跨过它们，寻找着下一个目的地。\n\n有人问她，抵达力量的尽头之后要做什么。\n她没有回答，因为这个问题毫无意义，就像询问火焰燃尽之后要去何处。火焰没有「之后」，燃烧本身就是它存在的全部。\n\n她行走，她战斗，她一次又一次地举起剑，从来不是为了证明、守护、复仇、权欲，或是别的什么无聊东西。\n只是因为，在剑与剑碰撞的那一瞬间，在力量与力量交锋的那一刹那，她能最清晰地感受到自己活着。\n\n追寻力量的道路没有尽头。而她庆幸如此。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_146397_UnlockDesc|同调率等级达到9"
  },
  [148400] = {
    ID = 148400,
    CnID = "唤醒体故事@卡拉布·简介",
    BaseSortID = 302,
    ActorIndex = 77921,
    Title = "AwakerStory_148400_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_148400_Content|她像是最懂事的孩子，永远懂得你最隐秘的心思，总是让你忍不住信任与倾诉，然后在恰到好处的时机，为你提供最求之不得的「赐福」。但请谨记，千万不要因为她娇俏的身躯和楚楚可怜的眼神而心生怜悯，以免成为那纯白身躯曾经吞噬的贪婪冤魂中的一员。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_148400_UnlockDesc|唤醒体等级达到1级"
  },
  [148397] = {
    ID = 148397,
    CnID = "唤醒体故事@卡拉布·故事一",
    BaseSortID = 303,
    ActorIndex = 77921,
    Title = "AwakerStory_148397_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_148397_Content|该银芯由弥萨格守密人%player%在@2峰崩毁事件后回收，由于其原所在维度已无法观测，银芯析出后的影响及实际唤醒方式暂时未知。 \n以下内容，记叙于守密人%player%随身携带的纸质手记： \n银芯质地经肉眼观测，极度纯净，无任何可见杂质。当无外力介入时，整体结构趋向规则，似乎有某种意志努力使其看上去坚固稳定，并焕发出如同火彩的明亮光泽。 但该银芯的诺斯指数近乎触达底线极值，实际内部结构极其脆弱松散，当观测距离小于1/@1英寸时，会触发该银芯的自我保护行为，观测者将突然看见大量形似冰晶的流动粒子，推测它们此前正在以极其特殊的方式折射外界光线，保护银芯的核心不被窥探。 换句话说，虽然这很不专业，但我认为这是一枚充满了「欺骗」的银芯。 \n在触发银芯的自我保护机制后，观测者的身躯会陷入短暂木僵状态，瞳孔渐渐褪色，最终完全呈苍白色，银芯将在此期间进行调整，直到重新回到被观测前的稳固状态。 经多次试验，这种自我保护机制不会造成实际伤害，但随之产生的失温症状依然存在一定危险。注：及时食用甜食，尤其是苹果类甜品有明显缓和作用，原因……暂不明确，吧？ 好消息，在发生这一切之后，这个自私的、内心充满层层防备的小骗子，显然对我们并没有真正的恶意。 \n——摘自《弥萨格大学银芯储存记录》",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_148397_UnlockDesc|同调率等级达到3"
  },
  [148399] = {
    ID = 148399,
    CnID = "唤醒体故事@卡拉布·故事二",
    BaseSortID = 304,
    ActorIndex = 77921,
    Title = "AwakerStory_148399_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_148399_Content|众所周知，学校的别称是什么？\n象牙塔！ \n听上去就和仙女这个名号非常相配，毕竟，要到哪里再去找一个有钱、有闲、还有很多内心充满可贵信任的潜在信徒的，完美天堂呢？ \n卡拉布的教派以一种堪称迅猛的速度，在短期内就发展出了为数可观的信徒，中坚力量几乎全部都是幼年唤醒体，他们近乎虔诚地相信着这位「仙女教母」，心甘情愿地定时定额上缴糖果和点心。令人意外或意料之中的，卡拉布的确会时不时降下一些赐福，多数发生在雷欧王国的传统节日，比如3@1年银霜节那场本不可能的降雪，以及新年夜被津津乐道至今的糖果雨。 \n教务处似乎甚至从未讨论过是否要阻止这种，原则上不应存在的「校内传教行为」。\n「让祂们玩吧，我们都知道这些孩子曾经经历过什么，总有一些事情是只有同样是孩子的人才能做到的。」 \n「当然，不能太过头。」\n某位不便透露姓名的校内人员笑眯眯地发表了如上言论，据不可靠消息称，和她共进红茶之前的那次事件，是卡拉布迄今为止唯一一次，真正尝试触碰校规。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_148399_UnlockDesc|同调率等级达到5"
  },
  [148398] = {
    ID = 148398,
    CnID = "唤醒体故事@卡拉布·故事三",
    BaseSortID = 305,
    ActorIndex = 77921,
    Title = "AwakerStory_148398_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_148398_Content|以下内容由卡拉布转述、弥萨格唤醒体系背景调查组整理记录成文：\n卡拉布幼年时正值十字军东征的热潮，孤苦无依的她决定向东前往安条克公国投奔姨父一家。听说东方的新土地象征着自由与梦想，一文不名的人也能在那里找到自己的出路。罗莎姨妈甚至经营起一座种植园，过得还不错。卡拉布幼年与罗莎姨妈关系极好，她下定决心要攒够路费前往安条克。 \n卡拉布在城市的贫民窟流窜，毫无背景的她只能靠偷拐抢骗苟活，原本单纯的一面被消磨殆尽。后来她遇到了巫师艾伐格，他许诺卡拉布，只要与自己合作，信徒们的供奉俩人三七分成，这样她就可以攒够前往东方的路费了，还能买很多最喜欢的糖果。俩人于是组成了招摇撞骗二人组，卡拉布被奉为小仙女教母居住在乡下临时搭建的神殿内，艾伐格则以她大祭司的身份招揽信众。 \n随着卡拉布在当地的名声越来越大，她开始不满足于现有的分成，以退出合作威胁艾伐格将供奉扭转成了七三分成。总算占得上风的卡拉布悠哉地作为假教母生活着，直到她发现艾伐格竟然挪用了她的供奉，偷偷娶了三个老婆还生了四个儿子。面对欺骗，卡拉布并不生气，她深情地告诉艾伐格，自己深知前往东方只是个虚无缥缈的梦想，金钱于她无用，不如留给艾伐格，只希望能与艾伐格一家人共进晚餐，共同商讨未来的欺诈事业。 \n意外发现卡拉布终于懂事了，艾伐格十分开心，邀请她前来赴宴。晚餐临近尾声，卡拉布忽然变脸，在她的一声令下，附近的村民、她忠诚的信徒们忽然冲进来，手持农具和厨具将巫师一家八口打了个半死，家中值钱的东西被一扫而空。“想骗我还嫩了点”——卡拉布心满意足离开，尚且未注意到自己额头上小小的黑色三角…...",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_148398_UnlockDesc|同调率等级达到7"
  },
  [148401] = {
    ID = 148401,
    CnID = "唤醒体故事@卡拉布·故事四",
    BaseSortID = 306,
    ActorIndex = 77921,
    Title = "AwakerStory_148401_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_148401_Content|你试过说谎吗？第一句谎言出口的时候，总是伴随着磕绊的唇舌、几乎跃出喉咙的心跳和掌心的汗水，连和暖的日光也化为令人头晕目眩的炫光。 而当谎言重复一万次，恐惧便会消失。说出口的话语会变得流畅，思路日益清明，微笑也固化为自然。 扮演仙女，扮演教母，扮演某位掌权者的亲眷，她早已熟稔自己捏造的千万重身份，习惯于将自我隐藏在谎言之后，直至自身也化为谎言的一部分。 而最初那只野兔，依然藏身于回忆里夕阳映照的小小的种植园中。 在冰消雪融的夜里，悄悄地探出头来。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {9},
    UnlockDesc = "AwakerStory_148401_UnlockDesc|同调率等级达到9"
  },
  [148994] = {
    ID = 148994,
    CnID = "唤醒体故事@本源奥吉尔·简介",
