    ActorIndex = 94451,
    Title = "AwakerStory_148994_Title|基础资料",
    StoryType = 1,
    Content = "AwakerStory_148994_Content|纵然身形依旧，但人们一眼就看得出他和自己熟知的那名小小骑士之间的差异。\n原本澄澈的双眼不再明亮，洁白的衣衫也染了污浊，更不必说他总是刻意地与所有人保持距离。\n但无需恐惧，在那可怖的黑色淤泥之下，仍是那颗你熟悉的、为忠贞正义而跳动的心。\n尽管曾一度遗忘，但他最终捡起了那些骑士的誓词。\n他将继续抗争——与他体内的另一个声音抗争，与一切伤害他珍重之物的存在抗争。",
    ConditionType = "Awaker_Level",
    ConditionPara = {1},
    UnlockDesc = "AwakerStory_148994_UnlockDesc|唤醒体等级达到1级"
  },
  [149052] = {
    ID = 149052,
    CnID = "唤醒体故事@本源奥吉尔·故事一",
    BaseSortID = 308,
    ActorIndex = 94451,
    Title = "AwakerStory_149052_Title|故事·一",
    StoryType = 2,
    Content = "AwakerStory_149052_Content|亲爱的读者们，这是一篇后记，更是我的忏悔书。\n为了完成这部旧式的古典骑士小说，我斥巨资拍得了那顶神秘的头盔，据说它不属于任何一个有历史可查的国度。如您所见，托它的福，我的灵感不断，仿佛真的看到了一片辽阔宏大的古战场，身披铠甲的骑士们正刀兵相向。我依靠这些奇妙的幻觉，完成了这部我心中最完美的作品。\n可我未曾想过，这件古董在赋予我灵感的同时，竟暗藏着一个恐怖的恶魔。\n读者们，你们可以试着想象一下，有一个声音，混沌，持续，日夜不息。再想象你的四肢开始不受控，意识也频频断片——不，那不是断片，更像是意志脱离了躯体，你清楚自己在做什么，却只能旁观......可那明明是我的身体。\n就在昨夜，在我刚刚完成这本小说之际，我再次听见了祂。\n随后，该死，我真不愿回想起那些画面——\n我犯下了无法挽回的罪孽，报纸会比这本书更早地告诉你们......\n祂、又在，又开始——\n（字迹歪扭）\n不不不不不不不不，我不能再——\n......\n\n（字迹恢复清晰）\n令人惊讶，祂停了，像是什么东西压住了祂，我不知道那是什么，但我要感谢它的抗争。\n或许是神明在给予我最后的机会，让我不至于彻底堕为魔鬼。\n\n我的枪里已填满了子弹。\n愿上帝宽恕我。\n\n\n——节选自作家克拉克·齐罗斯绝笔作《无影的骑士》后记",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {3},
    UnlockDesc = "AwakerStory_149052_UnlockDesc|同调率等级达到3"
  },
  [149051] = {
    ID = 149051,
    CnID = "唤醒体故事@本源奥吉尔·故事二",
    BaseSortID = 309,
    ActorIndex = 94451,
    Title = "AwakerStory_149051_Title|故事·二",
    StoryType = 2,
    Content = "AwakerStory_149051_Content|弥萨格曾发生过一起惊动全校的灵异事件。以下为校园记者汉娜整理的采访实录：\n「夜深人静的时候，图书馆里有窸窸窣窣的响动……我不敢去看。直到第二天早上，我发现里面的书全被摆得\n整整齐齐，比我自己整理得还好！」 ——校图书馆管理员\n「不觉得最近校园干净了不少吗？难道晚上有会清理垃圾的幽灵？」\n——某实践课老师\n「出任务的时候，总感觉后面有人跟着……有时会听到激烈交锋的声音，等我回头，只剩一地融蚀怪物的残骸。」——某新手调查员\n几个胆大的学生为此自发组成了调查小队，用一晚的睡眠换来了答案。\n一切的始作俑者承认了自己的「罪行」，也诚挚地为引发恐慌一事道了歉。然而面对随之而来的感谢，他却显得有些局促。用他自己的话说，「只是闲不下来而已。」\n对此，校心理教师茜尔维娅给出了她的诊断：「作为一名本心善良的好孩子，他对过去的事抱有太强的愧疚，久而久之，便成了根深蒂固的不配得感——来自他人太过直白的好意，反而会让他更难受呢。」\n这一事件轻巧地落了幕，「无形幽灵」的传说却由此流传开来。师生们都心照不宣地不去点明他的身份，只是渐渐地，大家都知道了，这名「幽灵」不过是想帮大家的忙而已。\n大家似乎都明白，对于这位不愿被看见的少年来说，最好的谢意，就是让这个秘密继续只属于他一个人。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {5},
    UnlockDesc = "AwakerStory_149051_UnlockDesc|同调率等级达到5"
  },
  [149065] = {
    ID = 149065,
    CnID = "唤醒体故事@本源奥吉尔·故事三",
    BaseSortID = 310,
    ActorIndex = 94451,
    Title = "AwakerStory_149065_Title|故事·三",
    StoryType = 2,
    Content = "AwakerStory_149065_Content|他也曾像睡前童话里所写的那般，踏上过自己的旅途。\n可他并非歌颂正义的骑士，世上亦不再存在等候拯救的公主。\n他杀死的，也不是可怖的邪龙，而是许多哀嚎逃窜的、手无寸铁的平民。\n「少年骑士斩杀了邪恶的巫师，击溃了顽固的敌军，烧毁了怪物的堡垒……\n他很英勇，很强大，战无不胜。在这条不知尽头的路上，只留下了一道绵长的血痕。」\n如果世上存在分不清幻梦与真实的吟游诗人，一定会将这段经历粉饰成这般模样。\n可故事的主人公其实是清醒的，那双眼中从未映出过虚假之物。\n他知道，他的枪尖穿透了老者的胸膛，黑泥吞噬了早已投降的败兵，那栋精致的、属于某户人家的小屋，也在他经过后化为了灰烬......只因这些皆与夺走他所守护之物的人有关。\n他知道，他从未身处在童话中，那些浪漫的幻想早已随着故国彻底死去，或许他在那一刻得以长大，或许仍是不成熟的稚子。\n直到他最终幡然醒悟，为了素不相识的陌生人们奉献生命时，他忽然在自己的泪水中，看见了绝不该存在的幻影。\n「奥吉尔，我对你很失望，你是空有虚衔的，最不称职的骑士。」\n「公主」的面容仿佛被蒙上了纱，但她的声音却异常清晰，远比世界上任何刀剑更锋利，剜着他的心。\n这道残忍的幻觉，时至今日仍是折磨他的梦魇，并未随着身死而消弭。\n他将永世活在辜负誓言的悔恨之中。",
    ConditionType = "AwakerFavorabilityLevel",
    ConditionPara = {7},
    UnlockDesc = "AwakerStory_149065_UnlockDesc|同调率等级达到7"
  },
  [149064] = {
