    Title = "AwakerStory_149064_Title|故事·四",
    StoryType = 2,
    Content = "AwakerStory_149064_Content|象征罪恶的深黑污泥仍在他的体内翻涌，妄图再一次掌控这具躯体，他需要不断紧抓那脆弱的丝线，才不会败下阵来。\n而他为自己重新找到的——值得捍卫之物，便成为了维系理智的唯一的锚。\n他再无法回到家乡，但弥萨格成为了他新的城堡。\n他再无法护卫公主，但命运还会创造新的相遇。\n在无人见证之地，少年单膝跪地，一只手覆在冰冷的胸口，向并不身处于此的主君宣告。\n「我会谨遵您的指令，永远守护您与您的世界，哪怕燃尽生命，哪怕透支灵魂。」\n「......这便是，我重新背负起的誓言。」",
    ConditionType = "AwakerFavorabilityLevel",
